// Erzeugt von scripts/build-data.mjs – nicht von Hand bearbeiten (Quelle: data/src).
window.MEDI_DETAILS = Object.assign(window.MEDI_DETAILS || {}, {"tacrolimus":{"wirkmechanismus":"Bremst die Immunabwehr, damit ein transplantiertes Organ nicht abgestossen wird bzw. die Hautentzündung abklingt. Tacrolimus bindet in T-Lymphozyten an das Protein FKBP12; dieser Komplex hemmt das Enzym Calcineurin. Dadurch wird die Bildung von Interleukin-2 und weiteren Botenstoffen blockiert und die Aktivierung der T-Zellen verhindert. Abgebaut wird es über CYP3A4; die Blutspiegel schwanken stark und müssen überwacht werden.","nebenwirkungen":{"sehrHaeufig":["Zittern (Tremor), Kopfschmerzen, Schlafstörungen","Hyperglykämie, Diabetes mellitus, Hyperkaliämie","Bluthochdruck","Nierenfunktionsstörung","Durchfall, Übelkeit","Salbe: Brennen und Juckreiz an der Auftragsstelle"],"haeufig":["Blutarmut, Leukopenie, Thrombozytopenie","Magnesium-, Kalium- oder Calciummangel, erhöhte Blutfette","Krampfanfälle, Kribbeln, Bewusstseinsstörungen","Sehstörungen, Ohrensausen","Herzrasen, Durchblutungsstörungen des Herzens","Akutes Nierenversagen","Erhöhte Leberwerte, Gallenstau","Haarausfall, Juckreiz, Ausschlag","Salbe: Rötung, Wärmegefühl oder Kribbeln an der Auftragsstelle; Hautinfektionen (Herpes, Follikulitis); Gesichtsrötung nach Alkohol"],"gelegentlich":["Herzinsuffizienz, Kammerrhythmusstörungen","Enzephalopathie, Lähmungen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Hämolytisch-urämisches Syndrom"],"selten":["Thrombotisch-thrombozytopenische Purpura","Hypertrophe Kardiomyopathie","Toxische epidermale Nekrolyse"],"sehrSelten":["Hörverlust","Stevens-Johnson-Syndrom (schwere Hautreaktion)","Leberversagen"],"unbekannt":["Infektionen (Viren, Bakterien, Pilze), auch opportunistische wie BK-Virus-Nephropathie oder PML (Hirninfektion)","QT-Verlängerung, Torsade de pointes","Posteriores reversibles Enzephalopathie-Syndrom (PRES)","Agranulozytose, Aplasie der roten Blutzellen","Lymphome und andere Krebserkrankungen, Hautkrebs","Sehnervschädigung (Optikusneuropathie)"]},"schwangerschaft":"Kapseln: nur wenn unbedingt nötig und unter enger Überwachung von Mutter und Kind (Frühgeburt, erhöhtes Kalium und Nierenfunktionsstörung beim Neugeborenen möglich). Salbe: nur wenn eindeutig erforderlich.","stillzeit":"Tacrolimus geht in die Muttermilch über; gemäss Fachinformation während der Behandlung nicht stillen.","hinweise":["Präparate (Prograf, Advagraf, Envarsus) sind nicht direkt austauschbar – nur auf ärztliche Anordnung wechseln; regelmässig Blutspiegel, Nierenwerte, Kalium und Blutzucker kontrollieren.","Kapseln auf nüchternen Magen (1 Stunde vor oder 2–3 Stunden nach dem Essen) einnehmen; keine Grapefruit.","Sonne und Solarium meiden, guter Sonnenschutz; regelmässige Hautkontrollen.","Salbe: nach Alkohol kann das Gesicht stark rot werden; Haut nicht luftdicht abdecken."],"darreichung":["Kapseln","Retardkapseln","Retardtabletten","Granulat zur Herstellung einer Suspension","Infusionskonzentrat","Salbe"]},"tadalafil":{"wirkmechanismus":"Verbessert bei sexueller Erregung den Bluteinstrom in den Penis, entspannt die Muskulatur von Prostata und Blasenhals und erweitert die Lungengefässe. Tadalafil hemmt selektiv die Phosphodiesterase 5, die den Botenstoff cGMP abbaut; dadurch verstärkt sich die gefässerweiternde Wirkung von Stickstoffmonoxid in Schwellkörpern, Prostata, Blase und Lungenarterien. Wegen der langen Halbwertszeit von etwa 17,5 Stunden hält die Wirkung bis zu 36 Stunden an.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen und Gesichtsrötung (bei Lungenhochdruck-Dosierung sehr häufig, sonst häufig)"],"haeufig":["Verdauungsbeschwerden (Dyspepsie), Reflux","Rückenschmerzen, Muskelschmerzen, Gliederschmerzen","Verstopfte Nase","Übelkeit (bei Lungenhochdruck-Dosierung)"],"gelegentlich":["Überempfindlichkeitsreaktionen, Hautausschlag","Schwindel","Verschwommenes Sehen, Augenschmerzen","Ohrensausen (Tinnitus)","Herzrasen, Herzklopfen","Blutdruckabfall oder Blutdruckanstieg","Atemnot, Nasenbluten","Bauchschmerzen, Erbrechen","Blut im Urin, verlängerte Erektionen","Brustschmerzen, Wassereinlagerungen, Müdigkeit"],"selten":["Angioödem, Gesichtsschwellung, Nesselsucht","Schlaganfall, TIA, Ohnmacht, Krampfanfälle, vorübergehender Gedächtnisverlust","Herzinfarkt, plötzlicher Herztod","NAION (Durchblutungsstörung des Sehnervs), Netzhautgefässverschluss, Gesichtsfeldausfälle","Plötzlicher Hörverlust","Priapismus (schmerzhafte Dauererektion über 4 Stunden)"],"unbekannt":["Stevens-Johnson-Syndrom, exfoliative Dermatitis (schwere Hautreaktionen)","Instabile Angina pectoris, ventrikuläre Herzrhythmusstörungen","Chorioretinopathia centralis serosa (Flüssigkeit unter der Netzhaut)"]},"schwangerschaft":"Vorsichtshalber nicht anwenden (Lungenhochdruck: keine ausreichenden Daten). Für Frauen ist die Behandlung von Erektionsstörungen nicht vorgesehen.","stillzeit":"Nicht anwenden – Tadalafil geht im Tierversuch in die Milch über.","hinweise":["Wirkt bis zu 36 Stunden: in dieser Zeit und bis 48 Stunden nach der letzten Dosis keine Nitrate oder «Poppers» – lebensbedrohlicher Blutdruckabfall.","Eine Erektion, die länger als 4 Stunden anhält, ist ein Notfall – sofort ärztliche Hilfe holen.","Einnahme unabhängig von den Mahlzeiten; grössere Mengen Alkohol meiden.","Bei plötzlicher Sehverschlechterung oder plötzlichem Hörverlust sofort absetzen und ärztlich abklären lassen."],"darreichung":["Filmtabletten"]},"tafamidis":{"wirkmechanismus":"Verhindert, dass das Transporteiweiss Transthyretin zerfällt und sich als Amyloid in Herz und Nerven ablagert. Tafamidis bindet selektiv an die Thyroxin-Bindungsstellen des Transthyretin-Tetramers und stabilisiert es. Dadurch wird der Zerfall in einzelne Untereinheiten (Monomere) gebremst, der geschwindigkeitsbestimmende Schritt der Amyloidbildung. Bereits abgelagertes Amyloid wird nicht abgebaut.","nebenwirkungen":{"sehrHaeufig":["Harnwegsinfekte","Scheideninfektionen","Durchfall","Oberbauchschmerzen"]},"schwangerschaft":"Nicht anwenden. Frauen im gebärfähigen Alter müssen während der Behandlung und bis 1 Monat danach zuverlässig verhüten.","stillzeit":"Nicht anwenden, da ein Risiko für das gestillte Kind nicht ausgeschlossen werden kann.","hinweise":["Kapseln ganz schlucken, nicht zerkauen oder zerbrechen; mit oder ohne Essen.","Die Kapseln zu 20 mg (Tafamidis-Meglumin) und zu 61 mg (Tafamidis) sind nicht Milligramm für Milligramm austauschbar.","Langzeittherapie – nicht eigenmächtig absetzen."],"darreichung":["Weichkapseln"]},"tafasitamab":{"wirkmechanismus":"Markiert bösartige B-Zellen, damit das Immunsystem sie zerstört. Tafasitamab ist ein humanisierter monoklonaler Antikörper gegen CD19, ein Oberflächenprotein auf B-Zellen und den meisten B-Zell-Lymphomen. Sein Fc-Teil ist so verändert, dass er Immunzellen besonders stark bindet: Er löst antikörperabhängige zelluläre Zytotoxizität (ADCC) und Phagozytose (ADCP) aus und kann den programmierten Zelltod (Apoptose) einleiten. Lenalidomid aktiviert NK-Zellen und verstärkt so die Wirkung.","nebenwirkungen":{"sehrHaeufig":["Infektionen (z. B. der Atem- und Harnwege)","Neutropenie, Thrombozytopenie, Anämie (Blutbildveränderungen)","Hypokaliämie (Kaliummangel), Appetitlosigkeit","Durchfall, Verstopfung, Übelkeit, Erbrechen, Bauchschmerzen","Hautausschlag","Husten, Atemnot","Rückenschmerzen, Muskelkrämpfe","Müdigkeit, Fieber, Ödeme (Wassereinlagerungen)"],"haeufig":["Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Sepsis (Blutvergiftung)","Infusionsbedingte Reaktionen","Hypomagnesiämie (Magnesiummangel)","Erhöhte Leberwerte und Bilirubin","Kopfschmerzen, Missempfindungen, Geschmacksstörungen","Basalzellkarzinom (heller Hautkrebs)"]},"schwangerschaft":"Keine Daten; kann beim Ungeborenen die B-Zellen vermindern. Die Kombination mit Lenalidomid ist in der Schwangerschaft kontraindiziert; zuverlässig verhüten während und mindestens 3 Monate nach der Behandlung.","stillzeit":"Während und mindestens 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Vor der Infusion werden Medikamente gegen Infusionsreaktionen gegeben.","Fieber, Schüttelfrost, Halsschmerzen, Blutungszeichen oder blaue Flecken sofort melden.","Für Lenalidomid gilt dessen Schwangerschaftsverhütungsprogramm."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"tafluprost":{"wirkmechanismus":"Senkt den Augeninnendruck, indem es den Abfluss des Kammerwassers verbessert. Tafluprost ist eine Vorstufe (Isopropylester), die beim Durchtritt durch die Hornhaut zur wirksamen Tafluprostsäure gespalten wird. Diese stimuliert selektiv den Prostaglandin-FP-Rezeptor und steigert den Kammerwasserabfluss über den uveoskleralen Weg. Die Drucksenkung setzt nach 2–4 Stunden ein und reicht für eine Anwendung pro Tag.","nebenwirkungen":{"haeufig":["Augenrötung (konjunktivale Hyperämie)","Augenjucken, Augenreizung, Augenschmerzen","Veränderungen der Wimpern (länger, dichter, zahlreicher)","Trockenes Auge, Fremdkörpergefühl","Rötung der Augenlider","Verschwommenes Sehen, Lichtscheu","Kopfschmerzen"],"gelegentlich":["Punktförmige Hornhautentzündung (Keratitis)","Lidrandentzündung (Blepharitis), Bindehautschwellung, Augenausfluss","Allergische Bindehautentzündung","Pigmentierung der Bindehaut, verstärkte Behaarung der Lider"],"unbekannt":["Dauerhaft stärkere Braunfärbung der Iris","Eingesunkene Lidfurche, dunklere Lidhaut","Regenbogen- oder Aderhautentzündung (Iritis, Uveitis)","Makulaödem (Schwellung der Netzhautmitte)","Verschlechterung von Asthma, Atemnot"]},"schwangerschaft":"Nicht anwenden, ausser wenn klar notwendig; Frauen im gebärfähigen Alter dürfen es nur mit zuverlässiger Verhütung anwenden.","stillzeit":"Während der Stillzeit nicht anwenden, da ein Übergang in die Muttermilch nicht ausgeschlossen ist.","hinweise":["Einzeldosisbehälter nach dem Öffnen sofort verwenden und den Rest verwerfen.","Einmal täglich, am besten abends, eintropfen; häufigere Anwendung kann die Wirkung abschwächen.","Andere Augentropfen mit mindestens 5 Minuten Abstand anwenden.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen."],"darreichung":["Augentropfen in Einzeldosisbehältern (ohne Konservierungsmittel)"]},"tafluprost-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck über zwei sich ergänzende Wege. Tafluprost ist eine Vorstufe, die im Auge zur Tafluprostsäure gespalten wird; diese stimuliert den Prostaglandin-FP-Rezeptor und verbessert den Abfluss des Kammerwassers über den uveoskleralen Weg. Timolol ist ein nicht selektiver Betablocker und vermindert die Bildung von Kammerwasser im Ziliarkörper. Timolol gelangt teilweise in den Körper und kann Puls, Blutdruck und Atemwege beeinflussen.","nebenwirkungen":{"haeufig":["Augenrötung (konjunktivale Hyperämie)"],"gelegentlich":["Augenjucken, Augenschmerzen, Augenreizung, Fremdkörpergefühl","Verschwommenes Sehen, trockenes Auge"],"unbekannt":["Dauerhaft stärkere Braunfärbung der Iris, Wimpernveränderungen, dunklere Lidhaut, eingesunkene Lidfurche","Makulaödem, Regenbogenhautentzündung (Iritis, Uveitis)","Langsamer Puls, Herzrhythmusstörungen, Blutdruckabfall, Verschlechterung einer Herzinsuffizienz","Atemnot, Verkrampfung der Atemwege (Bronchospasmus), vor allem bei Asthma","Kopfschmerzen, Schwindel, Müdigkeit, Depression","Kalte Hände und Füsse, Raynaud-Syndrom","Verschleierung einer Unterzuckerung"]},"schwangerschaft":"Nicht anwenden, ausser wenn klar notwendig; Frauen im gebärfähigen Alter nur mit zuverlässiger Verhütung. Bei Anwendung bis zur Geburt das Neugeborene auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Ein Risiko für den Säugling kann nicht ausgeschlossen werden; Stillen während der Behandlung nicht empfohlen.","hinweise":["Einzeldosisbehälter nach dem Öffnen sofort verwenden und den Rest verwerfen.","Nach dem Eintropfen den inneren Augenwinkel 2 Minuten leicht zudrücken – das verringert Wirkungen auf Herz und Atemwege.","Vor Operationen und bei anderen Ärztinnen und Ärzten angeben, dass Betablocker-Augentropfen verwendet werden.","Nicht eigenmächtig absetzen; den Augeninnendruck regelmässig kontrollieren lassen."],"darreichung":["Augentropfen in Einzeldosisbehältern (ohne Konservierungsmittel)"]},"talazoparib":{"wirkmechanismus":"Verhindert, dass Krebszellen Schäden an ihrem Erbgut reparieren. Talazoparib hemmt die Enzyme PARP-1 und PARP-2 und hält sie besonders stark an der DNA fest («PARP-Trapping»), was die Zellteilung blockiert. Tumorzellen mit BRCA-Mutation oder anderen Defekten der DNA-Reparatur können die entstehenden Schäden nicht beheben und sterben ab.","nebenwirkungen":{"sehrHaeufig":["Anämie (Blutarmut)","Thrombozytopenie, Neutropenie","Müdigkeit","Übelkeit, Erbrechen, Durchfall","Bauchschmerzen","Haarausfall","Kopfschmerzen, Schwindel","Appetitlosigkeit"],"haeufig":["Geschmacksstörungen","Mundschleimhautentzündung","Verdauungsbeschwerden"],"gelegentlich":["Myelodysplastisches Syndrom / akute myeloische Leukämie (Blutkrebs)"]},"schwangerschaft":"Nicht anwenden. Frauen verhüten während und bis mindestens 7 Monate nach der letzten Dosis; Männer mit Partnerin im gebärfähigen Alter verwenden Kondome bis mindestens 4 Monate danach.","stillzeit":"Während der Behandlung und mindestens 1 Monat nach der letzten Dosis nicht stillen.","hinweise":["Einmal täglich, mit oder ohne Essen; Kapsel ganz schlucken.","Blutbild vor Beginn und monatlich kontrollieren lassen.","Müdigkeit, Blässe, Fieber oder Blutungszeichen melden."],"darreichung":["Hartkapseln"]},"talimogen-laherparepvec":{"wirkmechanismus":"Ein abgeschwächtes, gentechnisch verändertes Herpesvirus wird direkt in Melanomknoten gespritzt, vermehrt sich in den Krebszellen und bringt sie zum Platzen. Durch Entfernen der Gene ICP34.5 und ICP47 vermehrt sich das Virus bevorzugt in Tumorzellen und wird für das Immunsystem besser erkennbar; zusätzlich bildet es den Botenstoff GM-CSF. Freigesetzte Tumorantigene und GM-CSF lösen eine Immunantwort gegen den Tumor aus, die auch nicht gespritzte Ableger erreichen kann.","nebenwirkungen":{"sehrHaeufig":["Grippeähnliche Beschwerden: Fieber, Schüttelfrost, Müdigkeit","Schmerzen und Reaktionen an der Injektionsstelle","Übelkeit, Erbrechen, Durchfall, Verstopfung","Kopfschmerzen","Muskel- und Gelenkschmerzen","Periphere Ödeme (Wassereinlagerungen)"],"haeufig":["Zellulitis (bakterielle Hautinfektion)","Lippenherpes","Vitiligo (weisse Hautflecken)","Tumorschmerzen","Atemnot","Tiefe Venenthrombose"],"gelegentlich":["Plasmozytom an der Injektionsstelle","Glomerulonephritis (Nierenentzündung)","Einengung der Atemwege durch Tumorschwellung"],"unbekannt":["Ausgedehnte (disseminierte) Herpesinfektion bei geschwächtem Immunsystem","Herpesinfektion des Auges (Keratitis)"]},"schwangerschaft":"Nicht anwenden; eine Herpesinfektion des ungeborenen Kindes ist möglich. Frauen im gebärfähigen Alter verhüten während der Behandlung.","stillzeit":"Es ist nicht bekannt, ob das Virus in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Injektionsstellen mindestens 1 Woche nach jeder Behandlung (bei nässenden Stellen länger) luft- und wasserdicht abdecken; Verbände in einem verschlossenen Beutel entsorgen.","Injektionsstellen nicht berühren oder kratzen; Kontaktpersonen tragen beim Verbandwechsel Handschuhe.","Beim Geschlechtsverkehr Kondome verwenden.","Herpesähnliche Beschwerden (Bläschen, Augenschmerzen, Kopfschmerzen, Verwirrtheit) bei sich oder Kontaktpersonen ärztlich melden."],"darreichung":["Injektionslösung (Injektion in den Tumor)"]},"talquetamab":{"wirkmechanismus":"Verbindet körpereigene Abwehrzellen (T-Zellen) mit Myelomzellen, damit diese zerstört werden. Talquetamab ist ein bispezifischer IgG4-Antikörper gegen GPRC5D, einen Rezeptor, der auf Myelomzellen reichlich vorkommt, und gegen CD3 auf T-Zellen. Die aktivierten T-Zellen setzen Zytokine und zytotoxische Proteine frei und töten die GPRC5D-tragenden Zellen. Weil GPRC5D auch in Zellen von Haut, Nägeln und Zunge vorkommt, sind Geschmacks-, Haut- und Nagelveränderungen typisch.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungs-Syndrom","Geschmacksstörungen, Mundtrockenheit, Schluckbeschwerden","Gewichtsverlust, Appetitlosigkeit","Nagelveränderungen (Verfärbung, Ablösung)","Hautveränderungen (Abschuppung, trockene Haut, Ausschlag, Juckreiz)","Neutropenie, Anämie, Thrombozytopenie, Lymphopenie","Infektionen (bakteriell, viral, durch Pilze)","Müdigkeit, Fieber"],"haeufig":["ICANS (immuneffektorzell-assoziiertes Neurotoxizitätssyndrom)","Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Sepsis (Blutvergiftung)","Erhöhte Leberwerte"]},"schwangerschaft":"In der Schwangerschaft nicht empfohlen (mögliche Schädigung des Ungeborenen, Antikörpermangel). Frauen verhüten während und mindestens 3 Monate nach der letzten Dosis.","stillzeit":"Während und mindestens 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Die Aufbaudosen werden unter Überwachung, meist im Spital, gegeben; Fieber, Schüttelfrost, Atemnot, Schwindel oder Verwirrtheit sofort melden.","Geschmacksveränderungen, Schluckbeschwerden oder Gewichtsverlust melden; eine Ernährungsberatung kann helfen.","Nach den Aufbaudosen und bei neurologischen Beschwerden kein Fahrzeug lenken.","Patientenkarte immer mitführen."],"darreichung":["Injektionslösung zur subkutanen Anwendung"]},"tamoxifen":{"wirkmechanismus":"Verhindert, dass Östrogen das Wachstum von Brustkrebszellen anregt. Tamoxifen bindet an den Östrogenrezeptor und wirkt im Brustgewebe als Gegenspieler, an Gebärmutter, Knochen und Blutgerinnung dagegen teilweise östrogenartig. Es ist ein Prodrug: Über CYP2D6 und CYP3A4 entsteht der hauptsächlich wirksame Metabolit Endoxifen. Bei stark verminderter CYP2D6-Aktivität (genetisch oder durch Hemmer) kann die Wirkung schwächer sein.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Übelkeit","Flüssigkeitseinlagerungen (Ödeme)","Scheidenblutungen oder Ausfluss","Hautausschlag","Müdigkeit"],"haeufig":["Thrombosen und Lungenembolie","Ischämischer Schlaganfall","Grauer Star (Katarakt), Netzhautveränderungen","Gebärmuttermyome, Polypen der Gebärmutterschleimhaut","Erhöhte Triglyceride, Fettleber, erhöhte Leberwerte","Kopfschmerzen, Wadenkrämpfe, Muskelschmerzen","Haarausfall","Anämie, Überempfindlichkeitsreaktionen"],"gelegentlich":["Gebärmutterkrebs (Endometriumkarzinom)","Hyperkalzämie bei Knochenmetastasen","Interstitielle Pneumonitis","Leukopenie, Thrombozytopenie","Pankreatitis"],"selten":["Uterussarkom","Agranulozytose, Neutropenie","Sehnerventzündung","Hepatitis, Cholestase, Leberversagen","Stevens-Johnson-Syndrom und andere schwere Hautreaktionen","Angioödem","Tumorschmerz zu Beginn (Flare)"],"sehrSelten":["Kutaner Lupus erythematodes"]},"schwangerschaft":"Kontraindiziert. Vor Beginn Schwangerschaft ausschliessen; während und noch mehrere Monate nach der Behandlung zuverlässig, aber nicht hormonell verhüten.","stillzeit":"Nicht stillen; Tamoxifen kann zudem die Milchbildung hemmen.","hinweise":["Täglich zur gleichen Zeit einnehmen, meist über 5–10 Jahre; nicht eigenmächtig absetzen.","Ungewöhnliche Blutungen aus der Scheide, Beinschwellung, Atemnot oder Sehstörungen sofort melden; jährliche gynäkologische Kontrolle.","Vor neuen Medikamenten, besonders Antidepressiva, Rücksprache halten (Paroxetin, Fluoxetin meiden)."],"darreichung":["Tabletten","Filmtabletten"]},"tamsulosin":{"wirkmechanismus":"Erleichtert das Wasserlösen, indem es die Muskulatur in Prostata, Blasenhals und Harnröhre entspannt. Tamsulosin blockiert bevorzugt die Alpha-1A- und Alpha-1D-Adrenozeptoren, die in Prostata und Blase überwiegen; dadurch sinkt der Widerstand beim Harnabfluss, der Harnstrahl wird kräftiger und Reizbeschwerden wie häufiger Harndrang nehmen ab. Die Prostata wird dabei nicht kleiner. Wegen der Bevorzugung der Rezeptoren im Harntrakt sinkt der Blutdruck meist nur wenig.","nebenwirkungen":{"haeufig":["Schwindel","Ejakulationsstörungen (verminderter oder fehlender Samenerguss, Samenerguss in die Blase)"],"gelegentlich":["Kopfschmerzen","Herzklopfen","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen)","Schnupfen, verstopfte Nase","Verstopfung, Durchfall, Übelkeit, Erbrechen","Hautausschlag, Juckreiz, Nesselsucht","Asthenie (Schwäche)"],"selten":["Synkope (Ohnmacht)","Angioödem (Schwellung von Gesicht, Lippen, Zunge)"],"sehrSelten":["Priapismus (schmerzhafte Dauererektion)","Stevens-Johnson-Syndrom (schwere Hautreaktion)"],"unbekannt":["Intraoperatives Floppy-Iris-Syndrom bei Katarakt- oder Glaukomoperation","Verschwommenes Sehen, Sehstörungen","Nasenbluten","Mundtrockenheit","Erythema multiforme, exfoliative Dermatitis (schwere Hautreaktionen)"]},"schwangerschaft":"Nicht für Frauen bestimmt.","stillzeit":"Nicht für Frauen bestimmt.","hinweise":["Einmal täglich unzerkaut schlucken; Retardkapseln nach dem Frühstück, Retardtabletten (Pradif T) unabhängig von den Mahlzeiten.","Vor allem zu Beginn kann Schwindel auftreten: langsam aufstehen und vorsichtig sein beim Autofahren.","Vor einer Augenoperation am grauen oder grünen Star die Einnahme angeben – auch wenn Tamsulosin früher eingenommen wurde.","In der Kombination mit Dutasterid (Duodart) gelten zusätzlich die Hinweise zu Dutasterid."],"darreichung":["Retardtabletten","Retardkapseln"]},"tapentadol":{"wirkmechanismus":"Lindert starke Schmerzen über zwei sich ergänzende Wege in einem Wirkstoff. Tapentadol ist ein Agonist am μ-Opioidrezeptor und hemmt gleichzeitig die Wiederaufnahme von Noradrenalin, wodurch absteigende schmerzhemmende Nervenbahnen im Rückenmark verstärkt werden. Die Opioidwirkung ist dadurch für eine vergleichbare Schmerzlinderung geringer, was sich etwa in weniger Magen-Darm-Beschwerden zeigen kann. Der Abbau erfolgt überwiegend durch Glucuronidierung ohne wirksame Abbauprodukte und mit geringer Beteiligung von CYP-Enzymen.","nebenwirkungen":{"sehrHaeufig":["Schwindel, Schläfrigkeit, Kopfschmerzen","Übelkeit","Obstipation (Verstopfung)"],"haeufig":["Appetitlosigkeit","Angst, gedrückte Stimmung, Schlafstörungen, Unruhe","Konzentrationsstörungen, Zittern, Muskelzuckungen","Hitzegefühl (Flushing)","Atemnot","Erbrechen, Durchfall, Verdauungsbeschwerden","Juckreiz, Schwitzen, Hautausschlag","Müdigkeit, Schwäche, Wassereinlagerungen"],"gelegentlich":["Verwirrtheit, Euphorie, Wahrnehmungsstörungen","Bewusstseinsstörungen, Ohnmacht","Sehstörungen","Herzrasen oder langsamer Puls, Blutdruckabfall","Nesselsucht","Sexuelle Funktionsstörungen","Entzugssymptome"],"selten":["Anaphylaxie, Angioödem (schwere allergische Reaktionen)","Abhängigkeit","Krampfanfälle","Atemdepression (abgeschwächte Atmung)"],"unbekannt":["Delir","Serotonin-Syndrom (in Kombination mit serotonergen Mitteln)"]},"schwangerschaft":"Nur wenn der Nutzen das Risiko klar überwiegt. Längere Anwendung kann beim Neugeborenen ein Entzugssyndrom, Anwendung unter der Geburt eine Atemdepression auslösen.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern.","Kein Alkohol; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Nach längerer Anwendung nicht abrupt absetzen, sondern schrittweise reduzieren (Entzugssymptome)."],"darreichung":["Filmtabletten","Retardtabletten"]},"tarlatamab":{"wirkmechanismus":"Verbindet körpereigene Abwehrzellen (T-Zellen) mit Tumorzellen, damit diese zerstört werden. Tarlatamab ist ein bispezifisches Antikörperkonstrukt mit verlängerter Halbwertszeit, das an DLL3 auf kleinzelligen Lungenkrebszellen und an CD3 auf T-Zellen bindet. Die aktivierten T-Zellen setzen Zytokine und zytotoxische Proteine frei und töten die DLL3-tragenden Tumorzellen. Auf gesunden Zellen kommt DLL3 an der Oberfläche kaum vor.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungs-Syndrom","Müdigkeit, Fieber","Geschmacksstörungen, Appetitlosigkeit","Verstopfung, Übelkeit","Muskel- und Knochenschmerzen","Anämie, Lymphopenie (Blutbildveränderungen)","Hyponatriämie (Natriummangel)","Erhöhte Leberwerte"],"haeufig":["ICANS (immuneffektorzell-assoziiertes Neurotoxizitätssyndrom: Verwirrtheit, Bewusstseinsstörung)","Neutropenie, Thrombozytopenie","Lungenentzündung, Harnwegsinfekte","Überempfindlichkeits- und Infusionsreaktionen"]},"schwangerschaft":"Kann aufgrund des Wirkmechanismus das Ungeborene schädigen; in der Schwangerschaft nicht empfohlen. Frauen im gebärfähigen Alter verhüten während und 2 Monate nach der letzten Dosis.","stillzeit":"Während und 2 Monate nach der letzten Dosis nicht stillen.","hinweise":["Nach den ersten beiden Infusionen erfolgt eine Überwachung im Spital; danach Anweisungen zur Erreichbarkeit der Klinik genau befolgen.","Fieber, Schwindel, Atemnot, Verwirrtheit, Zittern oder Sprachstörungen sofort melden.","Nach den ersten Dosen und bei neurologischen Beschwerden kein Fahrzeug lenken.","Patientenkarte immer mitführen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"tebentafusp":{"wirkmechanismus":"Lenkt die körpereigenen Abwehrzellen (T-Zellen) gezielt gegen Melanomzellen. Tebentafusp ist ein Fusionsprotein: Ein löslicher T-Zell-Rezeptor erkennt ein Bruchstück des Melanom-Eiweisses gp100, das die Tumorzellen über das Gewebemerkmal HLA-A*02:01 an ihrer Oberfläche zeigen. Der andere Teil bindet an CD3 auf T-Zellen und aktiviert diese unabhängig von ihrer eigenen Spezifität. Die aktivierten T-Zellen setzen Zytokine und zellzerstörende Eiweisse frei und töten die Tumorzellen ab.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungssyndrom (Fieber, Schüttelfrost, Blutdruckabfall)","Hautausschlag, Juckreiz, trockene Haut, Hautrötung","Veränderungen der Haut- und Haarfarbe (Pigmentverlust)","Müdigkeit, Ödeme (Wassereinlagerungen)","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Kopfschmerzen, Schwindel","Erhöhte Leberwerte und Lipase","Gelenk- und Rückenschmerzen"],"haeufig":["Herzrasen (Tachykardie)"],"unbekannt":["Herzrhythmusstörungen (z. B. Vorhofflimmern), QT-Verlängerung","Sauerstoffmangel (Hypoxie)"]},"schwangerschaft":"Nicht anwenden (keine Daten, Schädigung des Kindes durch den Wirkmechanismus möglich). Frauen im gebärfähigen Alter sollen während und mindestens 1 Woche nach der letzten Dosis verhüten.","stillzeit":"Während der Behandlung und mindestens 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Die ersten drei Infusionen erfolgen im Spital mit Überwachung über Nacht.","Fieber, Schüttelfrost, Schwindel oder Atemnot sofort melden (Zytokin-Freisetzungssyndrom).","Ausreichend trinken; neue Hautveränderungen ärztlich zeigen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"technetium-99mtc-oxidronat":{"wirkmechanismus":"Reichert sich dort im Knochen an, wo er besonders stark umgebaut wird, und macht diese Stellen mit einer Gammakamera sichtbar. Oxidronat (Hydroxymethylendiphosphonat) ist ein Bisphosphonat, das nach Markierung mit Technetium-99m an die Oberfläche der Hydroxylapatit-Kristalle des Knochens bindet; die Aufnahme hängt von Durchblutung und Osteoblastenaktivität ab. Der nicht gebundene Anteil wird rasch über die Nieren ausgeschieden. Technetium-99m sendet Gammastrahlen aus und hat eine Halbwertszeit von 6 Stunden.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz, Schwellungen) bis zur Anaphylaxie","Kreislaufreaktionen mit Blutdruckabfall, Schwindel oder Ohnmacht (vasovagale Reaktion)","Übelkeit, Erbrechen","Reaktionen an der Injektionsstelle","Strahlenbelastung: sehr geringes zusätzliches Langzeitrisiko für Krebs oder Erbgutschäden"]},"schwangerschaft":"Nur bei zwingender Indikation (Strahlenbelastung des Ungeborenen); eine mögliche Schwangerschaft vorher ausschliessen.","stillzeit":"Stillen gemäss Anweisung der Nuklearmedizin vorübergehend unterbrechen und die abgepumpte Milch verwerfen.","hinweise":["Zwischen Injektion und Aufnahme (meist 2–4 Stunden) sowie danach viel trinken und häufig die Blase entleeren, um die Strahlenbelastung zu senken.","Schwangerschaft oder Stillen vor der Untersuchung angeben."],"darreichung":["Kit zur Herstellung einer radioaktiven Injektionslösung"]},"technetium-99mtc-sestamibi":{"wirkmechanismus":"Wird vom Herzmuskel im Verhältnis zur Durchblutung aufgenommen und zeigt so schlecht durchblutete Bereiche. Sestamibi ist ein fettlöslicher, positiv geladener Technetium-99m-Komplex, der passiv in die Zellen eindringt und aufgrund des Membranpotentials in den Mitochondrien festgehalten wird. Da er kaum umverteilt wird, kann die Verteilung zum Zeitpunkt der Injektion noch Stunden später aufgezeichnet werden; Bilder nach Belastung und in Ruhe werden verglichen. Mitochondrienreiche Zellen wie Nebenschilddrüsenadenome und manche Tumoren halten ihn länger zurück als das umgebende Gewebe.","nebenwirkungen":{"haeufig":["Metallischer oder bitterer Geschmack direkt nach der Injektion","Geruchsstörungen"],"gelegentlich":["Kopfschmerzen","Brustschmerzen, Angina pectoris","EKG-Veränderungen","Übelkeit","Hautrötung (Flush)"],"selten":["Herzrhythmusstörungen","Schwindel, Blutdruckabfall, Ohnmacht","Überempfindlichkeitsreaktionen (Atemnot, Juckreiz, Hautausschlag, Nesselsucht)","Bauchschmerzen, Erbrechen"],"sehrSelten":["Schwere allergische Reaktionen (Anaphylaxie)","Krampfanfälle kurz nach der Injektion"],"unbekannt":["Strahlenbelastung: sehr geringes zusätzliches Langzeitrisiko für Krebs oder Erbgutschäden"]},"schwangerschaft":"Nur bei zwingender Indikation (Strahlenbelastung des Ungeborenen); eine mögliche Schwangerschaft vorher ausschliessen.","stillzeit":"Geht in die Muttermilch über: Stillen gemäss Anweisung der Nuklearmedizin unterbrechen (meist 24 Stunden) und die abgepumpte Milch verwerfen.","hinweise":["Vor der Untersuchung die Anweisungen zu Nüchternheit, Kaffeeverzicht und Herzmedikamenten genau befolgen.","Eine leichte, fetthaltige Mahlzeit oder Milch nach der Injektion beschleunigt die Ausscheidung über die Galle und verbessert die Bilder.","Nach der Untersuchung viel trinken und häufig die Blase entleeren."],"darreichung":["Kit zur Herstellung einer radioaktiven Injektionslösung"]},"technetium-99mtc-tetrofosmin":{"wirkmechanismus":"Wird vom Herzmuskel im Verhältnis zur Durchblutung aufgenommen und macht schlecht durchblutete Bereiche sichtbar. Tetrofosmin ist ein fettlösliches, positiv geladenes Diphosphin, das mit Technetium-99m markiert rasch in die Herzmuskelzellen aufgenommen und dort abhängig vom Membranpotential der Mitochondrien festgehalten wird. Da es kaum umverteilt wird, lassen sich Bilder nach Belastung und in Ruhe vergleichen. Blut und Leber werden rasch freigegeben (Ausscheidung über Nieren und Galle), sodass die Aufnahmen schon kurz nach der Injektion möglich sind.","nebenwirkungen":{"unbekannt":["Metallischer Geschmack, Geschmacks- oder Geruchsstörungen, Brennen im Mund","Übelkeit, Erbrechen, Bauchbeschwerden","Kopfschmerzen, Schwindel, Sehstörungen","Hautrötung, Juckreiz, Nesselsucht, Schwellung im Gesicht","Atemnot, Engegefühl in der Brust, Blutdruckabfall","Überempfindlichkeitsreaktionen bis zur Anaphylaxie","Strahlenbelastung: sehr geringes zusätzliches Langzeitrisiko für Krebs oder Erbgutschäden"]},"schwangerschaft":"Nur bei zwingender Indikation (Strahlenbelastung des Ungeborenen); eine mögliche Schwangerschaft vorher ausschliessen.","stillzeit":"Stillen gemäss Anweisung der Nuklearmedizin vorübergehend unterbrechen und die abgepumpte Milch verwerfen.","hinweise":["Vor der Untersuchung die Anweisungen zu Nüchternheit, Kaffeeverzicht und Herzmedikamenten genau befolgen.","Nach der Untersuchung viel trinken und häufig die Blase entleeren."],"darreichung":["Kit zur Herstellung einer radioaktiven Injektionslösung"]},"teclistamab":{"wirkmechanismus":"Verbindet körpereigene Abwehrzellen (T-Zellen) mit Myelomzellen, damit diese zerstört werden. Teclistamab ist ein bispezifischer IgG4-Antikörper, der an BCMA (B-Zell-Reifungsantigen) auf Myelomzellen und an CD3 auf T-Zellen bindet. Die so aktivierten T-Zellen setzen Zytokine und zytotoxische Proteine (Perforin, Granzyme) frei und töten die BCMA-tragenden Zellen. Weil auch gesunde Plasmazellen BCMA tragen, sinken die Antikörperspiegel im Blut.","nebenwirkungen":{"sehrHaeufig":["Zytokin-Freisetzungs-Syndrom","Infektionen (Lungenentzündung, COVID-19, Atemwegsinfekte)","Neutropenie, Anämie, Thrombozytopenie, Lymphopenie (Blutbildveränderungen)","Hypogammaglobulinämie (Antikörpermangel)","Reaktionen an der Injektionsstelle","Durchfall, Übelkeit, Verstopfung","Müdigkeit, Fieber, Muskel- und Knochenschmerzen","Kopfschmerzen"],"haeufig":["ICANS (immuneffektorzell-assoziiertes Neurotoxizitätssyndrom: Verwirrtheit, Sprachstörungen)","Sepsis (Blutvergiftung)","Febrile Neutropenie (Fieber bei Mangel an Abwehrzellen)","Hypoxie (Sauerstoffmangel)","Erhöhte Leberwerte"],"unbekannt":["Progressive multifokale Leukenzephalopathie (PML, seltene Hirninfektion)"]},"schwangerschaft":"Kann beim Ungeborenen Blutbildveränderungen und Antikörpermangel verursachen; in der Schwangerschaft nicht empfohlen. Frauen verhüten während und 5 Monate nach der letzten Dosis.","stillzeit":"Während und 5 Monate nach der letzten Dosis nicht stillen.","hinweise":["Die Aufbaudosen werden unter Überwachung, meist im Spital, gegeben; Fieber, Schüttelfrost, Atemnot, Schwindel oder Verwirrtheit sofort melden.","Nach den Aufbaudosen und bei neurologischen Beschwerden kein Fahrzeug lenken und keine Maschinen bedienen.","Infektzeichen umgehend melden; Blutbild und Immunglobuline werden regelmässig kontrolliert.","Patientenkarte immer mitführen."],"darreichung":["Injektionslösung zur subkutanen Anwendung"]},"tedizolid":{"wirkmechanismus":"Hemmt das Wachstum grampositiver Bakterien, indem es deren Eiweissherstellung blockiert. Tedizolidphosphat ist eine Vorstufe, die im Körper rasch zum wirksamen Tedizolid umgewandelt wird. Tedizolid bindet an die 23S-ribosomale RNA der 50S-Untereinheit und verhindert den Start der bakteriellen Eiweisssynthese (überwiegend bakteriostatisch). Es wirkt gegen Staphylokokken einschliesslich MRSA, Streptokokken und Enterokokken (auch vancomycinresistente), nicht gegen gramnegative Bakterien.","nebenwirkungen":{"haeufig":["Übelkeit","Kopfschmerzen","Durchfall","Erbrechen","Schwindel","Juckreiz am ganzen Körper"],"gelegentlich":["Pilzinfektionen (Mund, Scheide), Abszesse","Clostridioides-difficile-Kolitis (schwere Darmentzündung)","Anämie, Leukopenie","Schlaflosigkeit, Schläfrigkeit, Geschmacksstörungen, Kribbeln","Verschwommenes Sehen, Glaskörpertrübungen","Langsamer Puls (Bradykardie), Hitzewallungen","Bauchschmerzen, Verstopfung, Mundtrockenheit","Hautausschlag, Nesselsucht, Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Keine Erfahrungen beim Menschen; im Tierversuch Entwicklungsstörungen. Vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Tedizolid beim Menschen in die Muttermilch übergeht (bei Ratten ja). Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Tabletten unabhängig von den Mahlzeiten einnehmen; die Behandlung dauert in der Regel 6 Tage.","Bei Einnahme von Rosuvastatin, Methotrexat oder Krebsmedikamenten die Ärztin oder den Arzt informieren.","Sehstörungen, Kribbeln oder Taubheitsgefühl sowie starken Durchfall ärztlich melden."],"darreichung":["Filmtabletten","Pulver für ein Konzentrat zur Herstellung einer Infusionslösung"]},"teduglutid":{"wirkmechanismus":"Fördert das Wachstum und die Erholung der verbliebenen Darmschleimhaut, damit mehr Flüssigkeit und Nährstoffe aufgenommen werden. Teduglutid ist ein gentechnisch hergestelltes Analogon des körpereigenen Darmhormons GLP-2 und bindet an GLP-2-Rezeptoren im Darm. Dies vergrössert Darmzotten und Krypten, verbessert die Durchblutung und verlangsamt Magenentleerung und Darmpassage. Durch einen Aminosäureaustausch wird es vom Enzym DPP-4 kaum abgebaut und wirkt deshalb länger als natürliches GLP-2.","nebenwirkungen":{"sehrHaeufig":["Atemwegsinfektionen","Kopfschmerzen","Bauchschmerzen und Blähbauch","Übelkeit, Erbrechen","Schwellung oder andere Veränderungen am Stoma (künstlicher Darmausgang)","Reaktionen an der Injektionsstelle"],"haeufig":["Grippeähnliche Beschwerden","Appetitminderung","Flüssigkeitsüberladung, periphere Ödeme","Angst, Schlafstörungen","Kolorektale Polypen (Dickdarmpolypen)","Darmverschluss oder Darmverengung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Cholezystitis (Gallenblasenentzündung)"],"unbekannt":["Magen- und Zwölffingerdarmpolypen","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Vorsichtshalber in der Schwangerschaft vermeiden.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; vorsichtshalber während der Stillzeit nicht anwenden.","hinweise":["Einmal täglich unter die Haut von Bauch oder Oberschenkel spritzen, Einstichstelle wechseln.","Bei starken Bauchschmerzen, Blähbauch, Erbrechen oder Schwellung am Stoma sofort ärztlichen Rat einholen.","Gewicht, Flüssigkeitshaushalt und Laborwerte werden regelmässig kontrolliert, v. a. bei Anpassung der parenteralen Ernährung."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"teicoplanin":{"wirkmechanismus":"Tötet grampositive Bakterien ab, indem es den Aufbau ihrer Zellwand blockiert. Teicoplanin bindet an die D-Alanyl-D-Alanin-Enden der Zellwand-Bausteine und verhindert deren Einbau und Quervernetzung. Es wirkt gegen Staphylokokken (einschliesslich MRSA), Streptokokken, Enterokokken und Clostridien, aber nicht gegen gramnegative Bakterien. Wegen seiner sehr langen Halbwertszeit genügt nach einer Aufsättigungsphase eine Gabe pro Tag.","nebenwirkungen":{"haeufig":["Hautausschlag, Hautrötung, Juckreiz","Schmerzen an der Einstichstelle","Fieber"],"gelegentlich":["Thrombozytopenie, Leukopenie, Eosinophilie","Überempfindlichkeitsreaktionen","Schwindel, Kopfschmerzen","Hörverlust, Ohrensausen, Gleichgewichtsstörungen","Venenentzündung","Bronchospasmus (Verkrampfung der Atemwege)","Durchfall, Übelkeit, Erbrechen","Erhöhte Leber- und Nierenwerte"],"selten":["Red-Man-Syndrom (Rötung von Gesicht und Oberkörper während der Infusion)"],"unbekannt":["Anaphylaxie bis zum Schock","DRESS, Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Agranulozytose, Neutropenie","Akutes Nierenversagen","Krampfanfälle"]},"schwangerschaft":"Begrenzte Erfahrungen; im Tierversuch Schäden bei hohen Dosen. Gehör- und Nierenschäden beim Ungeborenen nicht ausgeschlossen – nur anwenden, wenn unbedingt erforderlich.","stillzeit":"Nicht bekannt, ob Teicoplanin in die Muttermilch übergeht. Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird als Injektion oder Infusion gegeben, zu Beginn in höherer Dosis (Aufsättigung); teils auch ambulant.","Ohrensausen, Hörminderung, Hautausschlag mit Fieber oder Blasen sowie Blutungszeichen sofort melden.","Bei längerer Behandlung werden Blutbild, Leber- und Nierenwerte sowie das Gehör kontrolliert."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektions- oder Infusionslösung"]},"telmisartan":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Wirkung des gefässverengenden Hormons Angiotensin II blockiert. Telmisartan bindet selektiv und lang anhaltend an den Angiotensin-II-Rezeptor Typ 1 (AT1) und hebt so die gefässverengende und aldosteronfreisetzende Wirkung von Angiotensin II auf: Die Gefässe erweitern sich, Salz- und Wasserrückhaltung nehmen ab. Anders als ACE-Hemmer hemmt es den Abbau von Bradykinin nicht, weshalb trockener Reizhusten selten ist. Telmisartan wird fast vollständig über die Galle ausgeschieden und wirkt dank langer Halbwertszeit (rund 24 Stunden) über den ganzen Tag.","nebenwirkungen":{"gelegentlich":["Hypotonie (tiefer Blutdruck), auch beim Aufstehen – bei Behandlung zur Herz-Kreislauf-Vorbeugung häufig","Hyperkaliämie (erhöhtes Kalium)","Nierenfunktionsstörung bis zum akuten Nierenversagen, erhöhtes Kreatinin","Synkope (kurze Ohnmacht), Vertigo (Drehschwindel), Bradykardie (langsamer Puls)","Harnwegsinfekte und Infekte der oberen Atemwege (z. B. Rachenentzündung, Sinusitis)","Bauchschmerzen, Durchfall, Verdauungsbeschwerden, Blähungen, Erbrechen","Muskelschmerzen, Muskelkrämpfe, Rückenschmerzen","Anämie (Blutarmut)"],"selten":["Angioödem (Schwellung von Gesicht, Zunge oder Rachen), auch lebensbedrohlich","Anaphylaxie (schwere allergische Reaktion)","Sepsis (Blutvergiftung), auch mit tödlichem Verlauf","Hypoglykämie (Unterzuckerung) bei Diabetikern","Thrombozytopenie (Mangel an Blutplättchen), Eosinophilie","Leberfunktionsstörung, erhöhte Leberwerte","Hautausschläge (Ekzem, Nesselsucht, toxischer Hautausschlag)","Gelenk- und Sehnenschmerzen"],"sehrSelten":["Interstitielle Lungenerkrankung"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schäden an Nieren und Schädelknochen des Ungeborenen, Fruchtwassermangel). Bei Kinderwunsch oder festgestellter Schwangerschaft rasch auf ein geeignetes Mittel umstellen.","stillzeit":"Nicht empfohlen, da Daten fehlen; besser untersuchte Alternativen wählen, besonders bei Neu- und Frühgeborenen.","hinweise":["Einmal täglich, mit oder ohne Essen; die volle Blutdrucksenkung wird nach 4–8 Wochen erreicht.","Kalium und Nierenwerte zu Beginn und regelmässig kontrollieren lassen.","Bei Durchfall, Erbrechen oder starkem Schwitzen ärztlich Rücksprache nehmen – Gefahr von Blutdruckabfall und Nierenversagen.","Zu Beginn können Schwindel und Müdigkeit die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Tabletten"]},"telotristat":{"wirkmechanismus":"Vermindert die übermässige Bildung von Serotonin, die beim Karzinoidsyndrom Durchfall verursacht. Telotristat ethyl ist eine Vorstufe, die im Körper zum aktiven Telotristat umgewandelt wird. Dieses hemmt die Tryptophanhydroxylase, das Schlüsselenzym der Serotoninbildung aus Tryptophan in Tumor- und Darmzellen. Dadurch sinken Serotoninspiegel und Stuhlfrequenz; ins Gehirn gelangt der Wirkstoff kaum.","nebenwirkungen":{"sehrHaeufig":["Bauchschmerzen","Müdigkeit"],"haeufig":["Appetitminderung","Depression, gedrückte Stimmung","Kopfschmerzen","Blähbauch, Blähungen, Verstopfung","Erhöhte Leberwerte (GGT, Transaminasen, alkalische Phosphatase)","Periphere Ödeme (Wassereinlagerungen)","Fieber"],"gelegentlich":["Kotstau (Fäkalom)"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter müssen wirksam verhüten.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen; Stillen während der Behandlung nicht empfohlen.","hinweise":["Dreimal täglich mit einer Mahlzeit oder einem Imbiss einnehmen.","Die Behandlung mit dem Somatostatin-Analogon (z. B. Octreotid, Lanreotid) weiterführen.","Verstopfung, zunehmende Bauchschmerzen oder gedrückte Stimmung ärztlich melden."],"darreichung":["Filmtabletten"]},"temozolomid":{"wirkmechanismus":"Hemmt das Wachstum von Hirntumorzellen, indem es deren Erbgut schädigt. Temozolomid ist ein Prodrug, das ohne Leberstoffwechsel beim pH-Wert des Körpers spontan zum aktiven Methyltriazen MTIC zerfällt. MTIC hängt Methylgruppen an die DNA-Base Guanin (vor allem an der O6- und N7-Position); die entstehenden Fehlpaarungen lösen den Zelltod aus. Tumoren, deren Reparaturenzym MGMT abgeschaltet ist (methylierter MGMT-Promotor), sprechen besonders gut an; der Wirkstoff gelangt gut ins Gehirn.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Verstopfung","Appetitlosigkeit","Müdigkeit","Kopfschmerzen","Haarausfall","Hautausschlag"],"haeufig":["Mangel an Blutplättchen, weissen und roten Blutkörperchen (Thrombozytopenie, Neutropenie, Lymphopenie, Anämie)","Infektionen, Mundsoor (Pilzbefall)","Krampfanfälle","Schwindel, Gedächtnis- und Konzentrationsstörungen, Verwirrtheit","Schlafstörungen, Angst","Durchfall, Bauchschmerzen, Mundschleimhautentzündung","Atemnot, Husten","Erhöhte Leberwerte"],"unbekannt":["Pneumocystis-Pneumonie und andere opportunistische Infektionen (z. B. Zytomegalie, Hepatitis-B-Reaktivierung)","Lang anhaltender Mangel aller Blutzellen, aplastische Anämie","Myelodysplastisches Syndrom und Zweitleukämien","Leberschäden bis Leberversagen","Interstitielle Pneumonitis, Lungenfibrose","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Anaphylaxie (schwere allergische Reaktion)","Diabetes insipidus"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und bis mehrere Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Kapseln nüchtern (mindestens 1 Stunde vor einer Mahlzeit) unzerkaut mit Wasser schlucken; nicht öffnen – bei Kontakt mit dem Inhalt Haut sofort waschen.","Vorbeugend Mittel gegen Übelkeit einnehmen; bei Erbrechen am selben Tag keine zweite Dosis nehmen.","Blutbild- und Leberkontrollen vor und während jedes Zyklus; Fieber und Infektzeichen sofort melden."],"darreichung":["Hartkapseln"]},"temsirolimus":{"wirkmechanismus":"Bremst das Wachstum von Krebszellen und die Bildung neuer Blutgefässe im Tumor. Temsirolimus und sein Wirkmetabolit Sirolimus binden an das Eiweiss FKBP-12; dieser Komplex hemmt die Kinase mTOR. Dadurch wird die Zellteilung im G1-Stadium angehalten und die Bildung von Wachstumsfaktoren wie VEGF über HIF-1α und HIF-2α vermindert.","nebenwirkungen":{"sehrHaeufig":["Infektionen (z. B. Harnwegs- und Atemwegsinfekte)","Anämie, Thrombozytopenie (Mangel an Blutplättchen)","Hyperglykämie (erhöhter Blutzucker), erhöhte Blutfette, Hypokaliämie","Appetitlosigkeit, Geschmacksstörungen","Mukositis und Stomatitis (Schleimhautentzündung im Mund), Übelkeit, Durchfall","Atemnot, Husten, Nasenbluten","Hautausschlag, Juckreiz, Nagelveränderungen","Ödeme (Wassereinlagerungen), Schwäche, Fieber"],"haeufig":["Neutropenie (Mangel an weissen Blutkörperchen)","Pneumonitis (Lungenentzündung ohne Infektion)","Überempfindlichkeits- und Infusionsreaktionen","Lungenentzündung, Sepsis","Thrombosen und Lungenembolie","Bluthochdruck","Nierenversagen","Bindehautentzündung, Schlaflosigkeit"],"gelegentlich":["Magen-Darm-Perforation (Durchbruch)","Hirnblutung","Perikarderguss (Flüssigkeit im Herzbeutel)","Wundheilungsstörungen"],"unbekannt":["Angioödem","Stevens-Johnson-Syndrom","Rhabdomyolyse (Muskelzerfall)"]},"schwangerschaft":"Nicht anwenden, ausser wenn unbedingt nötig (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und bis 3 Monate nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird einmal wöchentlich als Infusion im Spital oder in der Praxis gegeben; etwa 30 Minuten vorher erhält man ein Antihistaminikum gegen Infusionsreaktionen.","Regelmässige Kontrollen: Blutbild, Blutzucker, Blutfette, Nierenwerte.","Keine Lebendimpfungen während der Behandlung; Grapefruit meiden.","Atemnot, Husten oder Fieber umgehend ärztlich melden."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"tenecteplase":{"wirkmechanismus":"Löst Blutgerinnsel auf, die ein Herzkranzgefäss verschliessen. Tenecteplase ist eine gentechnisch veränderte Form des körpereigenen Gewebeplasminogenaktivators (t-PA): Es bindet an das Fibrin im Gerinnsel und wandelt dort Plasminogen in Plasmin um, das das Fibringerüst abbaut. Durch die Veränderungen ist es stärker fibrinspezifisch, weniger empfindlich gegenüber dem Hemmstoff PAI-1 und wird langsamer abgebaut, sodass eine einzige Injektion genügt.","nebenwirkungen":{"sehrHaeufig":["Blutungen, vor allem an Einstich- und Injektionsstellen","Herzrhythmusstörungen nach Wiederöffnung des Gefässes (Reperfusionsarrhythmien)"],"haeufig":["Nasenbluten","Magen-Darm-Blutungen","Blutungen im Harn- und Geschlechtstrakt","Blutergüsse (Ekchymosen)"],"gelegentlich":["Hirnblutung","Blutungen hinter dem Bauchfell (retroperitoneal)","Augenblutung"],"selten":["Anaphylaktoide Reaktionen (schwere Überempfindlichkeit)","Lungenblutung","Herzbeutelblutung (Hämoperikard)"],"unbekannt":["Embolien, auch Cholesterinembolien","Übelkeit, Erbrechen","Blutdruckabfall"]},"schwangerschaft":"Nur begrenzte Daten; in der lebensbedrohlichen Situation eines Herzinfarkts nur nach sorgfältiger Abwägung von Nutzen und Blutungsrisiko.","stillzeit":"Die Muttermilch soll in den ersten 24 Stunden nach der Behandlung verworfen werden.","hinweise":["Wird nur durch Notfallpersonal oder im Spital als einmalige Injektion gegeben.","Nach der Behandlung Blutungszeichen (schwarzer Stuhl, Blut im Urin, plötzliche starke Kopfschmerzen, Lähmungen) sofort melden."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"tenofoviralafenamid":{"wirkmechanismus":"Hemmt die Vermehrung des Hepatitis-B-Virus und von HIV. Tenofoviralafenamid ist eine im Blut stabile Vorstufe von Tenofovir, die vor allem in Leberzellen und Lymphozyten aufgenommen und dort (durch Carboxylesterase 1 bzw. Cathepsin A) zu Tenofovir gespalten wird. Tenofovir wird zum aktiven Tenofovir-Diphosphat phosphoryliert, das in die Virus-DNA eingebaut wird und die Kettenverlängerung abbricht. Weil eine kleine Dosis genügt, ist der Tenofovir-Spiegel im Blut rund 90 % tiefer als mit Tenofovirdisoproxil – Nieren und Knochen werden weniger belastet.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen"],"haeufig":["Schwindel","Übelkeit, Erbrechen, Durchfall","Bauchschmerzen, Blähbauch, Blähungen","Erhöhte Leberwerte (ALT)","Hautausschlag, Juckreiz","Gelenkschmerzen","Müdigkeit"],"gelegentlich":["Angioödem (Schwellung von Haut und Schleimhäuten)","Nesselsucht"],"unbekannt":["Schwere Hepatitisschübe nach dem Absetzen"]},"schwangerschaft":"Kann bei Bedarf in der Schwangerschaft in Betracht gezogen werden; die bisherigen Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Gemäss Fachinformation nicht stillen, da Tenofovir in die Muttermilch übergeht und ein Risiko für das Kind nicht ausgeschlossen ist. HIV-positive Mütter sollen grundsätzlich nicht stillen.","hinweise":["Einmal täglich mit einer Mahlzeit einnehmen.","Bei Hepatitis B nicht eigenmächtig absetzen – nach dem Absetzen Leberwerte über Monate kontrollieren.","Vor Beginn HIV-Test; Nierenfunktion regelmässig kontrollieren lassen."],"darreichung":["Filmtabletten"]},"tenofovirdisoproxil":{"wirkmechanismus":"Hemmt die Vermehrung von HIV und Hepatitis-B-Viren. Tenofovirdisoproxil ist eine Vorstufe (Prodrug), die nach der Aufnahme zu Tenofovir gespalten und in den Zellen zu Tenofovir-Diphosphat aktiviert wird. Dieses Nukleotid-Analogon des Adenosins wird von der Reversen Transkriptase von HIV bzw. der Polymerase des Hepatitis-B-Virus in die Virus-DNA eingebaut und führt zum Kettenabbruch. Tenofovir wird über die Nieren ausgeschieden und reichert sich in den Zellen der Nierenkanälchen an, was die mögliche Nierenschädigung erklärt.","nebenwirkungen":{"sehrHaeufig":["Hypophosphatämie (zu wenig Phosphat im Blut)","Schwindel","Durchfall, Übelkeit, Erbrechen","Hautausschlag","Asthenie (Schwäche)"],"haeufig":["Kopfschmerzen","Bauchschmerzen, Blähbauch, Blähungen","Erhöhte Leberwerte","Müdigkeit"],"gelegentlich":["Proximale Tubulopathie der Niere (inkl. Fanconi-Syndrom), Kreatininanstieg","Hypokaliämie (Kaliummangel)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Rhabdomyolyse (Muskelzerfall), Muskelschwäche"],"selten":["Akutes Nierenversagen, Nierenentzündung, nephrogener Diabetes insipidus","Osteomalazie (Knochenerweichung) mit Knochenschmerzen und Brüchen","Laktatazidose (Übersäuerung des Blutes)","Fettleber, Hepatitis","Angioödem (Schwellung von Haut und Schleimhäuten)"]},"schwangerschaft":"Kann bei Bedarf in der Schwangerschaft angewendet werden; umfangreiche Daten zeigen kein erhöhtes Fehlbildungsrisiko.","stillzeit":"Tenofovir geht in die Muttermilch über; gemäss Fachinformation während der Stillzeit nicht anwenden. HIV-positive Mütter sollen grundsätzlich nicht stillen.","hinweise":["Mit einer Mahlzeit einnehmen (bessere Aufnahme).","Nierenwerte und Phosphat vor Beginn und regelmässig während der Behandlung kontrollieren lassen.","Bei Hepatitis B nicht eigenmächtig absetzen – Hepatitisschub möglich.","Regelmässige Einnahme von Schmerzmitteln wie Ibuprofen oder Diclofenac vorher mit der Fachperson besprechen."],"darreichung":["Filmtabletten"]},"tenoxicam":{"wirkmechanismus":"Lindert Schmerzen und Entzündungen, indem es die Bildung von Prostaglandinen hemmt. Tenoxicam hemmt die Cyclooxygenasen COX-1 und COX-2. Mit einer Halbwertszeit von etwa 70 Stunden wirkt es sehr lange; eine Einnahme pro Tag genügt, und der Wirkstoff bleibt nach dem Absetzen noch mehrere Tage im Körper.","nebenwirkungen":{"haeufig":["Magen-Darm-Beschwerden wie Magendruck, Bauchschmerzen, Übelkeit, Dyspepsie (Verdauungsbeschwerden)","Kopfschmerzen, Schwindel"],"gelegentlich":["Magen-Darm-Geschwüre und -Blutungen","Verstopfung, Durchfall, Mundschleimhautentzündung","Hautausschlag, Juckreiz","Ödeme (Wassereinlagerungen)","Schlafstörungen, Schläfrigkeit","Herzklopfen","Erhöhte Leberwerte"],"unbekannt":["Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse)","Lichtempfindlichkeitsreaktionen","Agranulozytose, Thrombozytopenie, Anämie","Anaphylaxie, Bronchospasmus","Sehstörungen","Nierenfunktionsstörungen","Herzinsuffizienz, erhöhtes Risiko für Herzinfarkt und Schlaganfall"]},"schwangerschaft":"Im 1. und 2. Drittel nur nach strenger ärztlicher Abwägung; ab der 20. Woche können NSAR die Nierenfunktion des Ungeborenen beeinträchtigen. Im letzten Drittel kontraindiziert.","stillzeit":"Geht in geringen Mengen in die Muttermilch über; in der Stillzeit nicht empfohlen.","hinweise":["Einmal täglich mit einer Mahlzeit und reichlich Flüssigkeit einnehmen.","Wegen der sehr langen Wirkdauer keine zusätzlichen NSAR einnehmen; Nebenwirkungen klingen nach dem Absetzen nur langsam ab.","Schwindel kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden.","Bei schwarzem Stuhl, Bluterbrechen oder starken Magenschmerzen sofort ärztliche Hilfe holen."],"darreichung":["Filmtabletten"]},"tepotinib":{"wirkmechanismus":"Blockiert ein Wachstumssignal, das durch eine bestimmte Genveränderung im Tumor überaktiv ist. Tepotinib hemmt selektiv die Rezeptor-Tyrosinkinase MET. Bei MET-Exon-14-Skipping-Veränderungen wird MET nicht mehr normal abgebaut und treibt dauerhaft Zellteilung, Überleben und Ausbreitung der Krebszellen an; Tepotinib unterbricht diese Signale.","nebenwirkungen":{"sehrHaeufig":["Ödeme (Wassereinlagerungen, v. a. an den Beinen, auch am ganzen Körper)","Albuminmangel im Blut","Übelkeit, Durchfall","Erhöhtes Kreatinin","Erhöhte Leberwerte, erhöhte Amylase und Lipase","Müdigkeit"],"haeufig":["Interstitielle Lungenerkrankung, Pneumonitis","Erbrechen, Bauchschmerzen, Verstopfung","Pleuraerguss (Wasser im Brustfellraum)"]},"schwangerschaft":"Kann das ungeborene Kind schädigen; nur bei zwingender Notwendigkeit. Frauen und Männer müssen während der Behandlung und mindestens 1 Woche danach zuverlässig verhüten; bei hormonaler Verhütung zusätzlich eine Barrieremethode.","stillzeit":"Während der Behandlung und mindestens 1 Woche danach nicht stillen.","hinweise":["Einmal täglich mit einer Mahlzeit einnehmen; Tabletten unzerkaut schlucken.","Gewicht und Schwellungen beobachten; starke Ödeme melden.","Neue oder verschlimmerte Atemnot, Husten oder Fieber sofort melden.","Leberwerte werden regelmässig kontrolliert; kein Johanniskraut."],"darreichung":["Filmtabletten"]},"teprotumumab":{"wirkmechanismus":"Bremst die Entzündung und das Gewebewachstum hinter dem Auge, die bei der endokrinen Orbitopathie die Augen hervortreten lassen. Teprotumumab ist ein vollständig humaner monoklonaler IgG1-Antikörper, der den Insulin-like-Growth-Factor-1-Rezeptor (IGF-1R) blockiert. Auf den Bindegewebszellen der Augenhöhle bildet IGF-1R mit dem TSH-Rezeptor einen Signalkomplex, der durch Autoantikörper aktiviert wird. Seine Hemmung vermindert Entzündung, Hyaluronsäurebildung und die Volumenzunahme von Fett- und Muskelgewebe in der Augenhöhle.","nebenwirkungen":{"sehrHaeufig":["Muskelkrämpfe","Übelkeit","Durchfall","Haarausfall","Hyperglykämie (erhöhter Blutzucker)","Hörstörungen (Schwerhörigkeit, Ohrensausen, Druckgefühl, Hören der eigenen Stimme)","Müdigkeit"],"haeufig":["Geschmacksstörungen","Kopfschmerzen","Trockene Haut","Gewichtsabnahme","Nagelveränderungen","Infusionsreaktionen"],"unbekannt":["Bleibender Hörverlust","Verschlechterung einer chronisch-entzündlichen Darmerkrankung"]},"schwangerschaft":"Kontraindiziert: kann das ungeborene Kind schädigen (Wachstumsstörungen, Fehlgeburt). Vor Beginn Schwangerschaft ausschliessen und bis 6 Monate nach der letzten Infusion zuverlässig verhüten.","stillzeit":"Keine Erfahrungen; Stillen nur nach ärztlicher Abwägung.","hinweise":["Hörveränderungen (gedämpftes Hören, Ohrensausen, Hören der eigenen Stimme) sofort melden.","Bei Diabetes Blutzucker während der Behandlung häufiger messen.","Zuverlässig verhüten bis 6 Monate nach der letzten Infusion."],"darreichung":["Pulver zur Herstellung eines Infusionslösungskonzentrats"]},"terbinafin":{"wirkmechanismus":"Tötet Pilze ab, indem es den Aufbau ihrer Zellmembran stört. Terbinafin hemmt gezielt das pilzeigene Enzym Squalen-Epoxidase: Dadurch fehlt der Membranbaustein Ergosterol, und gleichzeitig reichert sich Squalen in giftigen Mengen in der Pilzzelle an. Gegen Dermatophyten (Fadenpilze) wirkt es abtötend (fungizid), gegen Hefen teils nur wachstumshemmend. Nach Einnahme reichert sich Terbinafin in Haut, Haaren und Nägeln an und bleibt dort über Wochen wirksam.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen (Tabletten)","Magen-Darm-Beschwerden wie Völlegefühl, Appetitlosigkeit, Dyspepsie (Verdauungsbeschwerden), Übelkeit, leichte Bauchschmerzen, Durchfall (Tabletten)","Hautausschlag, Nesselsucht (Tabletten)","Gelenk- und Muskelschmerzen (Tabletten)"],"haeufig":["Geschmacksstörung oder Geschmacksverlust, teils lang anhaltend (Tabletten)","Schwindel, Müdigkeit (Tabletten)","Sehstörungen (Tabletten)","Depressive Verstimmung (Tabletten)","Hautschuppung und Juckreiz an der Auftragsstelle (Creme, Gel)"],"gelegentlich":["Kribbeln oder Taubheitsgefühl (Parästhesien)","Ohrgeräusche (Tinnitus)","Lichtempfindlichkeit der Haut (Photosensibilität)","Angst, Fieber, Gewichtsabnahme","Rötung, Brennen oder Reizung an der Auftragsstelle (Creme, Gel)"],"selten":["Leberschäden: Hepatitis, Gallestau, Gelbsucht, erhöhte Leberwerte, Leberversagen (Einzelfälle mit Lebertransplantation oder tödlichem Verlauf)","Augenreizung, trockene Haut, Kontaktekzem (äusserliche Anwendung)"],"sehrSelten":["Agranulozytose, Neutropenie, Thrombozytopenie (schwere Blutbildstörungen)","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, akute generalisierte exanthematische Pustulose)","Auslösung oder Verschlechterung einer Psoriasis","Lupus erythematodes (Haut oder ganzer Körper)","Anaphylaktoide Reaktionen, Angioödem (Schwellung von Haut und Schleimhäuten)","Haarausfall"],"unbekannt":["Panzytopenie, Anämie (Blutbildstörungen)","DRESS (schwere Arzneimittelreaktion mit Fieber, Ausschlag und Organbeteiligung)","Pankreatitis (Bauchspeicheldrüsenentzündung)","Geruchsverlust, Hörminderung","Vaskulitis (Gefässentzündung)","Rhabdomyolyse (Muskelzerfall)","Serumkrankheit-ähnliche Reaktion, grippeähnliche Beschwerden"]},"schwangerschaft":"Tabletten: nicht anwenden, ausser wenn eindeutig notwendig (ungenügende Erfahrung). Creme, Gel und Lösung nur nach ärztlicher Abwägung; die Aufnahme über die Haut ist gering.","stillzeit":"Terbinafin geht in die Muttermilch über: während der Einnahme von Tabletten nicht stillen. Äusserliche Mittel nicht auf die Brust auftragen; der Säugling soll nicht mit behandelter Haut in Kontakt kommen.","hinweise":["Vor einer Tablettenbehandlung Leberwerte bestimmen lassen; bei Übelkeit, Appetitverlust, Müdigkeit, Gelbfärbung der Haut oder Augen, dunklem Urin oder hellem Stuhl sofort Arzt kontaktieren.","Bei Nagelpilz wächst der gesunde Nagel erst Monate nach Ende der Tabletteneinnahme nach – der Erfolg zeigt sich verzögert.","Geschmacksstörungen können nach dem Absetzen noch Wochen anhalten; bei Appetit- oder Gewichtsverlust den Arzt informieren.","Die Wechselwirkungen betreffen die Tabletten; Lamisil Once wird nur einmal auf beide Füsse aufgetragen, auch wenn nur ein Fuss betroffen ist."],"darreichung":["Tabletten","Creme","Gel","Lösung zur Anwendung auf der Haut (Einmalanwendung)"]},"terbutalin":{"wirkmechanismus":"Erweitert die Atemwege, indem es die verkrampfte Bronchialmuskulatur entspannt. Terbutalin stimuliert selektiv Beta-2-Adrenozeptoren der glatten Muskulatur; über einen Anstieg von zyklischem AMP (cAMP) erschlafft die Muskulatur. Nach dem Inhalieren setzt die Wirkung innert weniger Minuten ein und hält etwa 4–6 Stunden an. Zusätzlich wird die Reinigung der Bronchien durch die Flimmerhärchen gefördert.","nebenwirkungen":{"sehrHaeufig":["Zittern (Tremor)","Kopfschmerzen"],"haeufig":["Herzrasen (Tachykardie), Herzklopfen (Palpitationen)","Muskelkrämpfe","Hypokaliämie (Kaliummangel)"],"unbekannt":["Herzrhythmusstörungen (z. B. Vorhofflimmern, Extrasystolen)","Myokardischämie (Durchblutungsstörung des Herzmuskels)","Paradoxer Bronchospasmus (Verkrampfung der Atemwege direkt nach dem Inhalieren)","Überempfindlichkeitsreaktionen mit Hautausschlag, Nesselsucht oder Angioödem","Schlafstörungen, Unruhe, Erregtheit","Übelkeit","Blutdruckabfall, Kollaps"]},"schwangerschaft":"Keine Hinweise auf fruchtschädigende Wirkungen; im ersten Drittel nur nach ärztlicher Abwägung. Bei Anwendung kurz vor der Geburt kann das Neugeborene vorübergehend einen tiefen Blutzucker und einen schnellen Puls haben.","stillzeit":"Terbutalin geht in die Muttermilch über; in üblichen Dosen sind Auswirkungen auf den Säugling unwahrscheinlich – Anwendung nach ärztlicher Abwägung möglich.","hinweise":["Bei Atemnot nach Bedarf inhalieren. Braucht man das Mittel häufiger als sonst oder wirkt es schlechter, rasch ärztlich abklären lassen.","Ersetzt bei Asthma nicht die entzündungshemmende Basisbehandlung mit inhalativem Kortison.","Inhalationstechnik regelmässig in der Apotheke oder Praxis überprüfen lassen.","Steht auf der Dopingliste: Leistungssportlerinnen und -sportler brauchen eine medizinische Ausnahmebewilligung."],"darreichung":["Pulver zur Inhalation (Turbuhaler)","Injektionslösung"]},"teriflunomid":{"wirkmechanismus":"Bremst die Vermehrung aktivierter Abwehrzellen, die bei MS die Nervenhüllen angreifen, ohne die Abwehr ganz auszuschalten. Teriflunomid, der aktive Metabolit von Leflunomid, hemmt reversibel das mitochondriale Enzym Dihydroorotat-Dehydrogenase (DHODH). Dadurch wird die Neubildung von Pyrimidin-Bausteinen blockiert, die sich rasch teilende T- und B-Lymphozyten benötigen. Ruhende Zellen können ihren Bedarf weiterhin über einen Wiederverwertungsweg decken.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Durchfall","Übelkeit","Erhöhte Leberwerte (ALT)","Haarausdünnung (Alopezie)"],"haeufig":["Infektionen (Grippe, Atemwegs- und Harnwegsinfekte, Lippenherpes)","Neutropenie (Mangel an weissen Blutkörperchen), Anämie","Leichte allergische Reaktionen","Kribbeln (Parästhesien), Ischiasschmerzen, Karpaltunnelsyndrom","Bluthochdruck","Erbrechen, Oberbauchschmerzen","Hautausschlag, Akne","Muskel- und Gelenkschmerzen"],"gelegentlich":["Leichte Thrombozytopenie (Mangel an Blutplättchen)","Periphere Neuropathie (Nervenschäden), Nervenschmerzen","Nagelveränderungen"],"unbekannt":["Schwere Infektionen inkl. Sepsis","Anaphylaxie, Angioödem","Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Interstitielle Lungenerkrankung","Pankreatitis (Bauchspeicheldrüsenentzündung)","Mundschleimhautentzündung (Stomatitis)","Schwere Leberschäden","Psoriasis (Schuppenflechte)"]},"schwangerschaft":"Kontraindiziert (fruchtschädigend). Frauen im gebärfähigen Alter müssen zuverlässig verhüten; bei Kinderwunsch oder Eintritt einer Schwangerschaft wird ein beschleunigtes Auswaschverfahren mit Colestyramin oder Aktivkohle durchgeführt, da Teriflunomid sonst bis zu 2 Jahre im Blut verbleiben kann.","stillzeit":"Kontraindiziert.","hinweise":["Leberwerte vor Beginn und in den ersten 6 Monaten engmaschig, danach regelmässig kontrollieren; ebenso Blutbild und Blutdruck.","Alkohol möglichst meiden (Leberbelastung).","Bei Kinderwunsch frühzeitig ärztlich besprechen: Auswaschverfahren über etwa 11 Tage und Spiegelkontrolle.","Keine Lebendimpfungen während der Behandlung."],"darreichung":["Filmtabletten"]},"teriparatid":{"wirkmechanismus":"Regt die knochenbildenden Zellen an und baut so neue Knochensubstanz auf – im Gegensatz zu den meisten Osteoporosemitteln, die nur den Knochenabbau bremsen. Teriparatid ist das gentechnisch hergestellte aktive Teilstück (Aminosäuren 1–34) des körpereigenen Parathormons und bindet an den PTH-1-Rezeptor. Einmal täglich gegeben, stimuliert es überwiegend die Osteoblasten (osteoanaboler Effekt), während ein dauerhaft erhöhtes Parathormon den Knochen abbauen würde. Knochendichte und -struktur nehmen vor allem an der Wirbelsäule zu, das Risiko für Wirbel- und andere Brüche sinkt. Zudem steigert es vorübergehend die Calciumaufnahme im Darm und die Calcium-Rückresorption in der Niere.","nebenwirkungen":{"sehrHaeufig":["Gliederschmerzen"],"haeufig":["Übelkeit, Erbrechen, Sodbrennen","Kopfschmerzen, Schwindel, Drehschwindel","Blutdruckabfall, kurze Bewusstlosigkeit (Synkope), Herzklopfen","Muskelkrämpfe, Ischiasschmerzen","Müdigkeit, Schwäche, Brustschmerzen, Atemnot","Depression","Leichte Reaktionen an der Einstichstelle (Schmerz, Schwellung, Rötung, Juckreiz)","Anämie (Blutarmut), erhöhtes Cholesterin, vermehrtes Schwitzen"],"gelegentlich":["Hyperkalzämie (Calcium im Blut über 2,76 mmol/l)","Erhöhte Harnsäure","Schneller Puls (Tachykardie)","Nierensteine, häufiger Harndrang, Harninkontinenz","Muskel-, Gelenk- und Rückenschmerzen","Gewichtszunahme, erhöhte alkalische Phosphatase"],"selten":["Allergische Reaktionen bis zur Anaphylaxie, meist kurz nach der Injektion","Stark erhöhtes Calcium (über 3,25 mmol/l)","Nierenfunktionsstörung","Wassereinlagerungen (Ödeme)"],"unbekannt":["Osteosarkom (Knochenkrebs): in Tierversuchen gehäuft, beim Menschen nur sehr vereinzelt berichtet"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter müssen während der Behandlung wirksam verhüten; bei einer Schwangerschaft wird Teriparatid abgesetzt.","stillzeit":"Kontraindiziert (nicht bekannt, ob Teriparatid in die Muttermilch übergeht).","hinweise":["Einmal täglich in Oberschenkel oder Bauch spritzen, möglichst immer zur gleichen Tageszeit; den Pen im Kühlschrank lagern.","Die ersten Injektionen im Sitzen oder Liegen verabreichen – Schwindel durch Blutdruckabfall möglich; bei Schwindel nicht Auto fahren.","Gesamtdauer höchstens 24 Monate; danach wird meist mit einem knochenabbauhemmenden Mittel weiterbehandelt, damit der Gewinn an Knochenmasse erhalten bleibt.","Anhaltende Übelkeit, Verstopfung, Müdigkeit oder Muskelschwäche (mögliche Zeichen eines zu hohen Calciums) ärztlich melden."],"darreichung":["Injektionslösung im Fertigpen (zur Injektion unter die Haut)"]},"terlipressin":{"wirkmechanismus":"Verengt die Blutgefässe im Bauchraum und senkt so den Druck in den Krampfadern der Speiseröhre. Terlipressin ist eine Vorstufe (Prodrug), aus der im Körper langsam Lysin-Vasopressin freigesetzt wird. Dieses wirkt über Vasopressin-V1-Rezeptoren gefässverengend, vor allem im Splanchnikusgebiet, wodurch der Pfortaderdruck sinkt. Beim hepatorenalen Syndrom verbessert die Umverteilung des Blutes die Nierendurchblutung und -funktion.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Bradykardie (langsamer Puls)","Bluthochdruck","Periphere Durchblutungsstörungen, Blässe (kalte Hände und Füsse)","Vorübergehende Bauchkrämpfe, Durchfall"],"gelegentlich":["Herzrhythmusstörungen (Vorhofflimmern, Extrasystolen, Herzrasen)","Brustschmerzen, Herzinfarkt","Lungenödem durch Flüssigkeitsüberladung","Darmischämie (Minderdurchblutung des Darms)","Übelkeit, Erbrechen","Hautnekrose (Absterben von Haut), auch an der Injektionsstelle","Gebärmutterkrämpfe","Auslösung von Krampfanfällen"],"unbekannt":["Atemversagen, Atemnot (v. a. beim hepatorenalen Syndrom)","Torsade de pointes (gefährliche Herzrhythmusstörung), QT-Verlängerung","Herzinsuffizienz","Hyponatriämie (Natriummangel)"]},"schwangerschaft":"Kontraindiziert: Terlipressin löst Gebärmutterkontraktionen aus, vermindert die Durchblutung der Gebärmutter und kann eine Fehlgeburt verursachen.","stillzeit":"Nicht bekannt, ob Terlipressin in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Wird nur im Spital unter Überwachung von Blutdruck, Puls, EKG, Sauerstoffsättigung, Flüssigkeitshaushalt und Elektrolyten angewendet.","Atemnot, Brustschmerzen oder Schmerzen in Bauch, Händen oder Füssen sofort dem Behandlungsteam melden.","Beim hepatorenalen Syndrom wird die Albumin-Gabe angepasst, um eine Flüssigkeitsüberladung zu vermeiden."],"darreichung":["Injektionslösung","Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"testosteron":{"wirkmechanismus":"Ersetzt das körpereigene männliche Geschlechtshormon, wenn die Hoden zu wenig davon bilden. Testosteron bindet an Androgenrezeptoren, teils direkt, teils nach Umwandlung durch die 5-Alpha-Reduktase in das stärker wirksame Dihydrotestosteron; ein Teil wird durch Aromatase in Estradiol umgewandelt. Es fördert männliche Geschlechtsmerkmale, Libido und Potenz, Muskelmasse, Knochendichte und die Bildung roter Blutkörperchen. Als Ester (Undecanoat, Enantat) in öliger Lösung wird es aus dem Muskel langsam freigesetzt; das Gel wird über die Haut aufgenommen.","nebenwirkungen":{"haeufig":["Erhöhter Hämatokrit und Hämoglobin (zu viele rote Blutkörperchen, Polyzythämie)","Akne","Gewichtszunahme","Hitzewallungen","Anstieg des PSA-Werts, Prostataveränderungen","Reaktionen an der Einstich- oder Auftragsstelle (Schmerzen, Bluterguss, Hautrötung)"],"gelegentlich":["Bluthochdruck","Kopfschmerzen, Schwindel","Stimmungsschwankungen, Depression, Aggressivität, Schlaflosigkeit","Veränderte Libido","Brustvergrösserung (Gynäkomastie), Brustspannen, Hodenschmerzen","Erhöhte Leberwerte, veränderte Blutfette","Wassereinlagerungen (Ödeme)","Haarausfall, Juckreiz, fettige Haut, vermehrtes Schwitzen"],"selten":["Ölmikroembolie der Lunge während oder kurz nach der Depotspritze (Husten, Atemnot, Unwohlsein, Schwindel)","Schwere allergische Reaktionen nach der Injektion"],"unbekannt":["Venöse Thromboembolie (Thrombose, Lungenembolie)","Verminderte Spermienbildung, Verkleinerung der Hoden (vor allem bei hoher Dosis)","Lebertumoren bei langdauernder hoch dosierter Anwendung","Verschlechterung einer Schlafapnoe","Häufige oder schmerzhaft anhaltende Erektionen (Priapismus)"]},"schwangerschaft":"Kontraindiziert: Testosteron kann beim ungeborenen Mädchen eine Vermännlichung verursachen. Schwangere dürfen nicht mit Testosteron-Gel in Hautkontakt kommen.","stillzeit":"Kontraindiziert; Testosteronpräparate sind nicht für Frauen bestimmt.","hinweise":["Vor und während der Behandlung regelmässig Blutbild (Hämatokrit), PSA und Prostata, Leberwerte und Blutfette kontrollieren lassen.","Gel: Nach dem Auftragen Hände waschen und die Stelle nach dem Trocknen mit Kleidung bedecken – Hautkontakt kann Frauen und Kinder vermännlichen.","Nicht zur Leistungssteigerung oder zum Muskelaufbau missbrauchen: Gefahr schwerer Herz-, Leber- und psychischer Schäden; im Sport als Doping verboten.","Hohe Dosen hemmen die Spermienbildung (meist umkehrbar) – bei Kinderwunsch ärztlich besprechen."],"darreichung":["Depot-Injektionslösung (ölig, intramuskulär)","Gel zum Auftragen auf die Haut"]},"tetanus-immunglobulin":{"wirkmechanismus":"Gibt dem Körper sofort fertige Antikörper gegen das Tetanusgift (passive Immunisierung). Das Präparat enthält aus Spenderplasma gewonnene menschliche Immunglobuline (IgG) mit hohem Gehalt an Antikörpern gegen Tetanustoxin. Diese neutralisieren das frei zirkulierende Gift, bevor es an Nervenzellen bindet; bereits gebundenes Gift wird nicht mehr erreicht. Der Schutz hält einige Wochen an, deshalb wird gleichzeitig aktiv geimpft.","nebenwirkungen":{"unbekannt":["Schmerzen, Schwellung und Rötung an der Einstichstelle","Fieber, Schüttelfrost","Hautreaktionen (Ausschlag, Juckreiz)","Übelkeit, Erbrechen","Kreislaufreaktionen (Blutdruckabfall, Herzrasen)","Allergische Reaktionen bis zum anaphylaktischen Schock"]},"schwangerschaft":"Kann angewendet werden. Die langjährige Erfahrung mit Immunglobulinen zeigt keine schädlichen Wirkungen auf Schwangerschaft, Ungeborenes oder Neugeborenes.","stillzeit":"Kann angewendet werden; Immunglobuline gehen in die Muttermilch über und schaden dem Kind nicht.","hinweise":["Bei einer Verletzung gleichzeitig die Tetanusimpfung beginnen oder auffrischen (an einer anderen Körperstelle).","Lebendimpfungen (z. B. Masern, Mumps, Röteln, Windpocken) erst 3 Monate später.","Nach der Gabe können Antikörpertests im Blut vorübergehend falsch positiv ausfallen."],"darreichung":["Injektionslösung in Fertigspritze (intramuskulär)"]},"tetrabenazin":{"wirkmechanismus":"Vermindert unwillkürliche Bewegungen, indem es die Menge an Botenstoffen wie Dopamin in den Nervenzellen des Gehirns senkt. Tetrabenazin hemmt reversibel den vesikulären Monoamintransporter 2 (VMAT2), der Dopamin, Serotonin und Noradrenalin in Speicherbläschen der Nervenendigungen pumpt. Die ungeschützten Monoamine werden abgebaut, sodass vor allem die dopaminerge Signalübertragung im Striatum abnimmt. Wirksam sind hauptsächlich die Metaboliten alpha- und beta-Dihydrotetrabenazin, die über CYP2D6 weiter abgebaut werden.","nebenwirkungen":{"sehrHaeufig":["Depression","Schläfrigkeit (Somnolenz)","Parkinson-ähnliche Beschwerden (Steifheit, Zittern, Gleichgewichtsstörungen)"],"haeufig":["Angst, Unruhe, Verwirrtheit","Schlaflosigkeit","Schluckbeschwerden (Dysphagie)","Übelkeit, Erbrechen","Durchfall oder Verstopfung"],"selten":["Malignes neuroleptisches Syndrom (hohes Fieber, Muskelsteife, Bewusstseinsstörung)"],"unbekannt":["Suizidgedanken und suizidales Verhalten","QT-Verlängerung","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Akathisie (quälende Bewegungsunruhe)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach strenger ärztlicher Abwägung anwenden.","stillzeit":"Kontraindiziert.","hinweise":["Kann Müdigkeit verursachen – Vorsicht beim Autofahren; Alkohol meiden.","Niedergeschlagenheit, Suizidgedanken oder hohes Fieber mit Muskelsteife sofort ärztlich melden.","Die Dosis wird langsam gesteigert; nicht eigenmächtig verändern."],"darreichung":["Tabletten"]},"tetracosactid":{"wirkmechanismus":"Regt die Nebennierenrinde an, Kortisol zu bilden – so lässt sich prüfen, ob sie normal arbeitet. Tetracosactid entspricht den ersten 24 Aminosäuren des körpereigenen ACTH (Corticotropin) und bindet an die ACTH-Rezeptoren (MC2-Rezeptoren) der Nebennierenrinde. Diese schüttet daraufhin Kortisol und in geringerem Mass Mineralokortikoide und Androgene aus. Bleibt der Kortisolanstieg im Test aus, spricht das für eine Nebenniereninsuffizienz; die Depotform wirkt über die anhaltende Kortisolbildung wie eine Kortisonbehandlung.","nebenwirkungen":{"unbekannt":["Überempfindlichkeitsreaktionen bis Anaphylaxie (Atemnot, Hautausschlag, Kreislaufkollaps)","Reaktionen an der Injektionsstelle","Gesichtsrötung, Schwindel, Übelkeit","Depotform: Wassereinlagerung, Bluthochdruck, erhöhter Blutzucker, Kaliummangel","Depotform: dunklere Hautpigmentierung, Akne","Depotform: psychische Veränderungen (Euphorie, Schlaflosigkeit, Verstimmung)","Depotform: Knochenschwund, erhöhte Infektanfälligkeit"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Daten sind begrenzt.","stillzeit":"Nur nach ärztlicher Abwägung.","hinweise":["Wird von Fachpersonen gespritzt; danach mindestens 30 Minuten Überwachung wegen möglicher allergischer Reaktionen.","Vor dem Test angeben, welche Hormon- und Kortisonpräparate eingenommen werden.","Bei der Depotform wie bei einer Kortisonbehandlung Blutdruck, Blutzucker und Kalium kontrollieren."],"darreichung":["Injektionslösung","Depot-Injektionssuspension"]},"tetryzolin":{"wirkmechanismus":"Verengt die erweiterten Blutgefässe der Bindehaut und lässt so Rötung und Schwellung abklingen. Tetryzolin ist ein Imidazolin-Derivat, das Alpha-Adrenozeptoren an den Gefässen stimuliert. Die Wirkung tritt innert Minuten ein und hält einige Stunden an. Bei längerer Anwendung kann nach Abklingen der Wirkung eine verstärkte Rötung auftreten (Rebound-Effekt).","nebenwirkungen":{"unbekannt":["Vorübergehendes Brennen oder Stechen, Augenreizung","Verstärkte Rötung nach Abklingen der Wirkung (reaktive Hyperämie), vor allem bei längerer Anwendung","Pupillenerweiterung, verschwommenes Sehen","Herzklopfen, Blutdruckanstieg, Kopfschmerzen, Zittern, Schwitzen","Bei Kleinkindern nach Verschlucken: Benommenheit, langsamer Puls, Atemstörungen, Unterkühlung"]},"schwangerschaft":"Nur nach ärztlicher Abwägung anwenden; Daten zur Anwendung in der Schwangerschaft fehlen.","stillzeit":"Nur nach ärztlicher Abwägung anwenden; Daten zur Stillzeit fehlen.","hinweise":["Ohne ärztlichen Rat nur wenige Tage anwenden; bei anhaltender Rötung Arzt, Ärztin oder Apotheke aufsuchen.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen.","Für Kinder unerreichbar aufbewahren: Verschlucken kann bei Kleinkindern gefährlich sein."],"darreichung":["Augentropfen"]},"tezacaftor-ivacaftor":{"wirkmechanismus":"Hilft, mehr funktionsfähige CFTR-Chloridkanäle an die Zelloberfläche zu bringen und deren Öffnung zu verbessern. Tezacaftor ist ein CFTR-Korrektor, der die Faltung und den Transport des veränderten CFTR-Proteins zur Zellmembran verbessert. Ivacaftor ist ein Potentiator, der die Öffnungswahrscheinlichkeit der Kanäle erhöht. Zusammen steigt der Chloridtransport und die Lungenfunktion bessert sich.","nebenwirkungen":{"sehrHaeufig":["Kopfschmerzen","Nasen-Rachen-Entzündung, Infektionen der oberen Atemwege","Bauchschmerzen, Durchfall","Hautausschlag","Erhöhte Leberwerte (Transaminasen)","Bakterien im Auswurf (Sputum)"],"haeufig":["Schwindel","Übelkeit","Verstopfte Nebenhöhlen, Schnupfen, Rötung im Rachen","Ohrenschmerzen, Ohrgeräusche (Tinnitus)","Knoten in der Brust"],"gelegentlich":["Brustentzündung, Brustvergrösserung beim Mann (Gynäkomastie)","Druckgefühl im Ohr"],"unbekannt":["Linsentrübung (Katarakt) bei Kindern"]},"schwangerschaft":"Begrenzte Erfahrungen; vorsichtshalber möglichst vermeiden bzw. nur nach ärztlicher Abwägung.","stillzeit":"Ob die Wirkstoffe in die Muttermilch übergehen, ist nicht bekannt; Nutzen und Risiko ärztlich abwägen.","hinweise":["Morgens die Kombinationstablette, abends die Ivacaftor-Tablette einnehmen, jeweils mit einer fetthaltigen Mahlzeit und im Abstand von etwa 12 Stunden.","Grapefruit und Bitterorangen meiden.","Leberwerte regelmässig kontrollieren, bei Kindern zusätzlich augenärztliche Untersuchungen."],"darreichung":["Filmtabletten"]},"tezepelumab":{"wirkmechanismus":"Setzt am Anfang der Entzündungskette in den Atemwegen an. Tezepelumab bindet den Botenstoff TSLP, den die Bronchialschleimhaut bei Kontakt mit Allergenen, Viren oder Schadstoffen ausschüttet, und verhindert dessen Bindung an seinen Rezeptor. Dadurch werden mehrere Entzündungswege gleichzeitig gedämpft: Eosinophile im Blut, das Gesamt-IgE und das ausgeatmete Stickstoffmonoxid (FeNO) sinken. Die Wirkung ist nicht auf eine bestimmte Asthmaform (eosinophil oder allergisch) beschränkt.","nebenwirkungen":{"haeufig":["Rachenentzündung (Pharyngitis)","Hautausschlag","Gelenkschmerzen (Arthralgie)","Reaktionen an der Einstichstelle (Rötung, Schwellung, Schmerz)"],"unbekannt":["Überempfindlichkeitsreaktionen bis zur Anaphylaxie"]},"schwangerschaft":"Begrenzte Erfahrungen; Antikörper gehen über die Plazenta auf das Kind über. Vorzugsweise nicht anwenden, ausser der Nutzen für die Mutter überwiegt das mögliche Risiko für das Kind.","stillzeit":"Nicht bekannt, ob Tezepelumab in die Muttermilch übergeht; Anwendung nach ärztlicher Abwägung.","hinweise":["Wird alle 4 Wochen unter die Haut gespritzt; nach Schulung ist die Selbstinjektion mit Fertigpen oder Fertigspritze möglich.","Im Kühlschrank lagern, nicht einfrieren.","Bei Atemnot, Ausschlag oder Schwellungen nach der Injektion sofort ärztliche Hilfe holen.","Asthma- und Kortisonmedikamente nicht eigenmächtig absetzen."],"darreichung":["Injektionslösung (Fertigpen, Fertigspritze)"]},"thalidomid":{"wirkmechanismus":"Hemmt das Wachstum von Myelomzellen und beeinflusst das Immunsystem. Thalidomid bindet an das Protein Cereblon, einen Teil eines Ubiquitin-Ligase-Komplexes, und führt so zum Abbau der Transkriptionsfaktoren Ikaros und Aiolos. Daraus ergeben sich eine direkte wachstumshemmende Wirkung auf Myelomzellen, eine Immunmodulation (u. a. Hemmung von TNF-alpha) und eine Hemmung der Gefässneubildung (Angiogenese). Die Bindung an Cereblon erklärt auch die schwere fruchtschädigende Wirkung.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie und Thrombozytopenie (Blutbildveränderungen)","Periphere Neuropathie (Kribbeln, Taubheit, Schmerzen in Händen und Füssen)","Zittern (Tremor), Schwindel, Missempfindungen","Schläfrigkeit","Obstipation (Verstopfung)","Periphere Ödeme (Wassereinlagerungen in den Beinen)"],"haeufig":["Lungenentzündung","Tiefe Venenthrombose und Lungenembolie","Herzschwäche und Bradykardie (langsamer Puls)","Depression, Verwirrtheit","Atemnot, interstitielle Lungenerkrankung","Erbrechen, Mundtrockenheit","Hautausschlag, trockene Haut","Akute myeloische Leukämie (zweite Krebserkrankung)"],"gelegentlich":["Vorhofflimmern, AV-Block (Reizleitungsstörung)","Magen-Darm-Durchbruch (Perforation)","Myelodysplastisches Syndrom"],"unbekannt":["Schwere Hautreaktionen (Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse, DRESS)","Tumorlyse-Syndrom","Herzinfarkt und Schlaganfall","Reaktivierung einer Hepatitis B","Progressive multifokale Leukenzephalopathie (PML, schwere Hirninfektion)","Schilddrüsenunterfunktion","Hörstörungen","Allergische Reaktionen, Angioödem"]},"schwangerschaft":"Kontraindiziert: Thalidomid verursacht schwerste Fehlbildungen (z. B. der Gliedmassen) und Fehlgeburten. Frauen im gebärfähigen Alter müssen von 4 Wochen vor bis 4 Wochen nach der Behandlung zuverlässig verhüten und regelmässig Schwangerschaftstests machen.","stillzeit":"Während der Behandlung darf nicht gestillt werden.","hinweise":["Strenges Schwangerschaftsverhütungsprogramm: Frauen verhüten von 4 Wochen vor bis 4 Wochen nach der Therapie; Männer verwenden während und bis 7 Tage nach der Therapie Kondome (auch nach Vasektomie).","Während und bis 7 Tage nach der Behandlung kein Blut und keinen Samen spenden. Kapseln nicht öffnen, nicht weitergeben und unverbrauchte Kapseln in der Apotheke zurückgeben.","Wegen Schläfrigkeit am besten abends einnehmen; Fahrtüchtigkeit kann eingeschränkt sein, Alkohol meiden.","Bei Kribbeln oder Taubheit in Händen oder Füssen, Atemnot, Brustschmerzen oder geschwollenen Beinen sofort ärztliche Hilfe holen."],"darreichung":["Kapseln"]},"theophyllin":{"wirkmechanismus":"Erweitert die Bronchien und regt die Atmung an. Theophyllin hemmt unselektiv Phosphodiesterasen, wodurch cAMP in der Bronchialmuskulatur ansteigt, und blockiert Adenosinrezeptoren. Folge sind eine Entspannung der Bronchialmuskulatur, eine Anregung des Atemzentrums, eine bessere Kraft der Atemmuskulatur und leicht entzündungshemmende Effekte. Wirkung und Nebenwirkungen hängen eng vom Blutspiegel ab; abgebaut wird Theophyllin in der Leber vor allem über CYP1A2.","nebenwirkungen":{"unbekannt":["Übelkeit, Erbrechen, Bauchschmerzen, Durchfall","Sodbrennen (Reflux)","Kopfschmerzen, Unruhe, Schlaflosigkeit, Zittern","Herzrasen (Tachykardie), Herzklopfen, Herzrhythmusstörungen","Krampfanfälle, vor allem bei zu hohen Blutspiegeln","Hypokaliämie (Kaliummangel), erhöhter Blutzucker, erhöhte Harnsäure","Vermehrtes Wasserlassen","Überempfindlichkeitsreaktionen (Hautausschlag, Juckreiz)"]},"schwangerschaft":"Theophyllin geht auf das Kind über; Anwendung nur nach strenger ärztlicher Abwägung und mit Spiegelkontrollen. Kurz vor der Geburt angewendet kann es beim Neugeborenen Herzrasen und Unruhe auslösen.","stillzeit":"Geht in die Muttermilch über und kann beim Säugling Unruhe und Schlafstörungen auslösen; nur nach ärztlicher Abwägung, den Säugling beobachten.","hinweise":["Retardtabletten unzerkaut mit Flüssigkeit einnehmen, regelmässig zur gleichen Zeit.","Blutspiegel regelmässig kontrollieren lassen; Übelkeit, Erbrechen, Herzrasen oder Unruhe können erste Zeichen einer Überdosierung sein.","Rauchstopp, Fieber oder neue Medikamente (besonders Antibiotika) der Ärztin oder dem Arzt melden – die Dosis muss eventuell angepasst werden.","Grosse Mengen Kaffee, Schwarztee, Cola und Energydrinks meiden."],"darreichung":["Retardtabletten"]},"thiamin-vitamin-b1":{"wirkmechanismus":"Ersetzt Vitamin B1, das Nerven, Herz und Muskeln für die Energiegewinnung aus Kohlenhydraten brauchen. Im Körper wird Thiamin zu Thiaminpyrophosphat umgewandelt, einem Coenzym der Pyruvat-Dehydrogenase, der Alpha-Ketoglutarat-Dehydrogenase und der Transketolase. Bei Mangel stockt der Zuckerabbau, was vor allem das Nervensystem (Polyneuropathie, Wernicke-Enzephalopathie) und das Herz (Beriberi) schädigt. Der Körper speichert nur wenig Thiamin, sodass bei Alkoholkrankheit, Mangelernährung oder anhaltendem Erbrechen rasch ein Mangel entsteht.","nebenwirkungen":{"sehrSelten":["Überempfindlichkeitsreaktionen mit Schwitzen, Herzrasen, Juckreiz und Nesselsucht","Anaphylaktischer Schock, vor allem nach Injektion"],"unbekannt":["Schmerzen oder Reizung an der Injektionsstelle"]},"schwangerschaft":"In Dosen zur Bedarfsdeckung und zur Behandlung eines nachgewiesenen Mangels erlaubt.","stillzeit":"Erlaubt; Thiamin geht in die Muttermilch über, schadet dem Kind in üblichen Dosen aber nicht.","hinweise":["Bei Alkoholkrankheit und Mangelernährung wird Thiamin vor Glucosegaben verabreicht.","Tabletten unzerkaut mit etwas Flüssigkeit einnehmen.","Bei Atemnot, Schwellungen oder Hautausschlag nach einer Injektion sofort ärztliche Hilfe holen."],"darreichung":["Tabletten","Injektionslösung"]},"thiopental":{"wirkmechanismus":"Führt innerhalb von Sekunden zu tiefem Schlaf. Thiopental verstärkt die hemmende Wirkung des Botenstoffs GABA am GABA-A-Rezeptor, indem es die Öffnungsdauer der Chloridkanäle verlängert; in hoher Dosis öffnet es diese auch direkt. Wegen der hohen Fettlöslichkeit erreicht es das Gehirn sehr schnell; die kurze Wirkung beruht auf der Umverteilung in Muskel- und Fettgewebe. Weil der Abbau in der Leber langsam ist, kann es sich bei wiederholter Gabe anreichern. Es senkt Hirnstoffwechsel und Hirndruck.","nebenwirkungen":{"unbekannt":["Atemdepression bis Atemstillstand","Blutdruckabfall, Herzrhythmusstörungen, Herzdämpfung","Husten, Niesen, Laryngospasmus (Stimmritzenkrampf), Bronchospasmus","Allergische Reaktionen bis Anaphylaxie","Schwere Gewebeschäden bei Injektion neben die Vene; Gefässverschluss bis Gangrän bei Injektion in eine Arterie","Schläfrigkeit, Verwirrtheit und verzögertes Erwachen (Nachschlaf)","Übelkeit, Erbrechen, Kopfschmerzen","Kältezittern in der Aufwachphase"]},"schwangerschaft":"Thiopental gelangt rasch zum Ungeborenen; Anwendung nur bei klarer Notwendigkeit, z. B. zur Narkoseeinleitung beim Kaiserschnitt.","stillzeit":"Thiopental geht in die Muttermilch über; nach der Gabe für eine gewisse Zeit nicht stillen – die Dauer legt die Ärztin oder der Arzt fest.","hinweise":["Wird nur im Spital durch Anästhesiefachpersonen mit Beatmungsmöglichkeit verabreicht.","Bekannte Porphyrie oder eine Unverträglichkeit von Barbituraten vor der Narkose angeben.","Nach der Narkose mindestens 24 Stunden kein Fahrzeug lenken, keine Maschinen bedienen und keinen Alkohol trinken."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"thiotepa":{"wirkmechanismus":"Hemmt die Vermehrung von Krebs- und blutbildenden Zellen, indem es ihr Erbgut schädigt. Thiotepa ist ein polyfunktionelles Alkylans mit drei Ethylenimin-(Aziridin-)Gruppen, die DNA-Stränge vernetzen. In der Leber wird es durch CYP3A4 und CYP2B6 zum ebenfalls wirksamen TEPA umgewandelt. Es gelangt gut ins Gehirn und hemmt selbst das Enzym CYP2B6.","nebenwirkungen":{"sehrHaeufig":["Infektionen","Knochenmarkhemmung (Neutropenie, Thrombozytopenie, Anämie), Fieber bei Neutropenie","Graft-versus-Host-Krankheit (nach allogener Transplantation)","Übelkeit, Erbrechen, Durchfall, Mundschleimhautentzündung","Appetitlosigkeit","Hautausschlag, Juckreiz, Haarausfall, Hautverfärbung","Erhöhte Leberwerte und Bilirubin","Fieber, Ödeme"],"haeufig":["Lebervenenverschlusskrankheit (VOD/SOS)","Blutige Blasenentzündung (hämorrhagische Zystitis)","Kopfschmerzen, Schwindel, Verwirrtheit","Herzrhythmusstörungen","Lungenentzündung (Pneumonitis)","Ausbleiben der Menstruation, Unfruchtbarkeit"],"unbekannt":["Zweitkrebs","Enzephalopathie, posteriores reversibles Enzephalopathie-Syndrom (PRES)","Herzschwäche","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse"]},"schwangerschaft":"Kontraindiziert. Frauen und Männer müssen während und nach der Behandlung (Dauer gemäss ärztlicher Anweisung) sicher verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Wird nur in spezialisierten Zentren als Infusion gegeben.","Während und bis 48 Stunden nach der Infusion mindestens zweimal täglich duschen oder baden und Kleidung sowie Bettwäsche wechseln, da Thiotepa über die Haut ausgeschieden wird.","Blutbild und Leberwerte werden engmaschig kontrolliert; Fieber sofort melden.","Vor Behandlungsbeginn Möglichkeiten zum Fruchtbarkeitserhalt besprechen."],"darreichung":["Pulver zur Herstellung eines Konzentrats für eine Infusionslösung"]},"thyrotropin-alfa":{"wirkmechanismus":"Stimuliert verbliebene Schilddrüsen- und Schilddrüsenkrebszellen, ohne dass die Schilddrüsenhormone abgesetzt werden müssen. Thyrotropin alfa ist gentechnisch hergestelltes humanes TSH und bindet an die TSH-Rezeptoren von normalem Schilddrüsengewebe und gut differenzierten Schilddrüsenkrebszellen. Diese nehmen dadurch vermehrt radioaktives Jod auf und setzen Thyreoglobulin frei. So sind Nachsorgeuntersuchungen und Radiojod-Ablation ohne die belastende Schilddrüsenunterfunktion durch Hormonentzug möglich.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Erbrechen","Kopfschmerzen, Schwindel","Müdigkeit, Schwäche"],"gelegentlich":["Durchfall","Grippeähnliche Beschwerden, Fieber, Schüttelfrost","Hitzewallungen","Geschmacksstörung, Kribbeln","Hautausschlag, Nesselsucht","Nacken- und Rückenschmerzen"],"unbekannt":["Schwellung oder Schmerzen von Tumoren bzw. Metastasen","Schlaganfall","Herzklopfen","Überempfindlichkeitsreaktionen","Zittern"]},"schwangerschaft":"Kontraindiziert.","stillzeit":"Während der Anwendung nicht stillen; bei einer Radiojodbehandlung muss ohnehin abgestillt werden.","hinweise":["Zwei Injektionen in den Gesässmuskel im Abstand von 24 Stunden; nie in die Vene.","Die Schilddrüsenhormone werden normal weiter eingenommen.","Neue neurologische Beschwerden (z. B. Lähmungen, Sprachstörungen) oder Schwellungen im Halsbereich sofort melden."],"darreichung":["Pulver zur Herstellung einer Injektionslösung"]},"tiaprid":{"wirkmechanismus":"Dämpft unwillkürliche Bewegungen und Unruhe, ohne stark zu sedieren. Tiaprid ist ein Benzamid, das selektiv Dopamin-D2- und D3-Rezeptoren blockiert, besonders in überaktiven Bereichen des Striatums und des limbischen Systems. Histamin-, Muskarin- und Alpha-Rezeptoren werden kaum beeinflusst. Es wird überwiegend unverändert über die Niere ausgeschieden.","nebenwirkungen":{"haeufig":["Schwindel, Kopfschmerzen","Schläfrigkeit, Schlaflosigkeit, Unruhe, Gleichgültigkeit","Müdigkeit, Schwäche"],"gelegentlich":["Extrapyramidale Störungen (Zittern, Muskelsteifigkeit, vermehrter Speichelfluss), Akathisie (Sitzunruhe)","Gewichtszunahme","Milchfluss, Ausbleiben der Regel, Brustschmerzen oder -vergrösserung","Sexuelle Funktionsstörungen"],"selten":["Akute Dystonie (Muskelverkrampfungen, Blickkrämpfe)"],"unbekannt":["Spätdyskinesien (unwillkürliche Bewegungen)","Malignes neuroleptisches Syndrom (Fieber, Muskelsteifigkeit, Bewusstseinsstörung)","QT-Verlängerung, Torsade de pointes (lebensgefährliche Herzrhythmusstörung), plötzlicher Herztod","Krampfanfälle","Hyponatriämie (Natriummangel)","Venöse Thromboembolien (Blutgerinnsel)","Stürze und Lungenentzündung durch Verschlucken, v. a. bei älteren Menschen"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung. Bei Einnahme im letzten Drittel können beim Neugeborenen Bewegungsstörungen und Entzugssymptome auftreten.","stillzeit":"Stillen wird nicht empfohlen.","hinweise":["Kann die Reaktionsfähigkeit beeinträchtigen – Vorsicht beim Autofahren, Alkohol meiden.","Bei eingeschränkter Nierenfunktion ist eine tiefere Dosis nötig.","Bei Fieber mit Muskelsteifigkeit und Verwirrtheit sofort ärztliche Hilfe holen (malignes neuroleptisches Syndrom)."],"darreichung":["Tabletten"]},"tibolon":{"wirkmechanismus":"Lindert Wechseljahresbeschwerden, indem es im Körper in mehrere hormonähnlich wirkende Stoffe umgewandelt wird. Die Metaboliten 3-alpha- und 3-beta-Hydroxytibolon wirken östrogen (gegen Hitzewallungen und Knochenabbau), das Delta-4-Isomer wirkt gestagen und androgen. Die gestagene Wirkung auf die Gebärmutterschleimhaut macht einen zusätzlichen Gestagenschutz überflüssig.","nebenwirkungen":{"haeufig":["Unterleibs- und Beckenschmerzen","Vaginale Blutungen oder Schmierblutungen","Verdickung der Gebärmutterschleimhaut","Brustspannen","Vaginale Pilzinfektion, Ausfluss, Juckreiz im Genitalbereich","Vermehrte Körperbehaarung","Gewichtszunahme","Auffälliger Krebsabstrich (Zervixdysplasie)"],"gelegentlich":["Akne","Brustbeschwerden, Brustwarzenschmerzen","Wassereinlagerungen (Ödeme)","Pilzinfektionen"],"unbekannt":["Schlaganfall, venöse Thromboembolie","Brustkrebs, Gebärmutterschleimhautkrebs","Kopfschmerzen, Migräne, Schwindel, Depression","Sehstörungen","Hautausschlag, Juckreiz","Gelenk- und Muskelschmerzen","Veränderte Leberwerte"]},"schwangerschaft":"Kontraindiziert. Tritt eine Schwangerschaft ein, sofort absetzen.","stillzeit":"Kontraindiziert.","hinweise":["Frühestens 12 Monate nach der letzten natürlichen Menstruation beginnen, sonst sind unregelmässige Blutungen häufig; Tibolon verhütet nicht.","Täglich zur gleichen Zeit einnehmen; ein zusätzliches Gestagen ist nicht nötig.","Blutungen nach mehr als 6 Monaten Anwendung oder nach Absetzen ärztlich abklären lassen.","Wer Blutverdünner wie Phenprocoumon oder Acenocoumarol einnimmt, braucht anfangs engmaschige INR-Kontrollen."],"darreichung":["Tabletten"]},"ticagrelor":{"wirkmechanismus":"Verhindert, dass Blutplättchen verklumpen und Gerinnsel in den Herzkranzgefässen bilden. Ticagrelor blockiert den ADP-Rezeptor P2Y12 der Blutplättchen direkt und reversibel; es muss nicht erst in der Leber aktiviert werden und wirkt deshalb rasch und unabhängig vom CYP2C19-Stoffwechsel. Weil die Bindung umkehrbar ist, lässt die Wirkung nach dem Absetzen innerhalb weniger Tage nach. Zusätzlich hemmt Ticagrelor die Wiederaufnahme von Adenosin, was die häufige Atemnot erklären könnte. Der Abbau erfolgt über CYP3A4.","nebenwirkungen":{"sehrHaeufig":["Blutungen (z. B. Blutergüsse, Nasenbluten)","Dyspnoe (Atemnot, meist leicht und vorübergehend)","Hyperurikämie (erhöhte Harnsäure)"],"haeufig":["Gicht","Schwindel, Kopfschmerzen, Ohnmacht","Tiefer Blutdruck","Magen-Darm-Blutungen und Blutungen der Atemwege","Durchfall, Übelkeit, Verdauungsbeschwerden, Verstopfung","Hautausschlag, Juckreiz, Hautblutungen","Blutungen der Harnwege, erhöhtes Kreatinin","Nachblutungen nach Eingriffen und nach Verletzungen"],"gelegentlich":["Hirnblutung","Überempfindlichkeitsreaktionen einschliesslich Angioödem","Verwirrtheit","Augen- und Ohrenblutungen","Blutungen im hinteren Bauchraum (retroperitoneal), Muskelblutungen","Blutungen aus Tumoren"],"unbekannt":["Thrombotisch-thrombozytopenische Purpura (TTP)","Bradyarrhythmie (zu langsamer Herzschlag, Rhythmuspausen)","Zentrale Schlafapnoe einschliesslich Cheyne-Stokes-Atmung"]},"schwangerschaft":"Nicht empfohlen; Frauen im gebärfähigen Alter sollen während der Behandlung sicher verhüten.","stillzeit":"Ticagrelor geht im Tierversuch in die Milch über; Stillen oder Behandlung abbrechen – ärztlich entscheiden.","hinweise":["Nicht eigenmächtig absetzen – erhöhtes Risiko für Herzinfarkt, Stentverschluss und Tod.","Atemnot ist häufig und meist harmlos; bei starker oder zunehmender Atemnot ärztlich abklären lassen.","Vor Operationen und Zahnbehandlungen die Einnahme angeben; ein Pausieren (meist 5 Tage vorher) nur nach ärztlicher Anordnung.","Tabletten dürfen zerstossen und in Wasser eingenommen werden; neue Medikamente (auch Antibiotika, Pilzmittel, Johanniskraut) in der Apotheke prüfen lassen."],"darreichung":["Filmtabletten"]},"tigecyclin":{"wirkmechanismus":"Hemmt das Wachstum eines breiten Spektrums von Bakterien, darunter MRSA, vancomycinresistente Enterokokken und viele ESBL-bildende Darmbakterien. Tigecyclin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und verhindert die Anlagerung der Transfer-RNA, sodass die Eiweisssynthese stoppt (bakteriostatisch). Dank seiner Struktur umgeht es die typischen Resistenzmechanismen gegen Tetracycline (Effluxpumpen, ribosomaler Schutz). Gegen Pseudomonas aeruginosa und Proteus wirkt es nicht.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Erbrechen","Durchfall"],"haeufig":["Bauchschmerzen, Verdauungsbeschwerden, Appetitlosigkeit","Kopfschmerzen, Schwindel","Erhöhte Leberwerte und erhöhtes Bilirubin","Verlängerte Gerinnungszeiten (aPTT, Prothrombinzeit)","Hypoglykämie (Unterzuckerung)","Venenentzündung an der Infusionsstelle","Juckreiz, Hautausschlag","Infektionen wie Lungenentzündung, Abszesse oder Sepsis"],"gelegentlich":["Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Gelbsucht, Leberschädigung","Thrombozytopenie (Mangel an Blutplättchen)","Thrombophlebitis (Venenentzündung mit Gerinnsel)"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Leberversagen","Stevens-Johnson-Syndrom","Hypofibrinogenämie (Mangel am Gerinnungseiweiss Fibrinogen)","Pseudomembranöse Kolitis (schwere Darmentzündung)"]},"schwangerschaft":"Nur anwenden, wenn unbedingt erforderlich: Tigecyclin kann dem Ungeborenen schaden und wie andere Tetracycline bleibende Zahnverfärbungen verursachen.","stillzeit":"Nicht bekannt, ob Tigecyclin beim Menschen in die Muttermilch übergeht (im Tierversuch ja). Ärztlich entscheiden, ob abgestillt oder auf die Behandlung verzichtet wird.","hinweise":["Wird im Spital als Infusion über 30–60 Minuten gegeben.","Starke Oberbauchschmerzen, Gelbsucht oder Blutungszeichen sofort melden.","Während der Behandlung werden Leber- und Gerinnungswerte kontrolliert."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"tildrakizumab":{"wirkmechanismus":"Unterbricht eine Entzündungskette, die bei Schuppenflechte die Hautveränderungen unterhält. Tildrakizumab ist ein humanisierter monoklonaler IgG1κ-Antikörper, der spezifisch an die p19-Untereinheit von Interleukin-23 bindet und dessen Bindung an den IL-23-Rezeptor verhindert. Dadurch werden die Aktivierung von Th17-Zellen und die Freisetzung entzündungsfördernder Botenstoffe wie IL-17 gehemmt. Nach der Einleitung genügt eine Injektion alle 12 Wochen.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege"],"haeufig":["Kopfschmerzen","Magen-Darm-Entzündung (Gastroenteritis)","Übelkeit, Durchfall","Schmerzen und Reaktionen an der Einstichstelle","Rückenschmerzen"],"unbekannt":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht)"]},"schwangerschaft":"Vorsichtshalber vermeiden. Frauen im gebärfähigen Alter sollen während und mindestens 17 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Nicht bekannt, ob Tildrakizumab in die Muttermilch übergeht; über Stillen oder Behandlung entscheidet die Ärztin oder der Arzt.","hinweise":["Nach zwei Startdosen (Woche 0 und 4) eine Injektion alle 12 Wochen.","Vor Beginn Tuberkulose-Test; bei Fieber oder anhaltenden Infektzeichen ärztlich abklären lassen.","Keine Lebendimpfungen während der Behandlung."],"darreichung":["Injektionslösung in der Fertigspritze (unter die Haut)"]},"tilidin-naloxon":{"wirkmechanismus":"Lindert starke Schmerzen über die körpereigenen Opioid-Andockstellen in Gehirn und Rückenmark. Tilidin ist eine Vorstufe (Prodrug), die in der Leber zum eigentlichen Wirkstoff Nortilidin umgewandelt wird; dieses wirkt als Agonist am μ-Opioidrezeptor. Naloxon ist ein Opioid-Antagonist, der beim Schlucken in üblicher Dosis in der Leber fast vollständig abgebaut wird und die Schmerzlinderung kaum beeinflusst. Bei Injektion oder sehr hohen Dosen blockiert Naloxon jedoch die Opioidwirkung und kann bei Opioidabhängigen einen Entzug auslösen.","nebenwirkungen":{"sehrHaeufig":["Übelkeit"],"haeufig":["Erbrechen","Schwindel, Benommenheit, Müdigkeit","Kopfschmerzen, Nervosität","Durchfall, Bauchschmerzen","Vermehrtes Schwitzen"],"unbekannt":["Atemdepression (abgeschwächte Atmung), v. a. bei hohen Dosen","Verstopfung","Verwirrtheit, Halluzinationen, Euphorie","Abhängigkeit und Entzugssymptome","Überempfindlichkeitsreaktionen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit. Längere Anwendung kann beim Neugeborenen Entzugssymptome, Anwendung unter der Geburt eine Atemdepression auslösen.","stillzeit":"Nicht stillen, da die Wirkstoffe in die Muttermilch übergehen können.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern.","Kein Alkohol; die Fahrtüchtigkeit ist vor allem zu Beginn und bei Dosisänderungen eingeschränkt.","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome)."],"darreichung":["Retardtabletten","Tropfen (Lösung zum Einnehmen)"]},"timolol":{"wirkmechanismus":"Senkt den Augeninnendruck, indem weniger Kammerwasser gebildet wird. Timolol ist ein nicht selektiver Betablocker ohne eigene sympathomimetische Aktivität; es blockiert Beta-1- und Beta-2-Rezeptoren im Ziliarkörper und drosselt so die Kammerwasserproduktion. Auch als Augentropfen gelangt ein Teil über die Nasen- und Rachenschleimhaut in den Kreislauf und kann Puls, Blutdruck und Bronchien beeinflussen. Abgebaut wird Timolol hauptsächlich über das Leberenzym CYP2D6.","nebenwirkungen":{"unbekannt":["Augenreizung (Brennen, Stechen, Rötung), trockenes Auge, verminderte Hornhautempfindlichkeit","Sehstörungen, Doppelbilder, hängendes Augenlid; Aderhautabhebung nach Glaukomoperation","Langsamer Puls (Bradykardie), Herzrhythmusstörungen, AV-Block, Herzinsuffizienz, Ohnmacht (Synkope), Herzstillstand","Tiefer Blutdruck, kalte Hände und Füsse, Raynaud-Syndrom","Bronchospasmus (v. a. bei Asthma), Atemnot","Müdigkeit, Schwindel, Kopfschmerzen, Depression, Schlafstörungen","Verdeckte Unterzuckerung, Verstärkung einer Myasthenia gravis","Allergische Reaktionen bis Anaphylaxie, Hautausschlag, Verschlechterung einer Psoriasis"]},"schwangerschaft":"Nur anwenden, wenn es ärztlich klar notwendig ist. Bei Anwendung bis zur Geburt das Neugeborene in den ersten Lebenstagen auf langsamen Puls, Unterzuckerung und Atemprobleme überwachen.","stillzeit":"Timolol geht in die Muttermilch über; bei Augentropfen in üblicher Dosierung sind Wirkungen beim Säugling unwahrscheinlich. Nur nach ärztlicher Abwägung.","hinweise":["Nach dem Eintropfen das Auge 1–2 Minuten schliessen und den inneren Augenwinkel sanft zudrücken – so gelangt weniger Wirkstoff ins Blut.","Bei Asthma, Herzkrankheiten oder vor einer Operation die Anwendung der Augentropfen ärztlich angeben.","Bei mehreren Augenmitteln mindestens 5–10 Minuten Abstand einhalten; Augengel zuletzt anwenden."],"darreichung":["Augentropfen","Augengel"]},"tioconazol":{"wirkmechanismus":"Bekämpft Pilze, indem es den Aufbau ihrer Zellmembran stört. Tioconazol hemmt das pilzeigene Enzym Lanosterol-14-alpha-Demethylase und damit die Bildung von Ergosterol; die Membran wird durchlässig, und der Pilz stirbt ab oder wächst nicht weiter. Es wirkt gegen Hefen (Candida), Fadenpilze und einige grampositive Bakterien. Bei vaginaler Anwendung gelangt nur wenig Wirkstoff ins Blut.","nebenwirkungen":{"unbekannt":["Brennen, Juckreiz oder Reizung an der Anwendungsstelle","Vaginaler Ausfluss, Unterleibsschmerzen, Schmerzen beim Wasserlassen","Allergische Reaktionen (Hautausschlag, Nesselsucht, Schwellung)"]},"schwangerschaft":"Es gelangt nur wenig Wirkstoff ins Blut; in der Schwangerschaft, besonders im ersten Drittel, nur nach ärztlicher Abwägung anwenden.","stillzeit":"Nach ärztlicher Abwägung möglich; Hautpräparate nicht im Brustbereich auftragen.","hinweise":["Während der Behandlung keine Tampons, Scheidenspülungen oder Spermizide verwenden.","Latexkondome und Diaphragmen bieten während und kurz nach der Behandlung keinen sicheren Schutz.","Bei fehlender Besserung nach einigen Tagen ärztlich abklären; ein Partner mit Beschwerden sollte mitbehandelt werden.","Hautcreme nicht in die Augen bringen; nach dem Auftragen Hände waschen."],"darreichung":["Vaginalovula","Creme"]},"tioguanin":{"wirkmechanismus":"Hemmt die Vermehrung rasch wachsender Zellen, insbesondere von Leukämiezellen. Tioguanin ist eine Vorstufe (Prodrug), die in der Zelle durch das Enzym HGPRT direkt zu Thioguanin-Nukleotiden umgewandelt wird. Diese werden als falsche Bausteine in DNA und RNA eingebaut und hemmen die Neubildung von Purinen, was zum Zelltod führt. Anders als Mercaptopurin wird Tioguanin kaum über die Xanthinoxidase abgebaut, sondern vor allem durch die Thiopurin-Methyltransferase (TPMT).","nebenwirkungen":{"sehrHaeufig":["Knochenmarkhemmung (Mangel an weissen und roten Blutkörperchen und an Blutplättchen)","Venookklusive Lebererkrankung (Verschluss kleiner Lebervenen) bei Dauertherapie"],"haeufig":["Mundschleimhautentzündung","Magen-Darm-Beschwerden wie Übelkeit, Erbrechen, Appetitlosigkeit","Erhöhte Leberwerte"],"selten":["Nekrotisierende Kolitis (schwere Darmentzündung mit Gewebeuntergang), Darmdurchbruch","Zentrilobuläre Lebernekrose (Absterben von Lebergewebe)"],"unbekannt":["Pfortaderhochdruck, Milzvergrösserung, Krampfadern der Speiseröhre","Noduläre regenerative Hyperplasie der Leber (knotiger Leberumbau)","Hyperurikämie (erhöhte Harnsäure)","Infektionen"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit anwenden, da Tioguanin das Ungeborene schädigen kann. Frauen und Männer müssen während der Behandlung und einige Monate danach zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Blutbild in der Regel wöchentlich und Leberwerte regelmässig kontrollieren; Gelbsucht, Zunahme des Bauchumfangs, Fieber oder Blutungen sofort melden.","Nicht für eine Dauerbehandlung geeignet (Gefahr schwerer Leberschäden).","Keine Lebendimpfungen ohne Rücksprache mit der Ärztin oder dem Arzt."],"darreichung":["Tabletten"]},"tiotropium":{"wirkmechanismus":"Hält die Bronchien den ganzen Tag weiter offen. Tiotropium blockiert die Muskarinrezeptoren (v. a. M3) der Bronchialmuskulatur und verhindert so, dass der Nervenbotenstoff Acetylcholin die Bronchien verengt. Weil es sich nur sehr langsam vom M3-Rezeptor löst, hält die Wirkung über 24 Stunden an. Als quaternäre Ammoniumverbindung wird es kaum aus dem Darm aufgenommen und wirkt vor allem in der Lunge.","nebenwirkungen":{"haeufig":["Mundtrockenheit (meist leicht)"],"gelegentlich":["Schwindel, Kopfschmerzen, Geschmacksstörungen","Verschwommensehen","Vorhofflimmern","Rachenentzündung, Heiserkeit (Dysphonie), Husten","Sodbrennen (Reflux), Verstopfung, Mundsoor","Hautausschlag","Harnverhalt, Schmerzen beim Wasserlösen"],"selten":["Schlaflosigkeit","Glaukom, erhöhter Augeninnendruck","Herzrasen (Tachykardie), Herzklopfen, supraventrikuläre Tachykardie","Bronchospasmus, Nasenbluten, Kehlkopf- und Nasennebenhöhlenentzündung","Darmverschluss einschliesslich Darmlähmung (paralytischer Ileus), Schluckbeschwerden, Übelkeit, Zahnfleisch- und Mundschleimhautentzündung","Überempfindlichkeitsreaktionen: Nesselsucht, Juckreiz, Angioödem","Harnwegsinfekte"],"unbekannt":["Anaphylaxie (schwere allergische Reaktion)","Dehydratation (Flüssigkeitsmangel)","Zahnkaries","Trockene Haut, Hautinfektionen und Hautgeschwüre","Gelenkschwellung"]},"schwangerschaft":"Sehr begrenzte Erfahrungen; vorsichtshalber nicht anwenden, ausser der Nutzen überwiegt klar.","stillzeit":"Nicht bekannt, ob Tiotropium beim Menschen in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich zur gleichen Zeit inhalieren; nicht zur Behandlung akuter Atemnot.","HandiHaler-Kapseln nur inhalieren, nie schlucken.","Pulver und Sprühnebel nicht in die Augen bringen; bei Augenschmerzen, verschwommenem Sehen, Farbringen um Lichter oder geröteten Augen sofort ärztliche Hilfe holen (Glaukomanfall).","Gute Mundhygiene und regelmässige Zahnkontrollen, da Mundtrockenheit Karies fördern kann."],"darreichung":["Kapseln mit Pulver zur Inhalation (HandiHaler)","Lösung zur Inhalation (Respimat-Inhalator)"]},"tiotropium-olodaterol":{"wirkmechanismus":"Hält die Bronchien bei COPD rund um die Uhr weiter offen. Tiotropium blockiert langanhaltend die Muskarinrezeptoren (v. a. M3) der Bronchialmuskulatur und hemmt die verengende Wirkung von Acetylcholin. Olodaterol stimuliert als langwirksames Beta-2-Sympathomimetikum die Beta-2-Rezeptoren und entspannt die Bronchialmuskulatur. Beide Wirkungen halten 24 Stunden an.","nebenwirkungen":{"gelegentlich":["Schwindel, Kopfschmerzen","Herzrasen (Tachykardie)","Husten, Heiserkeit (Dysphonie)","Mundtrockenheit"],"selten":["Vorhofflimmern, Herzklopfen, supraventrikuläre Tachykardie","Bluthochdruck","Schlaflosigkeit, verschwommenes Sehen","Kehlkopf- und Rachenentzündung, Nasenbluten, Bronchospasmus","Verstopfung, Übelkeit, Mundsoor, Zahnfleisch- und Mundschleimhautentzündung","Überempfindlichkeitsreaktionen: Ausschlag, Juckreiz, Nesselsucht, Angioödem","Harnverhalt, Harnwegsinfekte, Schmerzen beim Wasserlösen","Rücken- und Gelenkschmerzen"],"unbekannt":["Glaukom, erhöhter Augeninnendruck","Darmverschluss einschliesslich Darmlähmung (paralytischer Ileus), Schluckbeschwerden, Reflux","Dehydratation (Flüssigkeitsmangel)","Zahnkaries","Nasennebenhöhlenentzündung"]},"schwangerschaft":"Sehr begrenzte Erfahrungen; vorsichtshalber nicht anwenden, ausser der Nutzen überwiegt klar. Olodaterol kann die Wehentätigkeit hemmen.","stillzeit":"Nicht bekannt, ob die Wirkstoffe beim Menschen in die Muttermilch übergehen (im Tierversuch ja); Anwendung nur nach ärztlicher Abwägung.","hinweise":["Einmal täglich zur gleichen Zeit inhalieren; nicht zur Behandlung akuter Atemnot.","Den Respimat vor dem ersten Gebrauch richtig vorbereiten (Patrone einsetzen, Testhübe) und den Sprühnebel nicht in die Augen bringen.","Bei Augenschmerzen, verschwommenem Sehen, Farbringen um Lichter oder geröteten Augen sofort ärztliche Hilfe holen (Glaukomanfall)."],"darreichung":["Lösung zur Inhalation (Respimat-Inhalator)"]},"tirbanibulin":{"wirkmechanismus":"Bringt sich rasch teilende, krankhaft veränderte Hautzellen zum Absterben. Tirbanibulin bindet an Tubulin und hemmt so den Aufbau der Mikrotubuli, die für die Zellteilung nötig sind. Die Zellen bleiben in der Teilung stecken und gehen durch programmierten Zelltod (Apoptose) zugrunde. Bei Anwendung auf der Haut gelangt nur sehr wenig Wirkstoff ins Blut.","nebenwirkungen":{"sehrHaeufig":["Rötung (Erythem) an der Anwendungsstelle","Schuppung","Krustenbildung","Schwellung","Erosionen oder Geschwüre an der Anwendungsstelle"],"haeufig":["Schmerzen an der Anwendungsstelle","Juckreiz an der Anwendungsstelle","Bläschen oder Pusteln an der Anwendungsstelle"]},"schwangerschaft":"Keine Erfahrungen; in Tierversuchen nach Einnahme schädlich für das Ungeborene. In der Schwangerschaft nicht empfohlen.","stillzeit":"Nicht bekannt, ob Tirbanibulin in die Muttermilch übergeht; ein Risiko für den Säugling kann nicht ausgeschlossen werden. In der Stillzeit nicht empfohlen.","hinweise":["Einmal täglich an 5 aufeinanderfolgenden Tagen dünn auf die Behandlungsfläche auftragen, nicht abdecken und danach sofort die Hände waschen.","Die behandelte Stelle etwa 8 Stunden lang nicht waschen und nicht berühren.","Behandelte Haut vor Sonne und UV-Licht (auch Solarium) schützen.","Rötung, Schuppung und Krusten sind zu erwarten und klingen meist innerhalb weniger Wochen ab."],"darreichung":["Salbe (Einzeldosis-Beutel)"]},"tirofiban":{"wirkmechanismus":"Verhindert, dass Blutplättchen miteinander verkleben und ein Gerinnsel bilden. Tirofiban ist ein nicht-peptidischer, reversibler Hemmstoff des Glykoprotein-IIb/IIIa-Rezeptors, über den Fibrinogen die Blutplättchen vernetzt. Dadurch wird der gemeinsame Endweg der Plättchenaggregation blockiert. Nach Ende der Infusion erholt sich die Plättchenfunktion innerhalb weniger Stunden; ausgeschieden wird es vor allem über die Niere.","nebenwirkungen":{"sehrHaeufig":["Blutungen, v. a. an der Punktionsstelle und nach Eingriffen"],"haeufig":["Übelkeit","Kopfschmerzen","Fieber","Blutergüsse (Hämatome)","Blutungen aus Zahnfleisch, Magen-Darm-Trakt oder Harnwegen","Abfall von Hämoglobin und Blutplättchen (Laborbefund)"],"unbekannt":["Hirnblutung, Blutung im Wirbelkanal","Blutung in den Bauchraum (retroperitoneal) oder in die Lunge","Blutung in den Herzbeutel (Hämoperikard)","Akuter schwerer Abfall der Blutplättchen","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur anwenden, wenn klar notwendig.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird nur im Spital als Infusion gegeben, in der Regel zusammen mit ASS und Heparin.","Thrombozyten, Hämoglobin und Gerinnungswerte werden vor und während der Behandlung kontrolliert.","Blutungen, schwarzen Stuhl, Blut im Urin oder plötzliche starke Kopfschmerzen sofort melden."],"darreichung":["Infusionslösung","Konzentrat zur Herstellung einer Infusionslösung"]},"tirzepatid":{"wirkmechanismus":"Senkt Blutzucker und Körpergewicht, indem es die Wirkung zweier körpereigener Darmhormone nachahmt. Tirzepatid ist ein einmal wöchentlich gespritzter Agonist an den Rezeptoren für GIP (glukoseabhängiges insulinotropes Polypeptid) und GLP-1 (Glucagon-like Peptide-1). Es steigert blutzuckerabhängig die Insulinausschüttung, senkt den Glukagonspiegel, verzögert die Magenentleerung und vermindert über Signale im Gehirn Hunger und Nahrungsaufnahme. Weil die Insulinfreisetzung vom Blutzucker abhängt, ist das Unterzuckerungsrisiko ohne Insulin oder Sulfonylharnstoffe gering.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Durchfall","Erbrechen und Verstopfung (bei Behandlung des Übergewichts sehr häufig, bei Typ-2-Diabetes häufig)","Hypoglykämie (Unterzuckerung) bei Kombination mit Insulin oder Sulfonylharnstoffen"],"haeufig":["Verminderter Appetit","Bauchschmerzen, Verdauungsbeschwerden (Dyspepsie), Blähungen, Aufstossen, Sodbrennen (Reflux)","Müdigkeit (Fatigue), Schwindel","Reaktionen an der Einstichstelle (Rötung, Juckreiz)","Haarausfall (vor allem bei Gewichtsbehandlung)","Erhöhter Puls, tiefer Blutdruck","Anstieg der Bauchspeicheldrüsen-Enzyme (Lipase, Amylase) im Blut","Überempfindlichkeitsreaktionen"],"gelegentlich":["Gallensteine (Cholelithiasis), Gallenblasenentzündung (Cholezystitis)","Akute Pankreatitis (Bauchspeicheldrüsenentzündung)","Geschmacksstörung","Anstieg des Calcitonins im Blut"],"unbekannt":["Anaphylaxie und Angioödem (schwere allergische Reaktionen)","Aspiration von Mageninhalt bei Narkose oder tiefer Sedierung"]},"schwangerschaft":"Nicht anwenden. Frauen im gebärfähigen Alter sollen sicher verhüten (Pille: siehe Wechselwirkungen); bei Kinderwunsch oder Eintritt einer Schwangerschaft ärztlich begleitet absetzen.","stillzeit":"Nicht empfohlen, da unbekannt ist, ob Tirzepatid in die Muttermilch übergeht; Entscheid nach ärztlicher Abwägung.","hinweise":["Einmal wöchentlich am gleichen Wochentag unter die Haut von Bauch, Oberschenkel oder Oberarm spritzen, unabhängig von den Mahlzeiten; Einstichstelle wechseln.","Eine vergessene Dosis innerhalb von 4 Tagen nachholen, sonst auslassen und zum gewohnten Termin weiterfahren.","Kleinere Mahlzeiten, langsames Essen und ausreichendes Trinken mildern Magen-Darm-Beschwerden; bei anhaltenden starken Bauchschmerzen sofort ärztlich abklären (Pankreatitis).","Vor Operationen, Narkosen und Magen-Darm-Spiegelungen die Behandlung angeben."],"darreichung":["Injektionslösung im Fertigpen (zur Injektion unter die Haut)"]},"tislelizumab":{"wirkmechanismus":"Löst eine Bremse des Immunsystems, damit Abwehrzellen Krebszellen wieder bekämpfen. Tislelizumab ist ein humanisierter IgG4-Antikörper, der an den Rezeptor PD-1 auf T-Zellen bindet und dessen Aktivierung durch die Liganden PD-L1 und PD-L2 blockiert. Sein Fc-Teil ist so verändert, dass er kaum an Fc-gamma-Rezeptoren von Fresszellen bindet – damit sollen die aktivierten T-Zellen nicht selbst abgebaut werden.","nebenwirkungen":{"sehrHaeufig":["Anämie (Blutarmut)","Müdigkeit","Erhöhte Leberwerte (AST, ALT) und erhöhtes Bilirubin","Husten","Hautausschlag"],"haeufig":["Hypothyreose, Hyperthyreose (Schilddrüsenunter- und -überfunktion)","Pneumonitis (nicht-infektiöse Lungenentzündung)","Hyperglykämie (erhöhter Blutzucker), Hyponatriämie, Hypokaliämie","Durchfall, Übelkeit","Juckreiz","Gelenk- und Muskelschmerzen","Fieber, Infusionsreaktionen","Neutropenie, Thrombozytopenie"],"gelegentlich":["Nebenniereninsuffizienz, Thyreoiditis","Typ-1-Diabetes","Kolitis (Dickdarmentzündung)","Hepatitis (Leberentzündung)","Nephritis (Nierenentzündung)","Myokarditis, Myositis, Arthritis"],"unbekannt":["Hypophysitis (Entzündung der Hirnanhangsdrüse)","Myasthenia gravis, Guillain-Barré-Syndrom","Schwere Hautreaktionen (Stevens-Johnson-Syndrom)","Abstossung transplantierter Organe"]},"schwangerschaft":"Nicht empfohlen: IgG-Antikörper gehen über die Plazenta, und die PD-1-Blockade kann die Toleranz gegenüber dem Ungeborenen stören. Frauen im gebärfähigen Alter verhüten während der Behandlung und mindestens 4 Monate danach.","stillzeit":"Während der Behandlung und mindestens 4 Monate nach der letzten Dosis nicht stillen.","hinweise":["Neue Beschwerden wie Durchfall, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Kopfschmerzen oder Hautausschlag sofort melden – auch Monate nach Therapieende.","Den Patientenausweis immer bei sich tragen und allen Ärztinnen und Ärzten zeigen.","Leber-, Nieren- und Schilddrüsenwerte sowie Blutzucker werden regelmässig kontrolliert.","Kortison nicht eigenmächtig beginnen oder absetzen."],"darreichung":["Infusionskonzentrat"]},"tizanidin":{"wirkmechanismus":"Entspannt verkrampfte Muskeln, indem es überaktive Nervenreflexe im Rückenmark dämpft. Tizanidin stimuliert zentrale Alpha-2-Adrenozeptoren und vermindert so die Freisetzung erregender Aminosäuren aus Zwischennervenzellen des Rückenmarks; dadurch werden polysynaptische Reflexe gehemmt. Als Alpha-2-Agonist senkt es zudem Blutdruck und Puls und wirkt beruhigend. Es wird fast vollständig über CYP1A2 in der Leber abgebaut.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Müdigkeit (v. a. bei höheren Dosen gegen Spastik)","Schwindel","Mundtrockenheit"],"haeufig":["Blutdruckabfall","Übelkeit, Magen-Darm-Beschwerden","Muskelschwäche","Erhöhte Leberwerte (Transaminasen)"],"gelegentlich":["Langsamer Puls (Bradykardie)"],"selten":["Halluzinationen","Schlaflosigkeit, Schlafstörungen"],"sehrSelten":["Hepatitis, Leberversagen"],"unbekannt":["Entzugserscheinungen nach abruptem Absetzen: Blutdruckanstieg, Herzrasen (Rebound)","Verwirrtheit","Verschwommenes Sehen","Hautausschlag, Juckreiz","Ohnmacht"]},"schwangerschaft":"Nicht empfohlen; nur wenn unbedingt nötig, nach ärztlicher Abwägung.","stillzeit":"Nicht anwenden, da Tizanidin in die Muttermilch übergehen kann.","hinweise":["Nicht abrupt absetzen, sondern langsam ausschleichen – sonst Blutdruckanstieg und Herzrasen möglich.","Alkohol meiden; Schläfrigkeit, Schwindel und Blutdruckabfall beeinträchtigen die Fahrtüchtigkeit – langsam aufstehen.","Bei höheren Dosen in den ersten Monaten Leberwerte kontrollieren.","Neu verordnete Medikamente, vor allem Antibiotika und Antidepressiva, immer auf Wechselwirkungen prüfen lassen."],"darreichung":["Tabletten"]},"tobramycin":{"wirkmechanismus":"Tötet Bakterien ab, indem es ihre Eiweissherstellung stört. Tobramycin bindet an die 30S-Untereinheit der bakteriellen Ribosomen und führt zu Ablesefehlern; die entstehenden fehlerhaften Eiweisse schädigen die Bakterienmembran. Die Wirkung ist konzentrationsabhängig und hält nach (postantibiotischer Effekt); besonders wirksam ist es gegen gramnegative Erreger einschliesslich Pseudomonas aeruginosa. Aus dem Darm wird es nicht aufgenommen; beim Inhalieren entstehen hohe Spiegel im Bronchialschleim bei geringer Aufnahme ins Blut.","nebenwirkungen":{"sehrHaeufig":["Bei Inhalationspulver: Husten, Heiserkeit, Atemnot, Halsschmerzen, Fieber"],"haeufig":["Bei Inhalation: Tinnitus (Ohrensausen) und Hörminderung","Bei Inhalation: Bronchospasmus (Verkrampfung der Atemwege), pfeifende Atmung, Bluthusten","Geschmacksstörungen, Übelkeit, Erbrechen","Nasenbluten, Hautausschlag","Bei Augentropfen: Augenbeschwerden und Augenrötung"],"gelegentlich":["Bei Augentropfen: Lidschwellung und -rötung, Juckreiz, Tränenfluss, Hornhautentzündung, verschwommenes Sehen"],"selten":["Schwindel, Kopfschmerzen, Stimmverlust"],"sehrSelten":["Pilzinfektionen im Mund","Überempfindlichkeitsreaktionen, Nesselsucht"],"unbekannt":["Bei Infusion: Nierenschädigung (Anstieg von Kreatinin und Harnstoff)","Bei Infusion: bleibende Innenohrschäden mit Hörverlust und Gleichgewichtsstörungen","Neuromuskuläre Blockade bis zur Atemlähmung","Elektrolytstörungen (Magnesium-, Calcium- und Kaliummangel)","Blutbildveränderungen (Anämie, Leukopenie, Thrombozytopenie)","Anaphylaxie (schwere allergische Reaktion)","Clostridioides-difficile-Kolitis"]},"schwangerschaft":"Aminoglykoside gehen über die Plazenta und können beim Kind bleibende Innenohrschäden (Taubheit) verursachen: Infusion und Inhalation nur bei zwingender Indikation. Augentropfen und -salbe nach ärztlicher Abwägung vertretbar.","stillzeit":"Geht in geringen Mengen in die Muttermilch über und wird vom Säugling kaum aufgenommen. Nach ärztlicher Abwägung möglich; Kind auf Durchfall und Pilzbefall beobachten.","hinweise":["Inhalation: zuerst den bronchienerweiternden Spray und die Atemphysiotherapie, Tobramycin zuletzt; nicht mit anderen Mitteln im Vernebler mischen.","Hörminderung, Ohrensausen oder Schwindel sofort ärztlich melden.","Bei Infusion werden Blutspiegel, Nierenwerte und bei längerer Therapie das Gehör kontrolliert.","Augentropfen: während der Infektion keine Kontaktlinsen tragen."],"darreichung":["Lösung für einen Vernebler","Inhalationspulver in Hartkapseln","Augentropfen","Augensalbe","Injektions- und Infusionslösung"]},"tobramycin-dexamethason":{"wirkmechanismus":"Hemmt die Entzündung und bekämpft gleichzeitig Bakterien am Auge. Dexamethason ist ein stark wirksames Glukokortikoid, das die Bildung entzündungsfördernder Botenstoffe unterdrückt und Rötung, Schwellung und Schmerzen lindert. Tobramycin ist ein Aminoglykosid-Antibiotikum, das an die bakteriellen Ribosomen bindet und die Eiweisssynthese stört. Es wirkt bakterizid, besonders gegen Staphylokokken und gramnegative Keime wie Pseudomonas aeruginosa.","nebenwirkungen":{"gelegentlich":["Erhöhter Augeninnendruck","Augenschmerzen, Augenjucken, Augenreizung und Augenbeschwerden"],"selten":["Keratitis (Hornhautentzündung)","Allergische Reaktion am Auge","Verschwommenes Sehen, trockenes Auge, Augenrötung","Geschmacksstörung"],"unbekannt":["Überempfindlichkeitsreaktionen, Gesichtsschwellung, Erythema multiforme","Schwindel, Kopfschmerzen","Lidschwellung, Pupillenerweiterung, vermehrter Tränenfluss","Übelkeit, Bauchbeschwerden","Glaukom, Linsentrübung (Katarakt) und Hornhautverdünnung bei längerer Anwendung","Pilz- oder Virusinfektionen des Auges (Sekundärinfektion)"]},"schwangerschaft":"Keine ausreichenden Daten; Aminoglykoside können bei systemischer Gabe das Gehör des Ungeborenen schädigen. Nur bei klarer Notwendigkeit und kurzzeitig anwenden.","stillzeit":"Nicht bekannt, ob die Wirkstoffe nach Anwendung am Auge in die Muttermilch gelangen; nur nach ärztlicher Abwägung.","hinweise":["Augentropfen vor Gebrauch gut schütteln.","Nicht länger als ärztlich verordnet anwenden; bei längerer Anwendung den Augeninnendruck kontrollieren lassen.","Während der Behandlung keine Kontaktlinsen tragen."],"darreichung":["Augentropfen (Suspension)","Augensalbe"]},"tocilizumab":{"wirkmechanismus":"Dämpft Entzündungen, indem es die Wirkung des Botenstoffs Interleukin-6 blockiert. Tocilizumab ist ein humanisierter monoklonaler IgG1-Antikörper, der an lösliche und membrangebundene IL-6-Rezeptoren bindet und so die IL-6-Signalübertragung hemmt. Dadurch sinken Entzündung, Fieber und Akutphase-Eiweisse wie das CRP. Weil IL-6 die Leberenzyme des Arzneimittelabbaus (Cytochrom P450) unterdrückt, normalisiert sich deren Aktivität unter Tocilizumab wieder.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege","Erhöhtes Cholesterin"],"haeufig":["Zellulitis (Hautinfektion), Lungenentzündung, Herpes simplex und Gürtelrose","Neutropenie, Leukopenie","Erhöhte Leberwerte und Bilirubin","Kopfschmerzen, Schwindel","Bluthochdruck","Bauchschmerzen, Mundgeschwüre, Gastritis","Ausschlag, Juckreiz, Nesselsucht","Infusions- oder Injektionsreaktionen, periphere Ödeme, Gewichtszunahme"],"gelegentlich":["Divertikulitis","Magengeschwür, Stomatitis (Mundschleimhautentzündung)","Erhöhte Triglyceride","Nierensteine","Schilddrüsenunterfunktion"],"selten":["Stevens-Johnson-Syndrom","Medikamentenbedingte Leberschädigung, Hepatitis, Gelbsucht"],"sehrSelten":["Leberversagen"],"unbekannt":["Anaphylaxie (schwere, auch tödliche allergische Reaktion)","Magen-Darm-Durchbruch (Perforation), meist als Komplikation einer Divertikulitis"]},"schwangerschaft":"Nur bei klarer Notwendigkeit nach ärztlicher Abwägung; Frauen im gebärfähigen Alter verhüten während und bis 3 Monate nach der Behandlung.","stillzeit":"Übergang in die Muttermilch ist unbekannt; Entscheid über Stillen oder Therapie ärztlich abwägen.","hinweise":["Weil Fieber und CRP unterdrückt werden, bei jedem Krankheitsgefühl, Husten oder Bauchschmerzen früh ärztlich abklären lassen.","Leberwerte, Blutbild und Blutfette werden regelmässig kontrolliert.","Vor Beginn auf Tuberkulose testen und Impfungen auffrischen.","Fertigspritzen im Kühlschrank lagern, nicht einfrieren."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung","Injektionslösung (Fertigspritze, Fertigpen)"]},"tocopherol-vitamin-e":{"wirkmechanismus":"Schützt die Zellmembranen vor Schäden durch aggressive Sauerstoffverbindungen (freie Radikale). Alpha-Tocopherol ist das wichtigste fettlösliche Antioxidans des Körpers: Es fängt Radikale ab und verhindert so die Oxidation mehrfach ungesättigter Fettsäuren in Zellmembranen und Lipoproteinen. Ein Mangel tritt fast nur bei gestörter Fettaufnahme auf und kann Nerven- und Muskelschäden sowie eine Blutarmut durch Zerfall roter Blutkörperchen verursachen.","nebenwirkungen":{"unbekannt":["Magen-Darm-Beschwerden (Übelkeit, Durchfall, Bauchkrämpfe) bei hohen Dosen","Müdigkeit, Kopfschmerzen","Überempfindlichkeitsreaktionen der Haut","Erhöhte Blutungsneigung bei sehr hohen Dosen, besonders bei Vitamin-K-Mangel"]},"schwangerschaft":"Dosen im Bereich des Tagesbedarfs sind unbedenklich; höhere Dosen nur nach ärztlicher Abwägung.","stillzeit":"Vitamin E geht in die Muttermilch über; übliche Dosen sind unbedenklich, höhere nur nach ärztlicher Abwägung.","hinweise":["Zu einer Mahlzeit einnehmen – Vitamin E wird zusammen mit Fett besser aufgenommen.","Vor Operationen die Einnahme hoher Vitamin-E-Dosen angeben.","Hoch dosiertes Vitamin E ist nur bei einem nachgewiesenen Mangel sinnvoll."],"darreichung":["Kapseln"]},"tofacitinib":{"wirkmechanismus":"Dämpft Entzündungen, indem es die Signalweiterleitung vieler Entzündungsbotenstoffe in den Immunzellen unterbricht. Tofacitinib hemmt bevorzugt die Enzyme Januskinase 1 und 3 (JAK1/JAK3), die Signale von Zytokin-Rezeptoren über STAT-Eiweisse an den Zellkern weitergeben. Dadurch werden Aktivierung und Vermehrung von Lymphozyten sowie die Bildung entzündungsfördernder Botenstoffe gehemmt.","nebenwirkungen":{"haeufig":["Lungenentzündung, Grippe, Gürtelrose, Harnwegsinfekte, Nasennebenhöhlen- und Rachenentzündung, Bronchitis","Anämie (Blutarmut), Lymphopenie","Kopfschmerzen","Bluthochdruck","Husten","Bauchschmerzen, Erbrechen, Durchfall, Übelkeit, Gastritis","Hautausschlag, Akne","Gelenkschmerzen, Ödeme, Fieber, Müdigkeit, erhöhte Kreatinkinase"],"gelegentlich":["Tuberkulose, Divertikulitis, Nierenbeckenentzündung, Zellulitis","Nicht-melanozytärer Hautkrebs, Lungenkrebs","Leukopenie, Neutropenie","Erhöhte Blutfette, Fettleber, erhöhte Leberwerte","Herzinfarkt","Tiefe Venenthrombose, Lungenembolie","Schlaflosigkeit, Parästhesien (Kribbeln)","Sehnenentzündung, Gelenkschwellung"],"selten":["Sepsis","Opportunistische Infektionen (z. B. Pneumocystis-Pneumonie, Zytomegalie)","Lymphome"],"sehrSelten":["Tuberkulose des Nervensystems, Kryptokokken-Meningitis"],"unbekannt":["Überempfindlichkeitsreaktionen (Angioödem, Nesselsucht)","Magen-Darm-Durchbruch (Perforation)"]},"schwangerschaft":"Kontraindiziert. Frauen im gebärfähigen Alter verhüten während und bis mindestens 4 Wochen nach der letzten Dosis zuverlässig.","stillzeit":"Kontraindiziert; nicht stillen.","hinweise":["Vor Beginn auf Tuberkulose und Hepatitis testen und Impfungen (inkl. Gürtelrose) aktualisieren lassen.","Bei plötzlicher Atemnot, Brustschmerz oder geschwollenem, schmerzhaftem Bein sofort ärztliche Hilfe holen (Thrombose, Lungenembolie).","Blutbild, Leberwerte und Blutfette werden regelmässig kontrolliert; regelmässige Hautkontrollen.","Retardtabletten ganz schlucken, nicht teilen oder zerkauen."],"darreichung":["Filmtabletten","Retardtabletten"]},"tofersen":{"wirkmechanismus":"Senkt die Bildung eines fehlerhaften Eiweisses, das bei einer erblichen Form der ALS die motorischen Nervenzellen schädigt. Tofersen ist ein Antisense-Oligonukleotid, das an die Boten-RNA der Superoxiddismutase 1 (SOD1) bindet und über das Enzym RNase H deren Abbau auslöst. Dadurch sinkt die Menge an SOD1-Protein im Nervensystem; als Zeichen der Wirkung nehmen die Neurofilament-Leichtketten, ein Mass für den Nervenzellschaden, in Blut und Nervenwasser ab. Weil der Wirkstoff die Blut-Hirn-Schranke nicht überwindet, wird er mittels Lumbalpunktion in den Rückenmarkskanal gespritzt.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, auch Kopf- und Rückenschmerzen nach der Lumbalpunktion","Müdigkeit","Gelenkschmerzen","Muskelschmerzen","Erhöhte weisse Blutkörperchen und erhöhtes Eiweiss im Nervenwasser"],"haeufig":["Myelitis (Rückenmarksentzündung) und Radikulitis (Nervenwurzelentzündung)","Aseptische Meningitis (Hirnhautentzündung ohne Erreger)","Erhöhter Hirndruck, Papillenödem"]},"schwangerschaft":"Keine Erfahrungen; vorsichtshalber während der Schwangerschaft nicht anwenden.","stillzeit":"Nicht bekannt, ob Tofersen in die Muttermilch übergeht; Stillen nur nach ärztlicher Abwägung.","hinweise":["Wird im Spital per Lumbalpunktion verabreicht: drei Anfangsdosen im Abstand von 14 Tagen, danach alle 28 Tage.","Starke Kopfschmerzen, Sehstörungen, Fieber mit Nackensteife oder neue Schwäche bzw. Taubheit in den Beinen sofort melden."],"darreichung":["Injektionslösung zur intrathekalen Anwendung (in den Rückenmarkskanal)"]},"tolcapon":{"wirkmechanismus":"Verlängert und verstärkt die Wirkung von Levodopa. Tolcapon hemmt reversibel das Enzym Catechol-O-Methyltransferase (COMT), das Levodopa im Körper und im Gehirn abbaut. Dadurch gelangt mehr Levodopa ins Gehirn und bleibt länger wirksam, was Off-Phasen verkürzt. Allein eingenommen wirkt Tolcapon nicht gegen Parkinson.","nebenwirkungen":{"sehrHaeufig":["Dyskinesien (Überbewegungen), Dystonie","Übelkeit, Appetitlosigkeit, Durchfall","Schlafstörungen, übermässiges Träumen","Schläfrigkeit, Schwindel","Verwirrtheit, Halluzinationen","Beschwerden beim Aufstehen (orthostatische Hypotonie)"],"haeufig":["Kopfschmerzen, Brustschmerzen","Erbrechen, Verstopfung, Bauchschmerzen, Mundtrockenheit","Vermehrtes Schwitzen","Gelbfärbung des Urins (harmlos)","Grippeähnliche Beschwerden, Infekte der oberen Atemwege","Ohnmacht (Synkope), Stürze"],"gelegentlich":["Leberschädigung, in seltenen Fällen mit tödlichem Leberversagen"],"selten":["Malignes neuroleptisches Syndrom (bei Absetzen oder Dosisreduktion)"],"unbekannt":["Impulskontrollstörungen (z. B. Spielsucht, Kaufsucht)"]},"schwangerschaft":"Keine ausreichenden Erfahrungen; nur nach strenger ärztlicher Abwägung.","stillzeit":"Tolcapon ging im Tierversuch in die Milch über; nicht stillen.","hinweise":["Leberwerte nach festem Schema kontrollieren; bei Übelkeit, Müdigkeit, Appetitlosigkeit, Gelbsucht, dunklem Urin oder Juckreiz sofort ärztlich abklären.","Die Gelbfärbung des Urins ist harmlos.","Nicht abrupt absetzen."],"darreichung":["Filmtabletten"]},"tollwut-immunglobulin":{"wirkmechanismus":"Verleiht sofortigen Schutz gegen Tollwutviren, bis die gleichzeitig begonnene Impfung eigene Antikörper bildet. Das Präparat enthält menschliche Immunglobuline aus dem Plasma geimpfter Spender mit hohem Gehalt an Antikörpern gegen das Tollwutvirus. Möglichst viel davon wird direkt in und um die Wunde gespritzt, damit die Viren schon an der Eintrittsstelle neutralisiert werden, bevor sie die Nerven erreichen.","nebenwirkungen":{"unbekannt":["Schmerzen, Druckempfindlichkeit und Schwellung an der Einstichstelle","Fieber, Schüttelfrost","Hautreaktionen","Übelkeit, Erbrechen","Kreislaufreaktionen (Blutdruckabfall, Herzrasen)","Allergische Reaktionen bis zum anaphylaktischen Schock"]},"schwangerschaft":"Kann und soll bei entsprechender Exposition angewendet werden: Tollwut verläuft tödlich, und Immunglobuline haben keine bekannten schädlichen Wirkungen auf das Kind.","stillzeit":"Kann angewendet werden.","hinweise":["Wunde sofort gründlich mit Wasser und Seife auswaschen und rasch ärztliche Hilfe suchen.","Immunglobulin möglichst am Tag der ersten Impfung geben; später als 7 Tage nach der ersten Impfdosis wird es nicht mehr verabreicht.","Alle Termine des Tollwut-Impfschemas einhalten.","Lebendimpfungen erst 3 Monate später."],"darreichung":["Injektionslösung (in die Wunde und intramuskulär)"]},"tollwut-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen das Tollwutvirus zu bilden. Der Impfstoff enthält abgetötete Tollwutviren (Stamm Flury LEP), die auf Hühnerfibroblasten-Zellkulturen gezüchtet werden. Er führt zur Bildung neutralisierender Antikörper, die das Virus abfangen, bevor es über die Nerven das Gehirn erreicht. Nach einem Kontakt ist eine rasche, vollständige Impfserie lebensrettend, da Tollwut nach Ausbruch fast immer tödlich verläuft.","nebenwirkungen":{"sehrHaeufig":["Reaktionen an der Einstichstelle (Schmerzen, Verhärtung, Schwellung)","Kopfschmerzen","Unwohlsein, Müdigkeit, Schwäche"],"haeufig":["Fieber","Schwindel","Lymphknotenschwellung","Übelkeit, Erbrechen, Durchfall, Bauchschmerzen","Hautausschlag, Nesselsucht","Muskel- und Gelenkschmerzen","Appetitlosigkeit"],"selten":["Allergische Reaktionen","Kribbeln (Parästhesien)","Schüttelfrost","Schwitzen"],"sehrSelten":["Anaphylaxie (schwere allergische Reaktion)","Angioödem (Schwellung von Gesicht oder Rachen)","Enzephalitis (Hirnentzündung) und Guillain-Barré-Syndrom (Nervenlähmung)","Ohnmacht (Synkope)"]},"schwangerschaft":"Nach einem möglichen Tollwutkontakt immer impfen, da Tollwut tödlich ist. Vorbeugend nur bei deutlich erhöhtem Risiko nach ärztlicher Abwägung; schädliche Wirkungen sind nicht bekannt.","stillzeit":"Anwendung möglich; ein Risiko für den gestillten Säugling ist nicht bekannt.","hinweise":["Nach Biss, Kratzer oder Lecken an verletzter Haut durch ein verdächtiges Tier (im Ausland v. a. Hunde, Katzen, Affen; überall Fledermäuse) die Wunde sofort 15 Minuten mit Seife und Wasser waschen und umgehend ärztliche Hilfe holen – auch Vorgeimpfte brauchen Auffrischdosen.","Das vorgegebene Impfschema genau einhalten und keine Dosis auslassen.","Injektion in den Oberarm (bei Kleinkindern in den Oberschenkel), nicht ins Gesäss, da die Wirkung dort schwächer ist."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Injektionslösung"]},"tolterodin":{"wirkmechanismus":"Beruhigt die überaktive Blase, sodass sie mehr Urin speichern kann und der Harndrang nachlässt. Tolterodin ist ein kompetitiver Muskarinrezeptor-Antagonist, der im Körper stärker an der Blase als an den Speicheldrüsen wirkt. Es wird über CYP2D6 zum gleich stark wirksamen 5-Hydroxymethyl-Metaboliten (5-HMT) umgewandelt; bei Menschen mit wenig CYP2D6-Aktivität (langsame Metabolisierer) erfolgt der Abbau über CYP3A4, und der Tolterodin-Spiegel ist höher.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Kopfschmerzen"],"haeufig":["Bronchitis","Schwindel, Schläfrigkeit, Kribbeln (Parästhesien)","Trockene Augen, Sehstörungen (Akkommodationsstörungen)","Drehschwindel","Herzklopfen","Verdauungsbeschwerden, Verstopfung, Bauchschmerzen, Blähungen, Erbrechen, Durchfall","Schmerzen beim Wasserlassen, Harnverhalt","Müdigkeit, Brustschmerzen, Wassereinlagerungen in den Beinen, Gewichtszunahme"],"gelegentlich":["Überempfindlichkeitsreaktionen","Nervosität","Gedächtnisstörungen","Herzrasen, Herzrhythmusstörungen, Herzinsuffizienz","Reflux (saures Aufstossen)"],"unbekannt":["Anaphylaktoide Reaktionen, Angioödem","Verwirrtheit, Halluzinationen, Desorientierung","Verschlechterung von Demenzsymptomen","Gesichtsrötung (Flush)","Trockene Haut"]},"schwangerschaft":"Nicht empfohlen – es liegen keine ausreichenden Daten vor; im Tierversuch zeigte sich Reproduktionstoxizität.","stillzeit":"Vermeiden – es ist nicht bekannt, ob Tolterodin in die Muttermilch übergeht.","hinweise":["Retardkapseln ganz schlucken, nicht zerkauen; Einnahme unabhängig von den Mahlzeiten.","Kann Sehstörungen, Schwindel und Müdigkeit verursachen: Vorsicht beim Autofahren.","Wirkung nach 2–3 Monaten ärztlich überprüfen lassen."],"darreichung":["Filmtabletten","Retardkapseln"]},"tolvaptan":{"wirkmechanismus":"Lässt die Niere mehr Wasser ohne Salz ausscheiden. Tolvaptan blockiert selektiv den Vasopressin-V2-Rezeptor im Sammelrohr der Niere; dadurch werden weniger Wasserkanäle (Aquaporin-2) eingebaut und mehr freies Wasser ausgeschieden (Aquarese), während die Ausscheidung von Natrium und Kalium kaum zunimmt. So steigt der Natriumspiegel im Blut. Bei Zystennieren senkt die Blockade den zellulären cAMP-Spiegel, der das Wachstum der Zysten antreibt.","nebenwirkungen":{"sehrHaeufig":["Starker Durst","Vermehrtes und nächtliches Wasserlassen (Polyurie, Nykturie)","Mundtrockenheit","Übelkeit (bei Hyponatriämie-Behandlung)","Kopfschmerzen, Schwindel, Müdigkeit und Durchfall (bei Zystennieren-Behandlung)"],"haeufig":["Erhöhte Leberwerte","Hypernatriämie (zu hohes Natrium) und Flüssigkeitsmangel","Hyperkaliämie (erhöhtes Kalium)","Hyperglykämie (erhöhter Blutzucker), Appetitlosigkeit","Orthostatische Hypotonie (Blutdruckabfall beim Aufstehen), Herzklopfen","Verstopfung, Bauchschmerzen, Verdauungsbeschwerden","Hautausschlag, Juckreiz","Gewichtsabnahme, Schlaflosigkeit"],"gelegentlich":["Geschmacksstörungen","Anstieg des Bilirubins","Nierenfunktionsstörung (Kreatininanstieg)"],"unbekannt":["Akutes Leberversagen","Anaphylaxie (schwere allergische Reaktion)","Osmotisches Demyelinisierungssyndrom (Nervenschädigung) bei zu rascher Natriumkorrektur"]},"schwangerschaft":"Kontraindiziert; im Tierversuch fruchtschädigend. Frauen im gebärfähigen Alter müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert; während der Behandlung nicht stillen.","hinweise":["Die Behandlung einer Hyponatriämie wird im Spital begonnen; der Natriumspiegel wird in den ersten Tagen engmaschig kontrolliert.","Bei Jinarc vor Beginn und während der Behandlung regelmässig (anfangs monatlich) die Leberwerte kontrollieren; bei Müdigkeit, Appetitlosigkeit, Oberbauchschmerzen, dunklem Urin oder Gelbsucht sofort ärztlich melden.","Immer Wasser griffbereit haben und bei Durst trinken; keinen Grapefruitsaft trinken."],"darreichung":["Tabletten"]},"topiramat":{"wirkmechanismus":"Dämpft überaktive Nervenzellen auf mehreren Wegen und verhindert so Krampfanfälle und Migräneattacken. Topiramat blockiert spannungsabhängige Natriumkanäle, verstärkt die hemmende Wirkung von GABA am GABA-A-Rezeptor und hemmt erregende Glutamat-Rezeptoren vom AMPA/Kainat-Typ. Zusätzlich hemmt es schwach die Carboanhydrase, was Nierensteine und eine metabolische Azidose (Übersäuerung des Blutes) begünstigt.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit, Schwindel","Kribbeln (Parästhesien)","Depression","Müdigkeit","Übelkeit, Durchfall","Gewichtsabnahme","Nasen-Rachen-Entzündung"],"haeufig":["Appetitverlust, Anämie","Verlangsamtes Denken, Wortfindungs-, Konzentrations- und Gedächtnisstörungen","Schlaflosigkeit, Angst, Verwirrtheit, Aggression","Geschmacksstörungen, Zittern, Sehstörungen (verschwommen, Doppelbilder)","Erbrechen, Verstopfung, Bauchschmerzen, Mundtrockenheit","Nierensteine, häufiges oder schmerzhaftes Wasserlassen","Haarausfall, Ausschlag, Juckreiz","Gelenkschmerzen, Muskelkrämpfe"],"gelegentlich":["Metabolische Azidose (Übersäuerung des Blutes), Hypokaliämie","Vermindertes Schwitzen (Oligohidrose), Überwärmung","Suizidgedanken, Psychose, Halluzinationen","Leukopenie, Thrombozytopenie"],"selten":["Hepatitis, Leberversagen","Stevens-Johnson-Syndrom, Erythema multiforme","Renale tubuläre Azidose"],"unbekannt":["Akute Kurzsichtigkeit mit sekundärem Engwinkelglaukom","Makulopathie, Sehfeldausfälle","Toxische epidermale Nekrolyse"]},"schwangerschaft":"Fruchtschädigend: erhöhtes Risiko für Fehlbildungen (z. B. Lippen-Kiefer-Gaumen-Spalten), Untergewicht und Entwicklungsstörungen. Zur Migräneprophylaxe kontraindiziert; bei Epilepsie nur, wenn keine Alternative besteht – nie eigenmächtig absetzen.","stillzeit":"Geht in die Muttermilch über; Stillen nur nach ärztlicher Abwägung, Kind auf Durchfall, Schläfrigkeit und schlechte Gewichtszunahme beobachten.","hinweise":["Frauen im gebärfähigen Alter benötigen eine hochwirksame Verhütung und vor Behandlungsbeginn einen Schwangerschaftstest.","Reichlich trinken, um Nierensteinen und Überwärmung vorzubeugen.","Bei plötzlichen Augenschmerzen oder Sehverschlechterung sofort ärztliche Hilfe holen.","Nicht abrupt absetzen – Gefahr von Krampfanfällen; Alkohol meiden."],"darreichung":["Filmtabletten"]},"topotecan":{"wirkmechanismus":"Verhindert, dass Krebszellen ihre Erbsubstanz korrekt verdoppeln. Topotecan hemmt das Enzym Topoisomerase I, das bei der DNA-Verdopplung vorübergehende Einzelstrangbrüche setzt und wieder verschliesst. Topotecan stabilisiert den Komplex aus Enzym und gespaltener DNA; trifft die Replikationsgabel darauf, entstehen Doppelstrangbrüche, die zum Zelltod führen.","nebenwirkungen":{"sehrHaeufig":["Infektionen","Neutropenie, febrile Neutropenie, Thrombozytopenie, Anämie, Leukopenie","Appetitlosigkeit","Übelkeit, Erbrechen, Durchfall, Verstopfung, Bauchschmerzen","Mundschleimhautentzündung","Haarausfall","Fieber, Müdigkeit, Schwäche"],"haeufig":["Sepsis","Panzytopenie (Mangel an allen Blutzellen)","Überempfindlichkeitsreaktionen inkl. Hautausschlag","Erhöhtes Bilirubin","Juckreiz","Unwohlsein"],"selten":["Anaphylaxie, Angioödem, Nesselsucht","Interstitielle Lungenerkrankung"],"sehrSelten":["Austritt neben die Vene (Paravasat) mit Gewebereaktion"],"unbekannt":["Neutropenische Kolitis","Magen-Darm-Durchbruch (Perforation)"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; im Tierversuch fruchtschädigend. Frauen und Männer müssen während der Behandlung zuverlässig verhüten.","stillzeit":"Kontraindiziert.","hinweise":["Blutbild vor jeder Gabe; Fieber, Infektzeichen oder Blutungen sofort melden.","Neu auftretender Husten, Fieber oder Atemnot ärztlich abklären lassen.","Müdigkeit und Schwäche können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Pulver bzw. Konzentrat zur Herstellung einer Infusionslösung"]},"torasemid":{"wirkmechanismus":"Fördert die Ausscheidung von Salz und Wasser über die Niere. Torasemid hemmt den Natrium-Kalium-2-Chlorid-Cotransporter im aufsteigenden Teil der Henle-Schleife und steigert so die Ausscheidung von Natrium, Chlorid und Wasser; der Kaliumverlust ist im Vergleich zu Furosemid etwas geringer. Die Wirkung hält mit 6–8 Stunden länger an als bei Furosemid, und der Wirkstoff wird aus dem Darm nahezu vollständig aufgenommen. In niedriger Dosis senkt es den Blutdruck vor allem über eine Abnahme des Gefässwiderstands. Torasemid wird überwiegend in der Leber (hauptsächlich über CYP2C9) abgebaut.","nebenwirkungen":{"haeufig":["Störungen des Wasser- und Elektrolythaushalts, z. B. Hypokaliämie (Kaliummangel), besonders bei kaliumarmer Ernährung, Erbrechen, Durchfall oder Leberzirrhose","Metabolische Alkalose, Muskelkrämpfe","Erhöhte Harnsäure, Blutzucker und Blutfette","Kopfschmerzen, Schwindel, Müdigkeit, Schwächegefühl","Magen-Darm-Beschwerden wie Appetitlosigkeit, Bauchschmerzen, Übelkeit, Erbrechen, Durchfall oder Verstopfung","Anstieg einzelner Leberwerte (z. B. Gamma-GT)"],"gelegentlich":["Mundtrockenheit","Kribbeln oder Taubheitsgefühl in Armen und Beinen (Parästhesien)","Harnverhalt bei Abflussstörungen (z. B. Prostatavergrösserung)","Anstieg von Kreatinin und Harnstoff im Blut"],"sehrSelten":["Thrombozytopenie, Leukopenie, Abnahme der roten Blutkörperchen","Pankreatitis (Bauchspeicheldrüsenentzündung)","Allergische Hautreaktionen (Juckreiz, Ausschlag), Lichtempfindlichkeit, schwere Hautreaktionen","Sehstörungen","Tinnitus (Ohrgeräusche) und Hörverlust","Thromboembolien, Durchblutungsstörungen von Herz und Gehirn und Blutdruckabfall durch Bluteindickung","Verwirrtheit"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit und in der niedrigsten wirksamen Dosis: Diuretika können die Durchblutung der Plazenta vermindern und beim Kind Elektrolytstörungen verursachen.","stillzeit":"Kontraindiziert; ist eine Behandlung nötig, muss abgestillt werden.","hinweise":["Am Morgen unzerkaut mit etwas Flüssigkeit einnehmen.","Körpergewicht bei Ödemen täglich kontrollieren; bei Durchfall, Erbrechen oder starkem Schwitzen ärztlichen Rat einholen.","Kalium, Natrium, Nierenwerte, Blutzucker und Harnsäure regelmässig kontrollieren lassen.","Kann besonders zu Beginn die Fahrtüchtigkeit beeinträchtigen, verstärkt durch Alkohol."],"darreichung":["Tabletten"]},"tovorafenib":{"wirkmechanismus":"Hemmt ein Wachstumssignal, das bei vielen kindlichen Hirntumoren durch Veränderungen im BRAF-Gen dauerhaft eingeschaltet ist. Tovorafenib ist ein RAF-Kinasehemmer vom Typ II, der mutiertes BRAF (V600), BRAF-Fusionsproteine sowie normales BRAF und CRAF als Einzel- und Doppelmoleküle (Monomere und Dimere) hemmt. Dadurch wird der MAPK-Signalweg (RAF-MEK-ERK) blockiert. Der Wirkstoff gelangt ins Gehirn.","nebenwirkungen":{"sehrHaeufig":["Veränderung der Haarfarbe (Aufhellung)","Hautausschlag, akneähnliche Hautentzündung, trockene Haut, Juckreiz, Nagelbettentzündung","Blutungen, vor allem Nasenbluten","Blutarmut (Anämie)","Müdigkeit, Kopfschmerzen, Fieber","Erbrechen, Übelkeit, Verstopfung, Bauchschmerzen","Erhöhte CK- (Muskelenzym) und Leberwerte","Verlangsamtes Wachstum, Appetitlosigkeit"],"unbekannt":["Lichtempfindlichkeit (Photosensibilität)","Blutung im Tumor","Leberschädigung"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Mädchen und Frauen im gebärfähigen Alter müssen während und einige Wochen nach der Behandlung zuverlässig nichthormonal verhüten.","stillzeit":"Während der Behandlung und einige Wochen danach nicht stillen.","hinweise":["Einmal pro Woche am gleichen Wochentag einnehmen, unabhängig von den Mahlzeiten.","Sonne meiden, schützende Kleidung und Sonnenschutz verwenden.","Grösse und Gewicht sowie Leberwerte und CK regelmässig kontrollieren.","Ungewöhnliche Blutungen, starke Kopfschmerzen oder neue neurologische Beschwerden sofort melden."],"darreichung":["Tabletten","Pulver zur Herstellung einer Suspension zum Einnehmen"]},"trabectedin":{"wirkmechanismus":"Stört die Erbsubstanz und die Genregulation von Krebszellen. Trabectedin bindet in der kleinen Furche der DNA und verbiegt die Doppelhelix. Dadurch werden Transkriptionsfaktoren und DNA-Reparaturmechanismen beeinträchtigt, was den Zellzyklus stört und zum Zelltod führt. Zusätzlich beeinflusst es Zellen der Tumorumgebung, etwa tumorassoziierte Makrophagen.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Thrombozytopenie, Anämie, Leukopenie","Erhöhte Leberwerte (Transaminasen, alkalische Phosphatase) und Bilirubin","Übelkeit, Erbrechen, Verstopfung, Durchfall, Bauchschmerzen, Mundschleimhautentzündung","Appetitlosigkeit","Kopfschmerzen","Müdigkeit, Schwäche, Fieber, Ödeme"],"haeufig":["Infektionen, febrile Neutropenie","Flüssigkeitsmangel, Hypokaliämie (Kaliummangel)","Periphere Neuropathie, Geschmacksstörungen, Schwindel","Tiefer Blutdruck, Hitzegefühl","Atemnot, Husten","Muskel-, Gelenk- und Rückenschmerzen, erhöhte Kreatinkinase (Muskelenzym)","Reaktionen an der Infusionsstelle","Schlaflosigkeit, Gewichtsabnahme"],"unbekannt":["Rhabdomyolyse (Muskelzerfall)","Leberversagen","Kapillarlecksyndrom","Verminderte Pumpfunktion des Herzens, Herzinsuffizienz","Sepsis, septischer Schock","Gewebeuntergang bei Paravasat"]},"schwangerschaft":"Nicht anwenden; Trabectedin kann das Ungeborene schwer schädigen. Frauen und Männer müssen während der Behandlung und mehrere Monate danach zuverlässig verhüten.","stillzeit":"Kontraindiziert; auch nach Behandlungsende einige Monate nicht stillen.","hinweise":["Vor jeder Infusion wird Dexamethason gegeben (Leberschutz, gegen Übelkeit).","Leberwerte, Kreatinkinase und Blutbild werden regelmässig kontrolliert; Muskelschmerzen, dunkler Urin oder Gelbfärbung der Haut sofort melden.","Alkohol meiden.","Die Gabe erfolgt in der Regel über einen zentralen Venenkatheter."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"tralokinumab":{"wirkmechanismus":"Dämpft die allergische Entzündung der Haut und lindert dadurch Ekzeme und Juckreiz. Tralokinumab ist ein vollständig humaner IgG4-Antikörper, der spezifisch an das Zytokin Interleukin-13 (IL-13) bindet und dessen Andocken an die IL-13-Rezeptoren verhindert. IL-13 ist ein zentraler Botenstoff der sogenannten Typ-2-Entzündung bei Neurodermitis und schwächt unter anderem die Hautbarriere.","nebenwirkungen":{"sehrHaeufig":["Infektionen der oberen Atemwege (z. B. Erkältung)"],"haeufig":["Bindehautentzündung (Konjunktivitis), auch allergisch","Reaktionen an der Injektionsstelle (Rötung, Schwellung, Schmerzen)","Eosinophilie (Vermehrung bestimmter weisser Blutkörperchen)"],"gelegentlich":["Keratitis (Hornhautentzündung)"]},"schwangerschaft":"Nur begrenzte Erfahrungen; vorsichtshalber während der Schwangerschaft vermeiden.","stillzeit":"Nicht bekannt, ob Tralokinumab in die Muttermilch übergeht; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Im Kühlschrank lagern; vor der Injektion etwa 30 Minuten auf Raumtemperatur kommen lassen.","Neu auftretende Augenrötung, Augenschmerzen oder Sehstörungen ärztlich abklären lassen.","Kortison- oder Calcineurinhemmer-Cremes können nach ärztlicher Anweisung weiter verwendet werden."],"darreichung":["Injektionslösung (Fertigspritze)","Injektionslösung (Fertigpen)"]},"tramadol":{"wirkmechanismus":"Lindert Schmerzen auf zwei Wegen: über die körpereigenen Opioid-Andockstellen und über eine Verstärkung der schmerzhemmenden Nervenbahnen. Tramadol wirkt schwach am μ-Opioidrezeptor, vor allem über sein Abbauprodukt O-Desmethyltramadol, das in der Leber durch CYP2D6 gebildet wird. Zusätzlich hemmt es die Wiederaufnahme von Noradrenalin und Serotonin im Rückenmark. Dadurch erklärt sich auch das Risiko für Serotonin-Syndrom und Krampfanfälle.","nebenwirkungen":{"sehrHaeufig":["Schwindel","Übelkeit"],"haeufig":["Kopfschmerzen, Schläfrigkeit","Erbrechen, Verstopfung, Mundtrockenheit","Starkes Schwitzen","Müdigkeit"],"gelegentlich":["Herzklopfen, Herzrasen, Kreislaufschwäche beim Aufstehen","Würgereiz, Magenbeschwerden, Durchfall","Juckreiz, Hautausschlag, Nesselsucht"],"selten":["Krampfanfälle","Halluzinationen, Verwirrtheit, Delir, Albträume","Abhängigkeit","Atemdepression, Atemnot","Allergische Reaktionen bis zur Anaphylaxie","Bradykardie (langsamer Puls), Blutdruckanstieg","Verschwommensehen, Pupillenveränderungen"],"sehrSelten":["Erhöhte Leberwerte"],"unbekannt":["Serotonin-Syndrom","Hypoglykämie (Unterzuckerung)","Hyponatriämie (Natriummangel)","Schluckauf"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung und nur kurzfristig; längere Anwendung kann beim Neugeborenen Entzugssymptome auslösen.","stillzeit":"Tramadol geht in die Muttermilch über. Nach einer einzelnen Dosis ist keine Stillpause nötig; bei wiederholter Einnahme wird vom Stillen abgeraten.","hinweise":["Retardtabletten ganz schlucken, nicht zerkauen oder zerkleinern.","Kein Alkohol; die Fahrtüchtigkeit kann vor allem zu Beginn eingeschränkt sein.","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome).","Bei Diabetes auf Zeichen einer Unterzuckerung achten."],"darreichung":["Kapseln","Retardtabletten","Tropfen (Lösung zum Einnehmen)","Zäpfchen","Injektionslösung"]},"tramadol-paracetamol":{"wirkmechanismus":"Kombiniert zwei unterschiedlich wirkende Schmerzmittel, die sich ergänzen. Tramadol wirkt schwach an μ-Opioidrezeptoren – vor allem über sein durch CYP2D6 gebildetes Abbauprodukt O-Desmethyltramadol – und hemmt zusätzlich die Wiederaufnahme von Noradrenalin und Serotonin, was die körpereigene Schmerzhemmung im Rückenmark verstärkt. Paracetamol hemmt vor allem im Zentralnervensystem die Bildung von Prostaglandinen. Die Kombination wirkt rascher als Tramadol allein und länger als Paracetamol allein.","nebenwirkungen":{"sehrHaeufig":["Übelkeit","Schwindel","Schläfrigkeit"],"haeufig":["Kopfschmerzen, Zittern","Verwirrtheit, Stimmungsschwankungen, Schlafstörungen","Erbrechen, Verstopfung, Durchfall","Mundtrockenheit, Bauchschmerzen, Verdauungsbeschwerden","Schwitzen, Juckreiz"],"gelegentlich":["Depression, Halluzinationen, Albträume","Muskelzuckungen, Kribbeln, Ohrgeräusche","Herzrhythmusstörungen, Herzrasen, Bluthochdruck","Atemnot","Erhöhte Leberwerte","Hautausschlag, Nesselsucht"],"selten":["Krampfanfälle","Abhängigkeit, Delir","Ohnmacht, Koordinationsstörungen","Verschwommensehen"],"sehrSelten":["Missbrauch"],"unbekannt":["Serotonin-Syndrom","Hypoglykämie (Unterzuckerung)","Hyponatriämie (Natriummangel)","Atemdepression","Schwere Hautreaktionen","Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Soll in der Schwangerschaft nicht angewendet werden. Tramadol passiert die Plazenta; längere Anwendung kann beim Neugeborenen Entzugssymptome auslösen.","stillzeit":"Nicht empfohlen; Tramadol geht in die Muttermilch über. Nach einer einzelnen Einnahme ist eine Stillpause in der Regel nicht nötig.","hinweise":["Höchstens 8 Filmtabletten pro Tag (entspricht 2,6 g Paracetamol); keine weiteren paracetamol- oder tramadolhaltigen Mittel gleichzeitig.","Kein Alkohol; die Fahrtüchtigkeit kann eingeschränkt sein.","Nach längerer Anwendung nicht abrupt absetzen (Entzugssymptome).","Bei Diabetes auf Zeichen einer Unterzuckerung achten."],"darreichung":["Filmtabletten"]},"tramazolin":{"wirkmechanismus":"Lässt die geschwollene Nasenschleimhaut abschwellen, sodass die Nasenatmung wieder frei wird. Tramazolin stimuliert Alpha-Adrenozeptoren an den Blutgefässen der Nasenschleimhaut und verengt diese. Die Wirkung setzt innert Minuten ein und hält mehrere Stunden an. Bei längerer Anwendung kann die Schleimhaut nach Abklingen der Wirkung erneut anschwellen (Rebound-Effekt).","nebenwirkungen":{"haeufig":["Brennen und Trockenheit der Nasenschleimhaut","Niesen"],"unbekannt":["Verstärkte Schwellung der Nasenschleimhaut nach Abklingen der Wirkung (reaktive Hyperämie)","Kopfschmerzen","Herzklopfen, beschleunigter Puls, Blutdruckanstieg","Schlaflosigkeit, Unruhe","Überempfindlichkeitsreaktionen","Dauerhaft geschwollene Nase bei Langzeitgebrauch (Rhinitis medicamentosa)"]},"schwangerschaft":"Nur nach ärztlicher Rücksprache, kurzzeitig und ohne Überschreiten der empfohlenen Dosis.","stillzeit":"Nur nach ärztlicher Rücksprache.","hinweise":["Ohne ärztliche Verordnung nicht länger als 5–7 Tage anwenden (Gefahr der Gewöhnung).","Das Spray aus hygienischen Gründen nur von einer Person benutzen lassen."],"darreichung":["Nasenspray"]},"trametinib":{"wirkmechanismus":"Bremst das Wachstum von Krebszellen, deren Wachstumssignal durch eine BRAF-Mutation dauerhaft eingeschaltet ist. Trametinib hemmt reversibel und allosterisch die Kinasen MEK1 und MEK2 im MAPK-Signalweg (RAS–RAF–MEK–ERK) und verhindert so die Aktivierung von ERK. Zusammen mit dem BRAF-Hemmer Dabrafenib wird derselbe Signalweg an zwei Stellen blockiert; das verstärkt die Wirkung und verzögert die Resistenzbildung.","nebenwirkungen":{"sehrHaeufig":["Fieber und Schüttelfrost (v. a. mit Dabrafenib)","Hautausschlag, akneartige Hautentzündung, trockene Haut","Durchfall, Übelkeit, Erbrechen","Müdigkeit, periphere Ödeme (Wassereinlagerungen)","Bluthochdruck","Blutungen (z. B. Nasenbluten)","Gelenkschmerzen, Kopfschmerzen, Husten","Erhöhte Leberwerte"],"haeufig":["Abnahme der Herzleistung (verminderte Auswurffraktion)","Verschwommenes Sehen","Neutropenie (Mangel an weissen Blutkörperchen)","Hautinfektionen (Zellulitis), Nagelbettentzündung","Dehydratation (Flüssigkeitsmangel)","Plattenepithelkarzinom der Haut (unter der Kombination)"],"gelegentlich":["Pneumonitis (Lungenentzündung ohne Infektion)","Seröse Netzhautablösung (Chorioretinopathie)","Netzhautvenenverschluss","Kolitis, Magen-Darm-Perforation (Durchbruch)","Rhabdomyolyse (Muskelzerfall)","Nierenversagen"],"unbekannt":["Venöse Thromboembolien (Thrombose, Lungenembolie)","Hämophagozytische Lymphohistiozytose (schwere Überreaktion des Immunsystems)","Schwere Hautreaktionen (z. B. Stevens-Johnson-Syndrom) unter der Kombination"]},"schwangerschaft":"Nicht anwenden, ausser wenn unbedingt nötig (im Tierversuch fruchtschädigend). Frauen müssen während und bis 16 Wochen nach der Behandlung zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Auf nüchternen Magen einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit.","Tabletten im Kühlschrank (2–8 °C) und in der Originalpackung aufbewahren.","Bei Fieber ab 38 °C, Sehstörungen, Atemnot, Blutungen oder starkem Durchfall sofort ärztlich melden.","Regelmässige Kontrollen: Herzfunktion (Ultraschall), Blutdruck, Haut, Augen und Leberwerte."],"darreichung":["Filmtabletten"]},"trandolapril":{"wirkmechanismus":"Senkt den Blutdruck, indem es die Bildung des gefässverengenden Hormons Angiotensin II hemmt. Trandolapril ist ein Prodrug, das in der Leber zum wirksamen Trandolaprilat umgewandelt wird; dieses hemmt das Angiotensin-Converting-Enzym (ACE) im Blut und in den Geweben, sodass Angiotensin II und Aldosteron sinken und sich die Gefässe erweitern. Weil ACE auch Bradykinin abbaut, steigt dieses an – das erklärt Reizhusten und Angioödeme. Durch seine lange Bindung an das Enzym wirkt Trandolapril über 24 Stunden.","nebenwirkungen":{"haeufig":["Kopfschmerzen","Schwindel","Husten","Hypotonie (tiefer Blutdruck)","Asthenie (Schwächegefühl)"],"gelegentlich":["Herzklopfen","Hitzewallungen","Übelkeit, Durchfall, Bauchschmerzen","Juckreiz, Hautausschlag","Schlaflosigkeit, Schläfrigkeit, verminderte Libido","Rückenschmerzen, Muskelkrämpfe","Erektionsstörungen","Müdigkeit, periphere Ödeme, Brustschmerzen"],"selten":["Angioödem (Schwellung von Gesicht, Lippen, Zunge oder Rachen)","Herzinfarkt, Herzrhythmusstörungen, Herzinsuffizienz","Synkope (Ohnmacht), Schlaganfall","Anämie, Leukopenie","Hepatitis, erhöhtes Bilirubin","Hyponatriämie (Natriummangel)","Nierenversagen","Magen-Darm-Blutung, Gastritis"],"unbekannt":["Agranulozytose, Panzytopenie","Hyperkaliämie (erhöhtes Kalium)","AV-Block, Herzstillstand","Bronchospasmus","Pankreatitis, intestinales Angioödem","Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse","Haarausfall"]},"schwangerschaft":"Im 1. Drittel nicht empfohlen, im 2. und 3. Drittel kontraindiziert (Schädigung der kindlichen Nieren, Fruchtwassermangel, Verknöcherungsstörungen des Schädels). Bei Kinderwunsch oder Schwangerschaft auf ein anderes Mittel umstellen.","stillzeit":"Keine ausreichenden Daten; nicht empfohlen – besser untersuchte Alternativen wählen.","hinweise":["Bei Schwellungen von Gesicht, Lippen, Zunge oder Rachen oder bei Atemnot sofort den Notfall aufsuchen (Angioödem).","Trockener Reizhusten ist eine typische Nebenwirkung – ärztlich melden, nicht selbst absetzen.","Kalium und Nierenwerte regelmässig kontrollieren; kaliumhaltige Salzersatzmittel meiden.","Zu Beginn sind Schwindel und Benommenheit möglich – Vorsicht beim Autofahren."],"darreichung":["Kapseln","Retardtabletten (Kombination mit Verapamil)"]},"tranexamsaeure":{"wirkmechanismus":"Bremst den Abbau von Blutgerinnseln und hilft so, Blutungen zu stillen. Tranexamsäure ist ein synthetischer Abkömmling der Aminosäure Lysin. Es besetzt die Lysin-Bindungsstellen des Plasminogens und verhindert so, dass Plasminogen an Fibrin bindet und zu Plasmin aktiviert wird; in hohen Konzentrationen hemmt es auch Plasmin direkt. Dadurch bleibt das Fibringerinnsel länger stabil. Die Ausscheidung erfolgt überwiegend unverändert über die Nieren.","nebenwirkungen":{"haeufig":["Übelkeit, Erbrechen, Durchfall (dosisabhängig)"],"gelegentlich":["Allergische Hautentzündung"],"sehrSelten":["Überempfindlichkeitsreaktionen bis Anaphylaxie"],"unbekannt":["Thrombosen und Embolien (arteriell oder venös) an verschiedenen Stellen","Sehstörungen einschliesslich Farbsehstörungen, Verschluss von Netzhautgefässen","Krampfanfälle, besonders bei hohen intravenösen Dosen","Unwohlsein mit Blutdruckabfall, evtl. Bewusstlosigkeit bei zu rascher Injektion"]},"schwangerschaft":"Tranexamsäure passiert die Plazenta; bisherige Erfahrungen zeigen kein erhöhtes Fehlbildungsrisiko. Anwendung nur nach ärztlicher Abwägung, im ersten Drittel besonders zurückhaltend.","stillzeit":"Geht nur in geringen Mengen (etwa 1 % der Blutkonzentration) in die Muttermilch über; eine Wirkung beim Säugling ist unwahrscheinlich. Anwendung möglich.","hinweise":["Bei Sehstörungen sofort absetzen und augenärztlich abklären lassen.","Bei starker Monatsblutung nur während der Blutungstage einnehmen; bei unregelmässigen oder neu auftretenden Blutungen zuerst die Ursache abklären lassen.","Bei Anzeichen einer Thrombose (schmerzhafte Beinschwellung, Brustschmerz, Atemnot) sofort ärztliche Hilfe holen.","Die Injektion wird langsam intravenös gegeben; zu rasche Gabe kann einen Blutdruckabfall auslösen."],"darreichung":["Filmtabletten","Injektionslösung"]},"trastuzumab":{"wirkmechanismus":"Blockiert einen Wachstumsrezeptor, der auf manchen Krebszellen in grosser Zahl vorkommt. Trastuzumab ist ein humanisierter monoklonaler IgG1-Antikörper gegen den äusseren Teil des Rezeptors HER2 (ErbB2). Er hemmt die HER2-vermittelte Wachstumssignalisierung und markiert die Tumorzellen für die Zerstörung durch Immunzellen (antikörperabhängige zelluläre Zytotoxizität). Weil HER2 auch für die Erholung von Herzmuskelzellen wichtig ist, kann die Herzfunktion abnehmen.","nebenwirkungen":{"sehrHaeufig":["Infusionsreaktionen (Fieber, Schüttelfrost)","Infektionen, Nasen-Rachen-Entzündung","Neutropenie, febrile Neutropenie, Anämie, Thrombozytopenie (v. a. mit Chemotherapie)","Abnahme der Herzpumpfunktion, Herzklopfen, unregelmässiger Herzschlag","Kopfschmerzen, Schwindel, Kribbeln, Zittern, Geschmacksstörungen","Atemnot, Husten, pfeifende Atmung, Nasenbluten","Durchfall, Übelkeit, Erbrechen, Bauchschmerzen, Stomatitis","Hautausschlag, Haarausfall, Nagelveränderungen, Gelenk- und Muskelschmerzen, Müdigkeit"],"haeufig":["Herzschwäche (Herzinsuffizienz), Kardiomyopathie, supraventrikuläre Herzrhythmusstörungen","Blutdruckabfall","Lungenentzündung (Pneumonie), Pleuraerguss, Asthma","Leberzellschädigung","Überempfindlichkeitsreaktionen"],"gelegentlich":["Perikarderguss","Hörverlust"],"unbekannt":["Kardiogener Schock","Interstitielle Lungenerkrankung, Pneumonitis, Lungenfibrose, akutes Atemnotsyndrom","Anaphylaxie (schwere allergische Reaktion)","Oligohydramnion (zu wenig Fruchtwasser) bei Anwendung in der Schwangerschaft","Glomerulopathie, Nierenversagen"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Indikation: Fälle von Oligohydramnion (zu wenig Fruchtwasser) mit schweren Folgen für das Kind. Frauen müssen während und bis 7 Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung und bis 7 Monate nach der letzten Gabe nicht stillen.","hinweise":["Herzultraschall vor Beginn und etwa alle 3 Monate; Atemnot, Herzklopfen oder geschwollene Beine melden.","Intravenöse und subkutane Form, Biosimilars und Trastuzumab-Konjugate (z. B. Trastuzumab-Emtansin, Trastuzumab-Deruxtecan) sind nicht austauschbar – Namen genau prüfen.","Sichere Verhütung bis 7 Monate nach der letzten Gabe."],"darreichung":["Pulver zur Herstellung eines Infusionslösungskonzentrats","Injektionslösung zur subkutanen Anwendung"]},"trastuzumab-deruxtecan":{"wirkmechanismus":"Bringt ein starkes Zellgift gezielt in Krebszellen mit dem Oberflächenmerkmal HER2. Der Anti-HER2-Antikörper (gleiche Aminosäuresequenz wie Trastuzumab) ist über einen spaltbaren Linker an rund acht Moleküle Deruxtecan gebunden, einen Hemmer der Topoisomerase I. Nach Aufnahme in die Zelle wird das Zellgift freigesetzt, verursacht DNA-Schäden und den Zelltod. Da es durch Zellmembranen dringt, schädigt es auch benachbarte Tumorzellen (Bystander-Effekt) – deshalb wirkt es auch bei Tumoren mit wenig HER2.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Erbrechen","Müdigkeit","Haarausfall","Neutropenie, Anämie, Thrombozytopenie, Leukopenie","Appetitlosigkeit, Verstopfung, Durchfall","Erhöhte Leberwerte","Interstitielle Lungenerkrankung / Pneumonitis","Husten, Nasenbluten, Hypokaliämie (Kaliummangel)"],"haeufig":["Febrile Neutropenie (Fieber bei Mangel an weissen Blutkörperchen)","Verminderte Herzpumpfunktion (Abfall der Auswurffraktion)","Infusionsbedingte Reaktionen","Lungenentzündung (Pneumonie)","Verschwommenes Sehen","Trockene Haut, Juckreiz, Ausschlag","Geschmacksstörung, Schwindel"]},"schwangerschaft":"Nicht anwenden: Schädigung des Ungeborenen zu erwarten (Zellgift, Fruchtwassermangel durch Anti-HER2-Wirkung). Frauen verhüten während der Behandlung und 7 Monate danach, Männer mit Partnerin 4 Monate danach.","stillzeit":"Während der Behandlung und 7 Monate nach der letzten Dosis nicht stillen.","hinweise":["Neuen oder stärkeren Husten, Atemnot oder Fieber sofort melden (mögliche Lungenentzündung) – auch zwischen den Infusionen.","Vor jeder Infusion gibt es Mittel gegen Übelkeit; bei Bedarf auch für zu Hause.","Blutbild, Herzfunktion und Lunge werden regelmässig kontrolliert.","Nicht durch Trastuzumab oder Trastuzumab Emtansin ersetzbar."],"darreichung":["Pulver für ein Infusionskonzentrat"]},"trastuzumab-emtansin":{"wirkmechanismus":"Bringt ein Zellgift gezielt in HER2-positive Krebszellen. Trastuzumab Emtansin besteht aus dem Anti-HER2-Antikörper Trastuzumab, an den über einen stabilen Linker das Maytansin-Derivat DM1 gebunden ist. Nach Bindung an HER2 wird das Konjugat in die Zelle aufgenommen und abgebaut; das freigesetzte DM1 hemmt die Mikrotubuli und stoppt so die Zellteilung. Zusätzlich blockiert der Antikörperteil wie Trastuzumab die HER2-Signale und vermittelt eine antikörperabhängige zelluläre Zytotoxizität.","nebenwirkungen":{"sehrHaeufig":["Übelkeit, Verstopfung, Durchfall, Erbrechen","Müdigkeit, Fieber","Blutungen, vor allem Nasenbluten","Thrombozytopenie (Mangel an Blutplättchen), Anämie","Erhöhte Leberwerte (Transaminasen)","Muskel- und Gelenkschmerzen","Kopfschmerzen, Schlafstörungen","Periphere Neuropathie (Kribbeln, Taubheit)"],"haeufig":["Linksventrikuläre Dysfunktion (verminderte Pumpleistung des Herzens)","Neutropenie (Mangel an weissen Blutkörperchen)","Infusionsreaktionen, Überempfindlichkeit","Bluthochdruck","Geschmacksstörung, Schwindel","Verschwommenes Sehen, trockene Augen, Bindehautentzündung","Juckreiz, Nagelveränderungen"],"gelegentlich":["Pneumonitis (nicht-infektiöse Lungenentzündung)","Leberversagen, noduläre regenerative Hyperplasie, Pfortaderhochdruck"]},"schwangerschaft":"Nicht anwenden: Schädigung des Ungeborenen (Fruchtwassermangel durch den Trastuzumab-Anteil, Zellgift DM1). Frauen und Männer mit Partnerin verhüten während der Behandlung und 7 Monate danach zuverlässig.","stillzeit":"Während der Behandlung und 7 Monate nach der letzten Dosis nicht stillen.","hinweise":["Leberwerte, Blutbild (Blutplättchen) und Herzfunktion werden regelmässig kontrolliert.","Gelbsucht, dunklen Urin, Blutungen, blaue Flecken, Atemnot oder Husten sofort melden.","Andere Medikamente, auch Antimykotika oder Antibiotika, mit dem Behandlungsteam abstimmen – manche erhöhen den Spiegel.","Nicht durch Trastuzumab ersetzbar: Die beiden Mittel sind nicht austauschbar."],"darreichung":["Pulver für ein Infusionskonzentrat"]},"travoprost":{"wirkmechanismus":"Senkt den Augeninnendruck, indem mehr Kammerwasser aus dem Auge abfliesst. Travoprost ist ein Prodrug (Isopropylester), das in der Hornhaut zur aktiven freien Säure gespalten wird. Diese ist ein hochselektiver Agonist am Prostaglandin-FP-Rezeptor und steigert den uveoskleralen und den trabekulären Abfluss. Die Drucksenkung setzt nach etwa 2 Stunden ein und erreicht nach rund 12 Stunden ihr Maximum.","nebenwirkungen":{"sehrHaeufig":["Rötung des Auges (okuläre Hyperämie)"],"haeufig":["Dauerhaft dunklere Färbung der Iris (Regenbogenhaut)","Augenschmerzen, Augenbeschwerden, Augenreizung","Trockenes Auge","Juckreiz am Auge"],"gelegentlich":["Entzündungen im Auge (Uveitis, Iritis, Keratitis), Lichtempfindlichkeit","Verschwommenes Sehen, verminderte Sehschärfe","Wimpernwachstum, Lidrötung, Lidrandentzündung","Dunkelfärbung der Haut um das Auge, verstärkte Behaarung","Kopfschmerzen","Husten, verstopfte Nase"],"selten":["Herpes-simplex-Infektion des Auges","Schwindel, Geschmacksstörung","Herzklopfen, unregelmässiger oder verlangsamter Puls","Blutdruckveränderungen","Atemnot, Asthma","Allergische Hautreaktionen"],"unbekannt":["Makulaödem (Schwellung der Netzhautmitte)","Einsinken der Augen (Vertiefung der Lidfurche)","Verschlechterung eines Asthmas","Brustschmerzen, Herzrhythmusstörungen"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden, da Travoprost der Schwangerschaft und dem Ungeborenen schaden kann. Frauen im gebärfähigen Alter dürfen es nur mit zuverlässiger Verhütung anwenden.","stillzeit":"Nicht empfohlen: Travoprost geht im Tierversuch in die Milch über.","hinweise":["Einmal täglich (meist abends) eintropfen; nicht häufiger anwenden.","Nach dem Eintropfen die Augen 2 Minuten schliessen oder den inneren Augenwinkel zudrücken.","Kontaktlinsen frühestens 15 Minuten nach dem Eintropfen wieder einsetzen; zu anderen Augentropfen 5 Minuten Abstand halten."],"darreichung":["Augentropfen"]},"travoprost-timolol":{"wirkmechanismus":"Senkt den Augeninnendruck auf zwei Wegen: Es fördert den Abfluss des Kammerwassers und drosselt dessen Bildung. Travoprost ist ein Prodrug, das in der Hornhaut zur freien Säure gespalten wird; diese aktiviert den Prostaglandin-FP-Rezeptor und steigert vor allem den uveoskleralen Abfluss. Timolol blockiert nicht-selektiv die Beta-Rezeptoren im Ziliarkörper und vermindert so die Kammerwasserproduktion. Ein Teil des Timolols gelangt über die Nasenschleimhaut ins Blut und kann wie ein Betablocker in Tablettenform auf Herz und Bronchien wirken.","nebenwirkungen":{"sehrHaeufig":["Rötung des Auges (okuläre Hyperämie)"],"haeufig":["Punktförmige Hornhautentzündung (Keratitis punctata)","Augenschmerzen, Augenreizung, Juckreiz am Auge","Verschwommenes Sehen, Sehstörungen","Trockenes Auge"],"gelegentlich":["Bradykardie (verlangsamter Puls)","Blutdruckanstieg oder -abfall","Schwindel, Kopfschmerzen","Atemnot (Dyspnoe)","Entzündungen am Auge (Iritis, Konjunktivitis, Blepharitis), Lichtempfindlichkeit","Wimpernwachstum, verstärkte Behaarung und dunklere Haut um das Auge","Überempfindlichkeitsreaktionen"],"selten":["Bronchospasmus (Verkrampfung der Atemwege), Husten","Herzrhythmusstörungen","Hornhauterosion (oberflächlicher Hornhautschaden)","Erhöhte Leberwerte","Nesselsucht, Verlust von Wimpern (Madarose)"],"unbekannt":["Dauerhafte Braunfärbung der Iris (Regenbogenhaut)","Makulaödem (Schwellung der Netzhautmitte)","Asthma","Herzinsuffizienz, Herzklopfen, Brustschmerzen","Depression","Herabhängendes Oberlid (Ptosis)"]},"schwangerschaft":"Nur bei klarer Notwendigkeit anwenden: Travoprost hat im Tierversuch der Schwangerschaft geschadet, und Timolol kann bei Anwendung bis zur Geburt beim Neugeborenen Puls und Blutzucker senken. Frauen im gebärfähigen Alter sollen zuverlässig verhüten.","stillzeit":"Nicht empfohlen: beide Wirkstoffe gehen wahrscheinlich in die Muttermilch über; Timolol kann beim Säugling Herz und Atmung beeinträchtigen.","hinweise":["Nach dem Eintropfen die Augen 2 Minuten schliessen oder den inneren Augenwinkel leicht zudrücken – das vermindert die Aufnahme ins Blut und Nebenwirkungen an Herz und Lunge.","Kontaktlinsen vor dem Eintropfen herausnehmen und frühestens nach 15 Minuten wieder einsetzen; zu anderen Augentropfen mindestens 5 Minuten Abstand halten.","Überschüssige Tropfen von der Haut abwischen (Haarwuchs und Hautverfärbung möglich).","Unmittelbar nach dem Eintropfen kann die Sicht verschwommen sein – erst bei klarer Sicht Auto fahren."],"darreichung":["Augentropfen"]},"trazodon":{"wirkmechanismus":"Hellt die Stimmung auf, wirkt angstlösend und schlaffördernd. Trazodon blockiert vor allem Serotonin-5-HT2A-Rezeptoren und hemmt schwächer die Wiederaufnahme von Serotonin; zusätzlich blockiert es Alpha-1-Adrenozeptoren und Histamin-H1-Rezeptoren, was die beruhigende Wirkung und den möglichen Blutdruckabfall erklärt. Anticholinerge Wirkungen sind gering. Der Abbau erfolgt hauptsächlich über CYP3A4.","nebenwirkungen":{"unbekannt":["Schläfrigkeit, Müdigkeit, Schwindel, Kopfschmerzen","Mundtrockenheit, Übelkeit, Erbrechen","Blutdruckabfall beim Aufstehen (orthostatische Hypotonie), Ohnmacht","Herzrhythmusstörungen, QT-Verlängerung","Priapismus (schmerzhafte Dauererektion – Notfall)","Hyponatriämie (Natriummangel), Serotoninsyndrom, Krampfanfälle","Blutbildveränderungen (z. B. Agranulozytose, Thrombozytopenie), Leberfunktionsstörungen","Suizidgedanken und suizidales Verhalten"]},"schwangerschaft":"Begrenzte Erfahrungen; nur bei klarer Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme bis zur Geburt das Neugeborene auf Absetzsymptome beobachten.","stillzeit":"Trazodon geht in geringen Mengen in die Muttermilch über; Anwendung nur nach ärztlicher Abwägung.","hinweise":["Nach einer Mahlzeit einnehmen, die Hauptdosis vorzugsweise abends (macht müde).","Bei einer anhaltenden, schmerzhaften Erektion sofort ärztliche Hilfe holen (Notfall).","Kann die Fahrtüchtigkeit beeinträchtigen; Alkohol meiden.","Langsam aufstehen (Schwindel durch Blutdruckabfall); nicht abrupt absetzen."],"darreichung":["Tabletten","Retardtabletten"]},"tremelimumab":{"wirkmechanismus":"Löst eine natürliche Bremse des Immunsystems, damit es Krebszellen besser bekämpfen kann. Tremelimumab ist ein vollhumaner IgG2-Antikörper gegen CTLA-4, einen hemmenden Rezeptor auf T-Zellen. Durch die Blockade der Bindung an CD80 und CD86 werden T-Zellen stärker aktiviert und vermehren sich. Zusammen mit dem PD-L1-Hemmer Durvalumab ergänzen sich die Wirkungen; die Aktivierung kann sich aber auch gegen gesunde Organe richten (immunvermittelte Nebenwirkungen).","nebenwirkungen":{"sehrHaeufig":["Hypothyreose (Schilddrüsenunterfunktion)","Durchfall, Übelkeit, Bauchschmerzen","Hautausschlag, Juckreiz","Erhöhte Leberwerte","Husten","Fieber, Müdigkeit, Appetitlosigkeit","Ödeme (Wassereinlagerungen)"],"haeufig":["Pneumonitis (immunvermittelte Lungenentzündung)","Kolitis (Darmentzündung), Pankreatitis (Bauchspeicheldrüsenentzündung)","Hepatitis (immunvermittelte Leberentzündung)","Hyperthyreose (Schilddrüsenüberfunktion), Thyreoiditis","Nebennierenschwäche, Hypophysitis (Entzündung der Hirnanhangdrüse)","Infusionsbedingte Reaktionen","Lungenentzündung und Infekte der oberen Atemwege"],"gelegentlich":["Myokarditis (Herzmuskelentzündung)","Myositis (Muskelentzündung)","Nephritis (Nierenentzündung)","Typ-1-Diabetes","Myasthenia gravis (Muskelschwäche)","Immunthrombozytopenie"]},"schwangerschaft":"Die Blockade von CTLA-4 kann die Verträglichkeit der Schwangerschaft stören (Fehlgeburt); in der Schwangerschaft nicht empfohlen. Frauen im gebärfähigen Alter verhüten während und mindestens 3 Monate nach der letzten Dosis.","stillzeit":"Während und mindestens 3 Monate nach der letzten Dosis nicht stillen.","hinweise":["Neue oder zunehmende Beschwerden wie Durchfall, Husten, Atemnot, Gelbsucht, starke Müdigkeit, Kopfschmerzen oder Hautausschlag sofort melden – auch noch Monate nach Therapieende.","Schilddrüsen-, Leber- und Nierenwerte sowie der Blutzucker werden regelmässig kontrolliert.","Patientenkarte immer mitführen und bei jeder ärztlichen Behandlung vorzeigen."],"darreichung":["Konzentrat zur Herstellung einer Infusionslösung"]},"treosulfan":{"wirkmechanismus":"Zerstört blutbildende Zellen und Immunzellen, damit gespendete Stammzellen anwachsen können, und wirkt gegen Krebszellen. Treosulfan ist eine Vorstufe (Prodrug), die sich im Körper ohne Enzyme in reaktive Epoxide umwandelt. Diese alkylieren die DNA und vernetzen ihre Stränge, was die Zellteilung verhindert. Die Wirkung ist stark knochenmarkhemmend und immunsuppressiv.","nebenwirkungen":{"sehrHaeufig":["Infektionen (Bakterien, Viren, Pilze)","Knochenmarkhemmung (Panzytopenie), Fieber bei Neutropenie","Mundschleimhautentzündung (Stomatitis, Mukositis)","Übelkeit, Durchfall","Müdigkeit"],"haeufig":["Sepsis (Blutvergiftung)","Erbrechen, Bauchschmerzen","Appetitlosigkeit","Kopfschmerzen, Schwindel","Herzrhythmusstörungen","Bluthochdruck","Hautausschlag, Juckreiz, Haarausfall","Erhöhte Leber- und Bilirubinwerte"],"gelegentlich":["Lebervenenverschlusskrankheit (VOD/SOS)","Dunkelfärbung der Haut (Hyperpigmentierung)","Blutungen"],"unbekannt":["Krampfanfälle (v. a. bei Säuglingen)","Windeldermatitis und Hautschäden im Windelbereich bei Kleinkindern","Zweitkrebs","Unfruchtbarkeit"]},"schwangerschaft":"Kontraindiziert. Frauen und Männer müssen während und bis 6 Monate nach der Behandlung sicher verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Wird nur in spezialisierten Transplantationszentren als Infusion gegeben.","Sorgfältige Mundpflege zur Vorbeugung von Mundschleimhautentzündungen.","Bei Kleinkindern Windeln häufig wechseln und die Haut reinigen, da der Wirkstoff mit dem Urin ausgeschieden wird.","Vor Behandlungsbeginn Möglichkeiten zum Fruchtbarkeitserhalt besprechen."],"darreichung":["Pulver zur Herstellung einer Infusionslösung"]},"treprostinil":{"wirkmechanismus":"Erweitert die Blutgefässe der Lunge und entlastet so das rechte Herz. Treprostinil ist ein stabiles, lang wirkendes Analogon des körpereigenen Prostacyclins: Es aktiviert Prostacyclin-Rezeptoren der Gefässmuskulatur, steigert dort das cAMP und entspannt die Gefässe des Lungen- und des Körperkreislaufs. Zusätzlich hemmt es die Zusammenlagerung der Blutplättchen und wirkt dem Wuchern der Gefässwandzellen entgegen.","nebenwirkungen":{"sehrHaeufig":["Schmerzen und Reaktionen an der Infusionsstelle (Rötung, Schwellung, Verhärtung) bei Gabe unter die Haut","Blutungen oder Blutergüsse an der Infusionsstelle","Kopfschmerzen","Gefässerweiterung mit Hautrötung (Flush)","Durchfall, Übelkeit","Hautausschlag","Kieferschmerzen"],"haeufig":["Schwindel","Hypotonie (niedriger Blutdruck)","Erbrechen","Juckreiz","Wassereinlagerungen (Ödeme)","Muskel-, Gelenk- und Gliederschmerzen","Blutungen (z. B. Nasenbluten, Bluthusten, Magen-Darm-Blutung)"],"unbekannt":["Blutvergiftung (Sepsis) und Katheterinfektionen bei Gabe in die Vene","Venenentzündung (Thrombophlebitis)","Zellulitis (Hautentzündung) an der Infusionsstelle","Thrombozytopenie (Mangel an Blutplättchen)","Knochenschmerzen"]},"schwangerschaft":"Nur begrenzte Daten; nur anwenden, wenn der Nutzen für die Mutter das Risiko für das Kind überwiegt. Während der Behandlung zuverlässig verhüten.","stillzeit":"Nicht empfohlen, da unbekannt ist, ob Treprostinil in die Muttermilch übergeht.","hinweise":["Die Infusion nie eigenmächtig unterbrechen oder abrupt absetzen – Gefahr einer lebensbedrohlichen Verschlechterung; Ersatzpumpe und Material bereithalten.","Bei Fieber, Schüttelfrost oder Rötung an der Katheterstelle sofort ärztliche Hilfe holen.","Schwindel durch Blutdruckabfall möglich – Vorsicht beim Aufstehen und im Strassenverkehr."],"darreichung":["Infusionslösung (subkutan oder intravenös)"]},"tretinoin":{"wirkmechanismus":"Normalisiert die Verhornung der Haut und löst Mitesser; bei Leukämie lässt es unreife Krebszellen ausreifen. Tretinoin (all-trans-Retinsäure) bindet an Retinsäure-Rezeptoren (RAR) im Zellkern und steuert Gene für Zellwachstum und Zellreifung. In der Haut beschleunigt es die Erneuerung der Oberhaut, lockert verhornte Talgdrüsenausgänge und beugt neuen Komedonen vor. Bei der akuten Promyelozytenleukämie überwindet es in hoher Konzentration die Blockade durch das Fusionsprotein PML-RARα, sodass die leukämischen Promyelozyten zu reifen Granulozyten ausdifferenzieren.","nebenwirkungen":{"sehrHaeufig":["Hautreizung an der Auftragsstelle mit Rötung, Schuppung, Brennen und Trockenheit (Creme)","Differenzierungssyndrom (Retinsäure-Syndrom) bei der Leukämiebehandlung: Fieber, Atemnot, Wassereinlagerungen","Kopfschmerzen, erhöhter Hirndruck (Pseudotumor cerebri), Schwindel","Trockene Haut und Schleimhäute, Lippenentzündung (Cheilitis), Ausschlag, Haarausfall (Kapseln)","Übelkeit, Erbrechen, Bauchschmerzen (Kapseln)","Erhöhte Blutfette (Triglyceride, Cholesterin) und Leberwerte (Kapseln)","Knochen- und Brustschmerzen, Fieber, Frösteln (Kapseln)","Seh- und Hörstörungen, Depression, Verwirrtheit (Kapseln)"],"unbekannt":["Thrombosen in Venen und Arterien (z. B. Herzinfarkt, Schlaganfall)","Starker Anstieg der weissen Blutkörperchen (Hyperleukozytose)","Bauchspeicheldrüsenentzündung (Pankreatitis)","Sweet-Syndrom, Gefässentzündung (Vaskulitis), Erythema nodosum","Geschwüre im Genitalbereich","Erhöhtes Calcium im Blut (Hyperkalzämie)","Pigmentveränderungen und erhöhte Lichtempfindlichkeit der Haut (Creme)"]},"schwangerschaft":"Kontraindiziert, auch als Creme: Tretinoin kann schwere Fehlbildungen verursachen. Frauen im gebärfähigen Alter müssen während der Kapseltherapie und bis 1 Monat danach zuverlässig verhüten.","stillzeit":"Bei Einnahme der Kapseln kontraindiziert – vorher abstillen. Die Creme in der Stillzeit nur nach ärztlicher Abwägung und nie im Brustbereich anwenden.","hinweise":["Creme abends dünn auf die gereinigte, trockene Haut auftragen; die Akne bessert sich oft erst nach mehreren Wochen, anfangs ist eine Verschlechterung möglich.","Sonne, Solarium und UV-Licht meiden, tagsüber Sonnenschutz verwenden.","Kapseln mit einer Mahlzeit oder kurz danach unzerkaut einnehmen.","Bei Fieber, Atemnot, rascher Gewichtszunahme oder starken Kopfschmerzen während der Kapseltherapie sofort die behandelnde Ärztin oder den Arzt informieren."],"darreichung":["Creme","Gel (Kombination mit Clindamycin)","Weichkapseln"]},"triamcinolon":{"wirkmechanismus":"Hemmt Entzündungen und allergische Reaktionen stark. Triamcinolon ist ein synthetisches Glukokortikoid, etwa fünfmal stärker entzündungshemmend als Cortisol und praktisch ohne salzbindende (mineralokortikoide) Wirkung. Es bindet an den Glukokortikoid-Rezeptor und unterdrückt die Bildung von Entzündungsbotenstoffen sowie die Aktivität von Immunzellen. Als schwer lösliche Kristallsuspension (Triamcinolonacetonid) wird es nach der Injektion über Wochen freigesetzt; im Nasenspray wirkt es vor allem örtlich.","nebenwirkungen":{"haeufig":["Kopfschmerzen, Nasenbluten, Rachenentzündung (Nasenspray)"],"unbekannt":["Cushing-Syndrom, Unterdrückung der Nebennierenfunktion und Zyklusstörungen (auch nach einer einzelnen Depotspritze möglich)","Erhöhter Blutzucker, Wassereinlagerungen, Bluthochdruck, Kaliummangel","Osteoporose, Muskelschwäche, Magen-Darm-Geschwüre bei wiederholter Anwendung","Hautverdünnung, Dellen und helle Flecken an der Einstichstelle; Gesichtsrötung (Flush) nach der Injektion","Vorübergehende Gelenkschmerzen und -schwellung nach der Injektion, Gelenkinfektion, Knochennekrose","Erhöhte Infektanfälligkeit; psychische Veränderungen wie Schlafstörungen, Stimmungsschwankungen, Psychose","Grauer oder grüner Star, verschwommenes Sehen","Anaphylaktische Reaktionen; Reizung und Trockenheit der Nase, selten Perforation der Nasenscheidewand (Nasenspray)"]},"schwangerschaft":"Nur nach strenger ärztlicher Abwägung; Depotspritzen wirken lange und sollen in der Schwangerschaft möglichst vermieden werden. Nasenspray nur, wenn nötig (begrenzte Daten).","stillzeit":"Glukokortikoide gehen in die Muttermilch über: Depotinjektion nur nach ärztlicher Abwägung. Nasenspray in üblicher Dosis nach Abwägung möglich.","hinweise":["Die Kristallsuspension darf nur in Gelenke, Muskeln oder Gewebe gespritzt werden – nie in die Vene, in den Rückenmarkskanal oder ins Auge.","Nach einer Depotspritze wirkt das Kortison wochenlang: Bei Diabetes Blutzucker engmaschiger messen; vor Operationen die Spritze angeben.","HIV-Medikamente mit Ritonavir oder Cobicistat vor jeder Kortisonspritze unbedingt angeben.","Nasenspray: Die volle Wirkung setzt erst nach einigen Tagen ein; bei Kindern die niedrigste wirksame Dosis verwenden."],"darreichung":["Kristallsuspension zur Injektion (in Gelenk, Muskel oder Hautveränderung)","Nasenspray","Creme (Kombi mit Econazol)"]},"triazolam":{"wirkmechanismus":"Macht rasch schläfrig, indem es die Wirkung eines hemmenden Botenstoffs im Gehirn verstärkt. Triazolam bindet an die Benzodiazepin-Bindungsstelle des GABA-A-Rezeptors und verstärkt die hemmende Wirkung von GABA. Es wird in der Leber fast vollständig über CYP3A4 abgebaut und hat eine kurze Halbwertszeit von etwa 2–5 Stunden, weshalb Müdigkeit am Folgetag selten ist. Hemmstoffe von CYP3A4 können den Spiegel jedoch um ein Vielfaches erhöhen.","nebenwirkungen":{"sehrHaeufig":["Schläfrigkeit"],"haeufig":["Kopfschmerzen","Schwindel, Benommenheit","Koordinationsstörungen, Gangunsicherheit (Ataxie)","Nervosität","Übelkeit, Erbrechen"],"unbekannt":["Anterograde Amnesie (Erinnerungslücken für die Zeit nach der Einnahme)","Komplexe Verhaltensweisen im Schlaf (z. B. Schlafwandeln, Autofahren oder Essen ohne Erinnerung)","Paradoxe Reaktionen (Unruhe, Erregung, Aggressivität, Halluzinationen)","Verwirrtheit, besonders bei älteren Menschen","Rebound-Schlaflosigkeit und Angst am Tag","Atemdepression (Atemdämpfung)","Abhängigkeit und Entzugserscheinungen beim Absetzen","Überempfindlichkeitsreaktionen bis Anaphylaxie, Angioödem"]},"schwangerschaft":"Nicht anwenden. Bei Einnahme gegen Ende der Schwangerschaft drohen beim Neugeborenen Atemprobleme, Muskelschlaffheit, Unterkühlung und Entzugssymptome.","stillzeit":"Triazolam geht vermutlich in die Muttermilch über – nicht anwenden bzw. abstillen.","hinweise":["Unmittelbar vor dem Zubettgehen einnehmen und eine ungestörte Schlafdauer von 7–8 Stunden einplanen, sonst drohen Erinnerungslücken.","Keinen Alkohol und keinen Grapefruitsaft; vor Beginn neuer Medikamente Apotheke oder Arztpraxis fragen.","Nur kurzfristig einnehmen; nach längerer Einnahme schrittweise absetzen.","Bei Schlafwandeln oder nächtlichen Handlungen ohne Erinnerung die Einnahme beenden und ärztlich Rücksprache nehmen."],"darreichung":["Tabletten"]},"tribenosid":{"wirkmechanismus":"Lindert Schwellung und Entzündung der Hämorrhoiden. Tribenosid vermindert die Durchlässigkeit kleiner Blutgefässe und damit die Ödembildung, wirkt entzündungshemmend, indem es die Wirkung von Botenstoffen wie Histamin und Bradykinin abschwächt, und verbessert die Spannung der Venenwand. Das im Kombipräparat enthaltene Lidocain betäubt zusätzlich die Schleimhaut und lindert rasch Schmerz und Juckreiz.","nebenwirkungen":{"unbekannt":["Lokales Brennen, Juckreiz oder Wärmegefühl","Allergische Hautreaktionen (Rötung, Ausschlag)","Überempfindlichkeitsreaktionen mit Schwellungen (Angioödem)"]},"schwangerschaft":"Im ersten Schwangerschaftsdrittel nicht anwenden; danach nur nach ärztlicher Rücksprache.","stillzeit":"Nur nach Rücksprache mit Ärztin, Arzt oder Apotheke anwenden.","hinweise":["Morgens und abends, vorzugsweise nach dem Stuhlgang, anwenden.","Bei Blut im Stuhl oder fehlender Besserung nach einer Woche ärztlich abklären lassen."],"darreichung":["Rektalcreme","Zäpfchen"]},"trientin":{"wirkmechanismus":"Bindet überschüssiges Kupfer im Körper, damit es über den Urin ausgeschieden werden kann. Trientin ist ein Chelatbildner, der mit Kupfer einen stabilen, wasserlöslichen Komplex bildet, der über die Niere ausgeschieden wird. Zusätzlich vermindert es vermutlich die Aufnahme von Kupfer aus dem Darm. So sinkt die Kupferbelastung von Leber, Gehirn und anderen Organen.","nebenwirkungen":{"haeufig":["Übelkeit"],"gelegentlich":["Hautausschlag"],"unbekannt":["Duodenitis (Zwölffingerdarmentzündung)","Kolitis (Dickdarmentzündung), auch schwer"]},"schwangerschaft":"Die Behandlung des Morbus Wilson wird in der Regel weitergeführt; Anwendung nach sorgfältiger ärztlicher Abwägung mit Kontrolle der Kupferwerte (Kupfermangel kann das Ungeborene schädigen).","stillzeit":"Nicht bekannt, ob Trientin in die Muttermilch übergeht; über Stillen oder Behandlung wird nach ärztlicher Abwägung entschieden.","hinweise":["Nüchtern einnehmen: mindestens 1 Stunde vor oder 2 Stunden nach einer Mahlzeit und mit mindestens 1 Stunde Abstand zu anderen Medikamenten.","Die Behandlung ist lebenslang; regelmässige Kontrollen von Kupfer in Blut und Urin, Blutbild und Leberwerten.","Trientin-Präparate mit verschiedenen Salzformen sind nicht direkt austauschbar (unterschiedliche Dosierungsangaben)."],"darreichung":["Filmtabletten"]},"trifaroten":{"wirkmechanismus":"Normalisiert die Verhornung der Haut und beugt verstopften Poren vor. Trifaroten ist ein Retinoid der neueren Generation, das selektiv den Retinsäure-Rezeptor gamma (RAR-γ) aktiviert, den in der Oberhaut häufigsten Retinsäure-Rezeptor. Dadurch werden Gene für Zellreifung und Entzündung reguliert: Die übermässige Verhornung der Talgdrüsenausgänge geht zurück, Komedonen lösen sich und entzündliche Läsionen nehmen ab. Nur sehr geringe Mengen gelangen ins Blut und werden in der Leber rasch abgebaut.","nebenwirkungen":{"haeufig":["Reizung an der Auftragsstelle (Rötung, Schuppung, Trockenheit, Brennen, Stechen)","Juckreiz an der Auftragsstelle","Sonnenbrand"],"gelegentlich":["Schmerzen an der Auftragsstelle","Hautverfärbung oder Hautabschürfung (Erosion) an der Auftragsstelle","Verschlechterung der Akne","Allergische Dermatitis","Hautausschlag, Schwellung an der Auftragsstelle"],"selten":["Nesselsucht (Urtikaria)","Bläschen an der Auftragsstelle","Lippenentzündung (Cheilitis)","Schwellung der Augenlider","Dunklere Hautstellen (Hyperpigmentierung)","Hautrisse (Fissuren)"]},"schwangerschaft":"Kontraindiziert. Retinoide zum Einnehmen verursachen Fehlbildungen; auch die Creme darf in der Schwangerschaft und bei Kinderwunsch nicht verwendet werden. Bei Eintritt einer Schwangerschaft die Behandlung sofort beenden.","stillzeit":"Ein Risiko für den Säugling ist nicht auszuschliessen – nur nach ärztlicher Abwägung und nie im Brustbereich auftragen.","hinweise":["Einmal täglich abends dünn auf die saubere, trockene Haut auftragen; danach die Hände waschen.","Von Beginn an eine feuchtigkeitsspendende Pflege und tagsüber Sonnenschutz verwenden.","Bei starker Reizung nach ärztlicher Rücksprache seltener anwenden oder pausieren.","Keine Haarentfernung mit Wachs und keine Peelings an den behandelten Stellen."],"darreichung":["Creme"]},"trifluridin-tipiracil":{"wirkmechanismus":"Stört die Erbsubstanz von Krebszellen und hemmt so ihr Wachstum. Trifluridin ist ein Thymidin-Analogon, das nach Aktivierung direkt in die DNA eingebaut wird und deren Funktion stört. Tipiracil hemmt das Enzym Thymidinphosphorylase, das Trifluridin sonst rasch abbauen würde, und erhöht so dessen Konzentration im Blut.","nebenwirkungen":{"sehrHaeufig":["Neutropenie, Leukopenie, Anämie, Thrombozytopenie","Appetitlosigkeit","Durchfall, Übelkeit, Erbrechen","Müdigkeit"],"haeufig":["Infektionen der Atemwege und andere Infektionen, febrile Neutropenie","Geschmacksstörungen, periphere Neuropathie (Kribbeln, Taubheitsgefühl)","Atemnot","Bauchschmerzen, Verstopfung, Mundschleimhautentzündung","Hand-Fuss-Syndrom, Hautausschlag, Haarausfall, Juckreiz","Eiweiss im Urin (Proteinurie)","Fieber, Ödeme, Schleimhautentzündung","Erhöhte Leberwerte und Bilirubin, Gewichtsabnahme"],"unbekannt":["Schwere Infektionen bis zum septischen Schock","Interstitielle Lungenerkrankung"]},"schwangerschaft":"Nicht anwenden, ausser bei zwingender Notwendigkeit; im Tierversuch fruchtschädigend. Frauen und Männer müssen während der Behandlung und bis 6 Monate danach zuverlässig verhüten.","stillzeit":"Während der Behandlung nicht stillen.","hinweise":["Zweimal täglich innerhalb einer Stunde nach dem Frühstück und dem Abendessen mit Wasser einnehmen; Einnahme- und Pausentage genau einhalten.","Nach dem Berühren der Tabletten die Hände waschen.","Blutbild vor jedem Zyklus und an Tag 15 kontrollieren; Fieber oder Infektzeichen sofort melden.","Müdigkeit oder Schwindel können die Fahrtüchtigkeit beeinträchtigen."],"darreichung":["Filmtabletten"]},"trimebutin":{"wirkmechanismus":"Reguliert die Darmbewegungen: Ist der Darm zu träge, regt Trimebutin ihn an, ist er verkrampft, beruhigt es ihn. Trimebutin wirkt als schwacher Agonist an den Opioidrezeptoren (μ, κ und δ) des Darmnervensystems und beeinflusst die Freisetzung von Darmhormonen wie Motilin. Zusätzlich hemmt es Ionenkanäle der glatten Muskulatur und wirkt örtlich betäubend, was die Schmerzempfindlichkeit des Darms senkt. Der Hauptmetabolit N-Desmethyltrimebutin ist ebenfalls wirksam.","nebenwirkungen":{"unbekannt":["Hautreaktionen (Ausschlag, Rötung, Juckreiz, Nesselsucht)","Überempfindlichkeitsreaktionen","Magen-Darm-Beschwerden wie Übelkeit, Mundtrockenheit, Durchfall oder Verstopfung","Müdigkeit, Schwindel, Kopfschmerzen"]},"schwangerschaft":"Keine ausreichenden Daten; vorsichtshalber nicht anwenden, besonders im ersten Schwangerschaftsdrittel.","stillzeit":"Keine Daten zum Übergang in die Muttermilch; während der Stillzeit vorsichtshalber nicht anwenden.","hinweise":["Klinisch bedeutsame Wechselwirkungen mit anderen Arzneimitteln sind nicht bekannt.","Neu aufgetretene Bauchbeschwerden, Blut im Stuhl, ungewollter Gewichtsverlust oder Fieber gehören ärztlich abgeklärt, bevor sie als Reizdarm behandelt werden."],"darreichung":["Filmtabletten"]},"trimipramin":{"wirkmechanismus":"Hellt die Stimmung auf und wirkt ausgeprägt beruhigend und schlaffördernd. Im Unterschied zu anderen Trizyklika hemmt Trimipramin die Wiederaufnahme von Serotonin und Noradrenalin nur schwach; im Vordergrund steht die Blockade von Histamin-H1-, Serotonin-5-HT2-, Alpha-1- und Dopamin-D2-Rezeptoren. Die Blockade von Muskarinrezeptoren (anticholinerge Wirkung) erklärt Nebenwirkungen wie Mundtrockenheit und Verstopfung. Die schlaffördernde Wirkung setzt rasch ein, die antidepressive Wirkung entwickelt sich über 2–4 Wochen.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit","Müdigkeit, Benommenheit","Schwindel, Blutdruckabfall beim Aufstehen (orthostatische Hypotonie)","Verstopfung","Gewichtszunahme","Herzklopfen, Herzrasen (Tachykardie)","Zittern (Tremor)","Vermehrtes Schwitzen"],"haeufig":["Sehstörungen (Akkommodationsstörungen)","Störungen beim Wasserlassen","Innere Unruhe, Kopfschmerzen","Durstgefühl","Libido- und Potenzstörungen","Übelkeit"],"gelegentlich":["Harnverhalt","Verwirrtheit und Delir (vor allem bei älteren Menschen)","Hautausschlag, Juckreiz","Krampfanfälle","Wassereinlagerungen (Ödeme)"],"selten":["Herzrhythmus- und Reizleitungsstörungen","Darmlähmung (paralytischer Ileus)","Leberfunktionsstörungen, Gelbsucht","Milchfluss (Galaktorrhö)","Kreislaufkollaps"],"sehrSelten":["Agranulozytose und andere Blutbildveränderungen","Akutes Glaukom"],"unbekannt":["QT-Verlängerung, Torsade de pointes","Hyponatriämie (Natriummangel)","Suizidgedanken und suizidales Verhalten","Absetzsymptome"]},"schwangerschaft":"Nur bei zwingender Notwendigkeit nach ärztlicher Abwägung. Bei Einnahme bis zur Geburt sind beim Neugeborenen Entzugs- und Anpassungsstörungen möglich.","stillzeit":"Trimipramin geht in die Muttermilch über; während der Behandlung soll nicht gestillt werden.","hinweise":["Wegen der dämpfenden Wirkung die Hauptdosis am Abend einnehmen.","Kann die Fahrtüchtigkeit stark beeinträchtigen; Alkohol meiden.","Nicht abrupt absetzen, sondern schrittweise nach ärztlicher Anleitung reduzieren.","Regelmässig EKG, Blutdruck, Blutbild und Leberwerte kontrollieren lassen."],"darreichung":["Tabletten","Tropfen"]},"triptorelin":{"wirkmechanismus":"Schaltet über die Hirnanhangsdrüse die Bildung von Geschlechtshormonen ab. Triptorelin ist ein synthetisches GnRH-Analogon mit stärkerer Wirkung als das natürliche Hormon. Nach einem kurzen Anstieg von LH, FSH und Sexualhormonen führt die Dauerstimulation zur Desensibilisierung der Hypophyse, sodass Testosteron bzw. Östradiol auf Kastrationsniveau sinken. Bei der künstlichen Befruchtung verhindert dies einen vorzeitigen Eisprung.","nebenwirkungen":{"sehrHaeufig":["Hitzewallungen","Vermehrtes Schwitzen","Libidoabnahme, Erektionsstörungen","Schwäche","Kopfschmerzen und Scheidentrockenheit (bei Frauen)"],"haeufig":["Reaktionen an der Injektionsstelle","Gelenk-, Muskel- und Knochenschmerzen","Übelkeit","Stimmungsschwankungen, Depression, Schlafstörungen","Gewichtszunahme","Schwindel","Ovarielles Überstimulationssyndrom (bei künstlicher Befruchtung)","Schmierblutungen (bei Kindern und Frauen zu Beginn)"],"gelegentlich":["Erhöhter Blutdruck, Herzklopfen","Erhöhte Leberwerte","Sehstörungen"],"unbekannt":["Anaphylaxie, Angioödem","QT-Verlängerung","Abnahme der Knochendichte","Hypophysenapoplexie (Einblutung in einen Hypophysentumor)","Krampfanfälle"]},"schwangerschaft":"Kontraindiziert. Vor Beginn Schwangerschaft ausschliessen; während der Behandlung eine nicht hormonelle Verhütungsmethode anwenden (z. B. Kondom).","stillzeit":"Kontraindiziert.","hinweise":["In den ersten Wochen können Beschwerden vorübergehend zunehmen (Flare).","Termine für die Depotspritze genau einhalten.","Bei Langzeitbehandlung Knochendichte und Blutzucker kontrollieren."],"darreichung":["Pulver und Lösungsmittel zur Herstellung einer Depot-Injektionssuspension","Injektionslösung (Fertigspritze)"]},"tropicamid":{"wirkmechanismus":"Erweitert die Pupille für einige Stunden. Tropicamid blockiert Muskarinrezeptoren am Pupillenschliessmuskel und – schwächer – am Ziliarmuskel und hebt so die Wirkung von Acetylcholin auf. Die Wirkung beginnt nach etwa 15–30 Minuten und klingt meist innerhalb von etwa 6 Stunden wieder ab; damit wirkt es deutlich kürzer als Atropin oder Cyclopentolat.","nebenwirkungen":{"unbekannt":["Vorübergehendes Brennen oder Stechen beim Eintropfen","Verschwommenes Sehen und Blendempfindlichkeit (erwartete Wirkung)","Anstieg des Augeninnendrucks, akuter Glaukomanfall bei engem Kammerwinkel","Kopfschmerzen, Mundtrockenheit, Herzrasen, Hautrötung","Zentralnervöse Störungen bei Kindern (Verhaltensänderungen, Verwirrtheit)","Kreislaufkollaps, vor allem bei Kindern (Einzelfälle)","Allergische Reaktionen"]},"schwangerschaft":"Nur nach ärztlicher Abwägung anwenden; Daten zur Anwendung in der Schwangerschaft fehlen.","stillzeit":"Nur nach ärztlicher Abwägung anwenden; Daten zur Stillzeit fehlen.","hinweise":["Bis das Sehen wieder normal ist (meist einige Stunden), nicht Auto fahren und keine Maschinen bedienen.","Eine Sonnenbrille schützt vor Blendung.","Bei Kindern nach dem Eintropfen den inneren Augenwinkel 1–2 Minuten zudrücken – das verringert die Aufnahme in den Körper.","Bei Augenschmerzen, Rötung und Sehverschlechterung (möglicher Glaukomanfall) sofort ärztliche Hilfe holen."],"darreichung":["Augentropfen"]},"trospium":{"wirkmechanismus":"Entspannt den überaktiven Blasenmuskel und verringert so Harndrang und unwillkürlichen Urinverlust. Trospium blockiert als Antagonist die Muskarinrezeptoren der glatten Muskulatur, besonders am Blasenmuskel (Detrusor). Als quartäre Ammoniumverbindung ist es dauerhaft geladen und überwindet die Blut-Hirn-Schranke kaum, was zentrale Nebenwirkungen wie Verwirrtheit selten macht. Es wird kaum über Cytochrom-P450-Enzyme abgebaut und überwiegend unverändert über die Nieren (aktive tubuläre Sekretion) ausgeschieden.","nebenwirkungen":{"sehrHaeufig":["Mundtrockenheit"],"haeufig":["Verdauungsbeschwerden (Dyspepsie)","Verstopfung","Bauchschmerzen","Übelkeit"],"gelegentlich":["Herzrasen (Tachykardie)","Durchfall","Blähungen"],"selten":["Sehstörungen (Akkommodationsstörungen)","Erschwertes Wasserlassen, Restharnbildung","Hautausschlag","Tachyarrhythmie","Atemnot","Schwäche","Leichter bis mässiger Anstieg der Leberwerte (Transaminasen)"],"sehrSelten":["Harnverhalt","Kopfschmerzen, Schwindel","Muskel- und Gelenkschmerzen","Angioödem","Anaphylaxie (schwere allergische Reaktion)"],"unbekannt":["Stevens-Johnson-Syndrom, toxische epidermale Nekrolyse (schwere Hautreaktionen)","Halluzinationen, Verwirrtheit, Unruhe"]},"schwangerschaft":"Nur nach strenger ärztlicher Nutzen-Risiko-Abwägung – es liegen keine ausreichenden Erfahrungen am Menschen vor.","stillzeit":"Nicht empfohlen – im Tierversuch ging Trospium in geringen Mengen in die Milch über.","hinweise":["Vor einer Mahlzeit auf nüchternen Magen mit Wasser einnehmen – Nahrung vermindert die Aufnahme deutlich.","Sehstörungen können die Fahrtüchtigkeit beeinträchtigen.","Die Notwendigkeit der Behandlung nach einigen Monaten ärztlich überprüfen lassen."],"darreichung":["Dragées (überzogene Tabletten)"]},"tuberkulin":{"wirkmechanismus":"Zeigt an, ob das Immunsystem schon einmal Kontakt mit Tuberkulose-Bakterien hatte. Tuberkulin PPD ist ein gereinigtes Eiweissgemisch aus abgetöteten Kulturen von Mycobacterium tuberculosis und wird in die Haut gespritzt. Bei Personen, deren T-Lymphozyten durch eine Infektion oder eine BCG-Impfung sensibilisiert sind, entsteht eine Überempfindlichkeitsreaktion vom verzögerten Typ mit einer tastbaren Verhärtung (Induration), die nach 48–72 Stunden am deutlichsten ist. Der Test unterscheidet nicht zwischen latenter Infektion, aktiver Erkrankung und früherer Impfung.","nebenwirkungen":{"unbekannt":["Starke Reaktion an der Einstichstelle mit Bläschen, Geschwür oder Gewebsuntergang (Nekrose)","Schmerzen, Juckreiz und Bluterguss an der Einstichstelle","Lymphknotenschwellung, Entzündung von Lymphbahnen (Lymphangitis)","Fieber, Kopfschmerzen","Allergische Reaktionen bis zur Anaphylaxie (schwere allergische Reaktion)"]},"schwangerschaft":"Kann angewendet werden; schädliche Wirkungen auf das Ungeborene sind nicht bekannt.","stillzeit":"Kann angewendet werden.","hinweise":["Die Reaktion muss nach 48–72 Stunden von einer Fachperson abgelesen werden; gemessen wird die tastbare Verhärtung, nicht die Rötung.","Die Einstichstelle nicht kratzen, reiben oder abdecken.","Ein positiver Test bedeutet nicht unbedingt eine aktive Tuberkulose; weitere Abklärungen (z. B. Röntgenbild) entscheiden über eine Behandlung."],"darreichung":["Injektionslösung zur Injektion in die Haut (intradermal)"]},"tucatinib":{"wirkmechanismus":"Blockiert Wachstumssignale in Brustkrebszellen mit zu vielen HER2-Rezeptoren. Tucatinib hemmt reversibel und sehr selektiv die Tyrosinkinase von HER2, kaum aber EGFR, und unterbricht so die Signalwege MAPK und AKT. Es gelangt auch ins Gehirn und wirkt bei Hirnmetastasen; mit Trastuzumab wird HER2 zusätzlich von aussen blockiert.","nebenwirkungen":{"sehrHaeufig":["Durchfall, Übelkeit, Erbrechen, Stomatitis","Hand-Fuss-Syndrom (schmerzhafte Rötung von Händen und Füssen)","Hautausschlag","Erhöhte Leberwerte","Erhöhtes Kreatinin","Müdigkeit, Kopfschmerzen","Gelenkschmerzen, Nasenbluten","Appetit- und Gewichtsabnahme"]},"schwangerschaft":"Nicht anwenden (im Tierversuch fruchtschädigend). Frauen und Männer müssen während und bis mindestens 1 Woche nach der Behandlung zuverlässig verhüten; die Vorgaben zu Trastuzumab und Capecitabin gelten zusätzlich.","stillzeit":"Während der Behandlung und bis 1 Woche nach der letzten Dosis nicht stillen.","hinweise":["Zweimal täglich im Abstand von etwa 12 Stunden einnehmen, mit oder ohne Essen; Tabletten ganz schlucken.","Starker Durchfall, Gelbfärbung der Haut oder dunkler Urin sofort ärztlich melden.","Leberwerte vor und regelmässig während der Behandlung kontrollieren lassen."],"darreichung":["Filmtabletten"]},"typhus-impfstoff":{"wirkmechanismus":"Regt das Immunsystem an, Abwehrstoffe gegen Typhusbakterien zu bilden. Vivotif enthält den lebenden, abgeschwächten Salmonella-Typhi-Stamm Ty21a, der sich kurz im Darm ansiedelt, ohne krank zu machen, und dort eine lokale und allgemeine Immunantwort auslöst. Typhim Vi enthält das gereinigte Vi-Kapselpolysaccharid der Bakterien, gegen das Antikörper gebildet werden. Beide Impfstoffe schützen nicht vollständig und kaum gegen Paratyphus.","nebenwirkungen":{"sehrHaeufig":["Schmerzen, Rötung und Verhärtung an der Einstichstelle (Typhim Vi)"],"unbekannt":["Bauchschmerzen, Übelkeit, Durchfall, Erbrechen (Kapseln)","Fieber, Kopfschmerzen, Müdigkeit, Unwohlsein","Muskel- und Gelenkschmerzen","Hautausschlag, Juckreiz, Nesselsucht","Allergische Reaktionen bis Anaphylaxie","Kribbeln (Parästhesien), Schwindel"]},"schwangerschaft":"Kapseln (Lebendimpfstoff) in der Schwangerschaft nicht empfohlen. Typhim Vi nur bei klarem Ansteckungsrisiko nach ärztlicher Abwägung.","stillzeit":"Keine ausreichenden Daten; Impfung nur nach ärztlicher Abwägung.","hinweise":["Kapseln im Kühlschrank lagern und nach Anleitung unzerkaut etwa 1 Stunde vor einer Mahlzeit mit einer kühlen Flüssigkeit schlucken; Einnahmeschema vollständig einhalten.","Impfung rechtzeitig vor der Abreise abschliessen (Kapseln mindestens 1 Woche, Spritze mindestens 2 Wochen vorher).","Auch geimpft gilt: nur Gekochtes, Geschältes und abgekochtes oder abgepacktes Wasser."],"darreichung":["Magensaftresistente Kapseln (Vivotif)","Injektionslösung in Fertigspritze (Typhim Vi)"]}});
